{
  "name": "FastFood Manager Pro",
  "description": "Una aplicación integral para la gestión de pedidos de comida rápida, optimizada para dispositivos móviles con asistente inteligente de IA para sugerencias de menú y análisis de ventas."
}

export interface FoodItem {
  id: string;
  name: string;
  price: number;
  category: 'Burgers' | 'Pizzas' | 'Drinks' | 'Sides' | 'Desserts';
  image: string;
  description: string;
}

export interface OrderItem extends FoodItem {
  quantity: number;
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PREPARING = 'PREPARING',
  READY = 'READY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export interface Order {
  id: string;
  items: OrderItem[];
  total: number;
  status: OrderStatus;
  customerName: string;
  createdAt: number;
  tableNumber?: string;
}

export type ViewType = 'menu' | 'orders' | 'kitchen' | 'stats' | 'ai';

import { FoodItem } from './types';

export const INITIAL_MENU: FoodItem[] = [
  {
    id: 'b1',
    name: 'Burger Clásica',
    price: 8.50,
    category: 'Burgers',
    description: 'Carne 100% res, queso cheddar, lechuga y tomate.',
    image: 'https://picsum.photos/seed/burger1/400/300'
  },
  {
    id: 'b2',
    name: 'Burger Doble Bacon',
    price: 12.00,
    category: 'Burgers',
    description: 'Doble carne, extra bacon crujiente y salsa BBQ.',
    image: 'https://picsum.photos/seed/burger2/400/300'
  },
  {
    id: 'p1',
    name: 'Pizza Pepperoni',
    price: 15.00,
    category: 'Pizzas',
    description: 'Masa artesanal, mozzarella y pepperoni premium.',
    image: 'https://picsum.photos/seed/pizza1/400/300'
  },
  {
    id: 's1',
    name: 'Papas Fritas XL',
    price: 4.50,
    category: 'Sides',
    description: 'Papas cortadas a mano con sal marina.',
    image: 'https://picsum.photos/seed/fries1/400/300'
  },
  {
    id: 'd1',
    name: 'Coca Cola 500ml',
    price: 2.50,
    category: 'Drinks',
    description: 'Refresco bien frío.',
    image: 'https://picsum.photos/seed/drink1/400/300'
  },
  {
    id: 'de1',
    name: 'Brownie con Helado',
    price: 6.00,
    category: 'Desserts',
    description: 'Brownie tibio con helado de vainilla.',
    image: 'https://picsum.photos/seed/dessert1/400/300'
  }
];

export const CATEGORIES = ['Burgers', 'Pizzas', 'Sides', 'Drinks', 'Desserts'] as const;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getSmartSuggestions = async (currentMenu: any[], currentOrders: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analiza el siguiente menú y pedidos actuales para dar 3 consejos estratégicos de ventas o gestión para hoy.
      Menú: ${JSON.stringify(currentMenu)}
      Pedidos Recientes: ${JSON.stringify(currentOrders)}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              impact: { type: Type.STRING, description: 'Alta, Media o Baja' }
            },
            required: ['title', 'description', 'impact']
          }
        }
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (error) {
    console.error("Error in Gemini service:", error);
    return [];
  }
};

export const generateUpsellSuggestion = async (cartItems: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Basado en estos productos en el carrito: ${JSON.stringify(cartItems)}, sugiere un producto adicional que combine bien para aumentar el ticket promedio. Responde solo con el nombre del producto y una breve razón.`,
    });
    return response.text;
  } catch (error) {
    return null;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  ShoppingBag, 
  ClipboardList, 
  ChefHat, 
  BarChart3, 
  Sparkles, 
  Plus, 
  Minus, 
  Trash2, 
  CheckCircle2, 
  Clock,
  ChevronRight,
  Menu as MenuIcon,
  X
} from 'lucide-react';
import { FoodItem, Order, OrderItem, OrderStatus, ViewType } from './types';
import { INITIAL_MENU, CATEGORIES } from './constants';
import { getSmartSuggestions, generateUpsellSuggestion } from './geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('menu');
  const [menu, setMenu] = useState<FoodItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);
  const [upsellHint, setUpsellHint] = useState<string | null>(null);

  // Cart logic
  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = (itemId: string) => {
    setCart(prev => prev.filter(i => i.id !== itemId));
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        const newQty = Math.max(1, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const placeOrder = () => {
    if (cart.length === 0) return;
    const newOrder: Order = {
      id: `ORD-${Date.now()}`,
      items: [...cart],
      total: cartTotal,
      status: OrderStatus.PENDING,
      customerName: customerName || 'Cliente Genérico',
      tableNumber: tableNumber,
      createdAt: Date.now()
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setCustomerName('');
    setTableNumber('');
    setIsCartOpen(false);
    setActiveView('orders');
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  // AI Logic triggers
  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    const suggestions = await getSmartSuggestions(menu, orders);
    setAiSuggestions(suggestions);
    setLoadingAI(false);
  };

  useEffect(() => {
    if (cart.length > 0 && cart.length % 2 === 0) {
      generateUpsellSuggestion(cart).then(hint => setUpsellHint(hint));
    } else {
      setUpsellHint(null);
    }
  }, [cart]);

  // Statistics
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => {
      o.items.forEach(item => {
        data[item.name] = (data[item.name] || 0) + item.quantity;
      });
    });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);

  return (
    <div className="min-h-screen pb-20 md:pb-0 md:pl-20 flex flex-col bg-slate-50 text-slate-900">

      {/* Desktop Sidebar / Mobile Bottom Nav */}
      <nav className="fixed bottom-0 left-0 right-0 md:top-0 md:bottom-0 md:w-20 bg-white border-t md:border-t-0 md:border-r border-slate-200 z-50 flex md:flex-col justify-around md:justify-center items-center py-2 md:space-y-8">
        <NavButton icon={<ShoppingBag />} active={activeView === 'menu'} onClick={() => setActiveView('menu')} label="Menú" />
        <NavButton icon={<ClipboardList />} active={activeView === 'orders'} onClick={() => setActiveView('orders')} label="Pedidos" />
        <NavButton icon={<ChefHat />} active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} label="Cocina" />
        <NavButton icon={<BarChart3 />} active={activeView === 'stats'} onClick={() => setActiveView('stats')} label="Stats" />
        <NavButton icon={<Sparkles className="text-indigo-500" />} active={activeView === 'ai'} onClick={() => setActiveView('ai')} label="IA" />
      </nav>

      {/* Header */}
      <header className="sticky top-0 bg-white/80 backdrop-blur-md border-b border-slate-200 px-6 py-4 flex justify-between items-center z-40">
        <div className="flex items-center gap-2">
          <div className="bg-orange-500 p-2 rounded-lg">
            <ShoppingBag className="text-white w-6 h-6" />
          </div>
          <h1 className="text-xl font-bold tracking-tight">FastFood<span className="text-orange-500">Pro</span></h1>
        </div>

        {activeView === 'menu' && (
          <button 
            onClick={() => setIsCartOpen(true)}
            className="relative p-2 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"
          >
            <ShoppingBag className="w-6 h-6" />
            {cart.length > 0 && (
              <span className="absolute -top-1 -right-1 bg-orange-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">
                {cart.reduce((a, b) => a + b.quantity, 0)}
              </span>
            )}
          </button>
        )}
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-8 max-w-6xl mx-auto w-full">
        {activeView === 'menu' && (
          <div className="space-y-8">
            <div className="flex flex-wrap gap-2">
              <button className="px-4 py-2 rounded-full bg-orange-500 text-white font-medium shadow-sm">Todos</button>
              {CATEGORIES.map(cat => (
                <button key={cat} className="px-4 py-2 rounded-full bg-white border border-slate-200 text-slate-600 font-medium hover:bg-slate-50 transition-colors">
                  {cat}
                </button>
              ))}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {menu.map(item => (
                <div key={item.id} className="bg-white rounded-2xl border border-slate-200 overflow-hidden hover:shadow-lg transition-shadow group">
                  <div className="relative h-48 overflow-hidden">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" />
                    <div className="absolute top-3 right-3 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-sm font-bold text-orange-600">
                      ${item.price.toFixed(2)}
                    </div>
                  </div>
                  <div className="p-5">
                    <h3 className="text-lg font-bold mb-1">{item.name}</h3>
                    <p className="text-slate-500 text-sm line-clamp-2 mb-4">{item.description}</p>
                    <button 
                      onClick={() => addToCart(item)}
                      className="w-full py-2.5 bg-slate-900 text-white rounded-xl font-semibold flex items-center justify-center gap-2 hover:bg-slate-800 transition-colors"
                    >
                      <Plus className="w-4 h-4" /> Agregar al Pedido
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeView === 'orders' && (
          <div className="space-y-6">
            <h2 className="text-2xl font-bold">Listado de Pedidos</h2>
            {orders.length === 0 ? (
              <div className="bg-white p-12 rounded-3xl border border-dashed border-slate-300 text-center space-y-4">
                <ClipboardList className="w-12 h-12 text-slate-300 mx-auto" />
                <p className="text-slate-500">No hay pedidos registrados aún.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-bold text-lg">{order.id}</span>
                        <StatusBadge status={order.status} />
                      </div>
                      <p className="text-slate-500 text-sm">
                        {order.customerName} {order.tableNumber ? `• Mesa ${order.tableNumber}` : ''} • {new Date(order.createdAt).toLocaleTimeString()}
                      </p>
                      <div className="mt-2 text-sm text-slate-700">
                        {order.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                      </div>
                    </div>
                    <div className="flex items-center justify-between md:justify-end gap-6 border-t md:border-t-0 pt-4 md:pt-0">
                      <div className="text-right">
                        <p className="text-xs text-slate-400 uppercase font-bold tracking-wider">Total</p>
                        <p className="text-xl font-bold">${order.total.toFixed(2)}</p>
                      </div>
                      {order.status !== OrderStatus.DELIVERED && (
                        <button 
                          onClick={() => updateOrderStatus(order.id, OrderStatus.DELIVERED)}
                          className="bg-emerald-500 text-white p-2.5 rounded-xl hover:bg-emerald-600 transition-colors"
                        >
                          <CheckCircle2 className="w-6 h-6" />
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeView === 'kitchen' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {orders.filter(o => o.status === OrderStatus.PENDING || o.status === OrderStatus.PREPARING).map(order => (
              <div key={order.id} className="bg-white rounded-2xl border border-slate-200 overflow-hidden flex flex-col">
                <div className={`p-4 ${order.status === OrderStatus.PENDING ? 'bg-amber-50 border-b border-amber-100' : 'bg-blue-50 border-b border-blue-100'}`}>
                  <div className="flex justify-between items-center mb-1">
                    <span className="font-bold">{order.id}</span>
                    <span className="text-xs font-bold uppercase px-2 py-0.5 rounded bg-white/50">{order.status}</span>
                  </div>
                  <p className="text-xs font-medium text-slate-600 uppercase tracking-wide">
                    {order.customerName} {order.tableNumber && `| Mesa ${order.tableNumber}`}
                  </p>
                </div>
                <div className="p-4 flex-1 space-y-3">
                  {order.items.map(item => (
                    <div key={item.id} className="flex justify-between items-start gap-2">
                      <span className="font-bold text-orange-600">{item.quantity}x</span>
                      <span className="flex-1 text-sm font-medium">{item.name}</span>
                    </div>
                  ))}
                </div>
                <div className="p-4 bg-slate-50 border-t border-slate-100">
                  {order.status === OrderStatus.PENDING ? (
                    <button 
                      onClick={() => updateOrderStatus(order.id, OrderStatus.PREPARING)}
                      className="w-full py-2 bg-blue-600 text-white rounded-lg font-bold flex items-center justify-center gap-2"
                    >
                      <Clock className="w-4 h-4" /> Empezar a Preparar
                    </button>
                  ) : (
                    <button 
                      onClick={() => updateOrderStatus(order.id, OrderStatus.READY)}
                      className="w-full py-2 bg-emerald-600 text-white rounded-lg font-bold flex items-center justify-center gap-2"
                    >
                      <CheckCircle2 className="w-4 h-4" /> Marcar como Listo
                    </button>
                  )}
                </div>
              </div>
            ))}
            {orders.filter(o => o.status === OrderStatus.PENDING || o.status === OrderStatus.PREPARING).length === 0 && (
              <div className="col-span-full py-20 text-center">
                <ChefHat className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-slate-400">¡Cocina al día!</h3>
                <p className="text-slate-400">No hay pedidos pendientes de preparación.</p>
              </div>
            )}
          </div>
        )}

        {activeView === 'stats' && (
          <div className="space-y-8">
            <h2 className="text-2xl font-bold">Rendimiento de Ventas</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <StatCard label="Ventas Totales" value={`$${orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((a, b) => a + b.total, 0).toFixed(2)}`} icon={<BarChart3 className="text-emerald-500" />} />
              <StatCard label="Pedidos Completados" value={orders.filter(o => o.status === OrderStatus.DELIVERED).length.toString()} icon={<CheckCircle2 className="text-blue-500" />} />
              <StatCard label="Ticket Promedio" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(2) : '0.00'}`} icon={<Clock className="text-orange-500" />} />
            </div>

            <div className="bg-white p-6 rounded-3xl border border-slate-200">
              <h3 className="font-bold mb-6 text-lg">Productos Más Vendidos</h3>
              <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={salesData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                    />
                    <Bar dataKey="value" fill="#f97316" radius={[6, 6, 0, 0]}>
                      {salesData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#f97316' : '#fb923c'} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        )}

        {activeView === 'ai' && (
          <div className="space-y-8">
            <div className="bg-indigo-600 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl shadow-indigo-100">
              <div className="relative z-10">
                <div className="flex items-center gap-3 mb-4">
                  <div className="bg-white/20 p-2 rounded-xl backdrop-blur-md">
                    <Sparkles className="w-6 h-6 text-indigo-200" />
                  </div>
                  <h2 className="text-2xl font-bold">Consultor Inteligente</h2>
                </div>
                <p className="text-indigo-100 max-w-lg mb-6">
                  Obtén recomendaciones basadas en tus ventas actuales y tendencias de mercado para optimizar tu negocio.
                </p>
                <button 
                  onClick={fetchAISuggestions}
                  disabled={loadingAI}
                  className="px-6 py-3 bg-white text-indigo-600 rounded-2xl font-bold hover:bg-indigo-50 transition-colors disabled:opacity-50"
                >
                  {loadingAI ? 'Analizando...' : 'Generar Análisis de Hoy'}
                </button>
              </div>
              <Sparkles className="absolute -bottom-10 -right-10 w-64 h-64 text-white/10" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {aiSuggestions.map((s, idx) => (
                <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-200 hover:border-indigo-200 transition-colors group">
                  <div className="flex justify-between items-start mb-4">
                    <h3 className="font-bold text-lg group-hover:text-indigo-600 transition-colors">{s.title}</h3>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-widest ${
                      s.impact === 'Alta' ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'
                    }`}>
                      Impacto {s.impact}
                    </span>
                  </div>
                  <p className="text-slate-500 text-sm leading-relaxed">{s.description}</p>
                </div>
              ))}
              {!loadingAI && aiSuggestions.length === 0 && (
                <div className="col-span-full text-center py-20 text-slate-400">
                  Pulsa el botón superior para recibir consejos estratégicos.
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* Cart Drawer / Slide-over */}
      {isCartOpen && (
        <div className="fixed inset-0 z-[60] overflow-hidden">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity" onClick={() => setIsCartOpen(false)} />
          <div className="absolute inset-y-0 right-0 w-full max-w-md bg-white shadow-2xl flex flex-col transform transition-transform duration-300">
            <div className="px-6 py-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-2xl font-bold flex items-center gap-2">
                Tu Carrito <span className="bg-slate-100 text-slate-600 text-sm px-2 py-1 rounded-lg">{cart.length}</span>
              </h2>
              <button onClick={() => setIsCartOpen(false)} className="p-2 hover:bg-slate-100 rounded-full">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
              {cart.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
                  <ShoppingBag className="w-16 h-16 opacity-20" />
                  <p>Carrito vacío</p>
                </div>
              ) : (
                <>
                  <div className="space-y-4">
                    {cart.map(item => (
                      <div key={item.id} className="flex gap-4">
                        <img src={item.image} className="w-20 h-20 rounded-xl object-cover" alt="" />
                        <div className="flex-1">
                          <div className="flex justify-between font-bold mb-1">
                            <span>{item.name}</span>
                            <span>${(item.price * item.quantity).toFixed(2)}</span>
                          </div>
                          <div className="flex items-center gap-3">
                            <div className="flex items-center border border-slate-200 rounded-lg p-1">
                              <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-slate-100 rounded">
                                <Minus className="w-3 h-3" />
                              </button>
                              <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                              <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-slate-100 rounded">
                                <Plus className="w-3 h-3" />
                              </button>
                            </div>
                            <button onClick={() => removeFromCart(item.id)} className="text-red-500 hover:text-red-600 p-1">
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>

                  {upsellHint && (
                    <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100 flex gap-3">
                      <Sparkles className="w-5 h-5 text-orange-500 shrink-0 mt-1" />
                      <div>
                        <p className="text-xs font-bold text-orange-600 uppercase mb-1">Tip de IA para vender más:</p>
                        <p className="text-sm text-orange-800">{upsellHint}</p>
                      </div>
                    </div>
                  )}

                  <div className="space-y-4 pt-4 border-t border-slate-100">
                    <h3 className="font-bold text-sm uppercase tracking-wider text-slate-400">Datos de Entrega</h3>
                    <div className="space-y-3">
                      <input 
                        type="text" 
                        placeholder="Nombre del Cliente" 
                        value={customerName}
                        onChange={(e) => setCustomerName(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none transition-shadow"
                      />
                      <input 
                        type="text" 
                        placeholder="Nº Mesa (Opcional)" 
                        value={tableNumber}
                        onChange={(e) => setTableNumber(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none transition-shadow"
                      />
                    </div>
                  </div>
                </>
              )}
            </div>

            <div className="p-6 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-500 font-medium">Subtotal</span>
                <span className="text-3xl font-black text-slate-900">${cartTotal.toFixed(2)}</span>
              </div>
              <button 
                onClick={placeOrder}
                disabled={cart.length === 0}
                className="w-full py-4 bg-orange-500 text-white rounded-2xl font-bold text-lg shadow-lg shadow-orange-200 hover:bg-orange-600 transition-colors disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-3"
              >
                Confirmar Pedido <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Sub-components
const NavButton: React.FC<{ icon: React.ReactNode, active: boolean, onClick: () => void, label: string }> = ({ icon, active, onClick, label }) => (
