import React, { useState, useMemo, useEffect } from 'react';
import { 
  ShoppingBag, 
  ClipboardList, 
  ChefHat, 
  BarChart3, 
  Sparkles, 
  Plus, 
  Minus, 
  Trash2, 
  CheckCircle2, 
  Clock,
  ChevronRight,
  X,
  CreditCard,
  UtensilsCrossed,
  ArrowRight
} from 'lucide-react';
import { FoodItem, Order, OrderItem, OrderStatus, ViewType, PaymentStatus } from './types';
import { INITIAL_MENU, CATEGORIES } from './constants';
import { getSmartSuggestions, generateUpsellSuggestion } from './geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('menu');
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);
  const [upsellHint, setUpsellHint] = useState<string | null>(null);

  // Filtered menu
  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return INITIAL_MENU;
    return INITIAL_MENU.filter(item => item.category === activeCategory);
  }, [activeCategory]);

  // Cart logic
  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        const newQty = Math.max(1, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handlePayment = () => {
    if (!customerName) {
      alert("Por favor, ingresa el nombre del cliente.");
      return;
    }
    setIsPaying(true);
    // Simular proceso de pago
    setTimeout(() => {
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        confirmOrder();
        setPaymentSuccess(false);
      }, 1500);
    }, 2000);
  };

  const confirmOrder = () => {
    const newOrder: Order = {
      id: `ORD-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
      items: [...cart],
      total: cartTotal,
      status: OrderStatus.PENDING,
      paymentStatus: PaymentStatus.PAID,
      customerName: customerName,
      tableNumber: tableNumber,
      createdAt: Date.now()
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setCustomerName('');
    setTableNumber('');
    setIsCartOpen(false);
    setActiveView('orders');
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    const suggestions = await getSmartSuggestions(INITIAL_MENU, orders);
    setAiSuggestions(suggestions);
    setLoadingAI(false);
  };

  useEffect(() => {
    if (cart.length > 0 && cart.length % 2 === 0) {
      generateUpsellSuggestion(cart).then(hint => setUpsellHint(hint));
    } else {
      setUpsellHint(null);
    }
  }, [cart]);

  return (
    <div className="min-h-screen pb-20 md:pb-0 md:pl-20 flex flex-col bg-[#FDFCFB] text-slate-900 overflow-x-hidden">

      {/* Sidebar Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 md:top-0 md:bottom-0 md:w-20 bg-white border-t md:border-t-0 md:border-r border-slate-100 z-50 flex md:flex-col justify-around md:justify-center items-center py-4 md:space-y-10">
        <NavButton icon={<UtensilsCrossed />} active={activeView === 'menu'} onClick={() => setActiveView('menu')} label="Menú" />
        <NavButton icon={<ClipboardList />} active={activeView === 'orders'} onClick={() => setActiveView('orders')} label="Pedidos" />
        <NavButton icon={<ChefHat />} active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} label="Cocina" />
        <NavButton icon={<BarChart3 />} active={activeView === 'stats'} onClick={() => setActiveView('stats')} label="Stats" />
        <NavButton icon={<Sparkles className="text-amber-500" />} active={activeView === 'ai'} onClick={() => setActiveView('ai')} label="IA" />
      </nav>

      {/* Modern Header */}
      <header className="sticky top-0 bg-white/70 backdrop-blur-xl border-b border-slate-100 px-6 py-5 flex justify-between items-center z-40">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-br from-orange-500 to-red-600 p-2.5 rounded-2xl shadow-lg shadow-orange-100">
            <UtensilsCrossed className="text-white w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight leading-none">FastFood<span className="text-orange-500">Pro</span></h1>
            <p className="text-[10px] uppercase tracking-widest font-bold text-slate-400 mt-1">Management Suite</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsCartOpen(true)}
            className="relative p-3 bg-slate-50 border border-slate-100 rounded-2xl hover:bg-slate-100 transition-all active:scale-95"
          >
            <ShoppingBag className="w-6 h-6 text-slate-700" />
            {cart.length > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white animate-bounce">
                {cart.reduce((a, b) => a + b.quantity, 0)}
              </span>
            )}
          </button>
        </div>
      </header>

      <main className="flex-1 p-4 md:p-8 max-w-7xl mx-auto w-full animate-in fade-in duration-500">
        {activeView === 'menu' && (
          <div className="space-y-10">
            {/* Visual Category Scroller */}
            <div className="flex overflow-x-auto pb-4 no-scrollbar gap-4 -mx-4 px-4">
              <CategoryBtn 
                label="Todas" 
                icon="🔥" 
                active={activeCategory === 'Todas'} 
                onClick={() => setActiveCategory('Todas')} 
              />
              {CATEGORIES.map(cat => (
                <CategoryBtn 
                  key={cat.id}
                  label={cat.id} 
                  icon={cat.icon} 
                  active={activeCategory === cat.id} 
                  onClick={() => setActiveCategory(cat.id)} 
                />
              ))}
            </div>

            {/* Menu Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[32px] border border-slate-100 overflow-hidden hover:shadow-2xl hover:shadow-orange-100/50 transition-all duration-500 group flex flex-col">
                  <div className="relative h-56 overflow-hidden">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                    <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1.5 rounded-2xl text-sm font-black text-orange-600 shadow-xl">
                      ${item.price.toFixed(2)}
                    </div>
                  </div>
                  <div className="p-6 flex flex-col flex-1">
                    <span className="text-[10px] font-black uppercase tracking-widest text-orange-500 mb-2">{item.category}</span>
                    <h3 className="text-xl font-bold mb-2 group-hover:text-orange-600 transition-colors">{item.name}</h3>
                    <p className="text-slate-400 text-sm leading-relaxed mb-6 line-clamp-2">{item.description}</p>
                    <button 
                      onClick={() => addToCart(item)}
                      className="mt-auto w-full py-4 bg-slate-900 text-white rounded-[20px] font-bold flex items-center justify-center gap-3 hover:bg-orange-500 transition-all active:scale-95 shadow-lg shadow-slate-200"
                    >
                      <Plus className="w-5 h-5" /> Agregar
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeView === 'orders' && (
          <div className="max-w-3xl mx-auto space-y-6">
            <h2 className="text-3xl font-black tracking-tight">Registro de Pedidos</h2>
            {orders.map(order => (
              <div key={order.id} className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm space-y-4">
                <div className="flex justify-between items-start">
                  <div>
                    <div className="flex items-center gap-3 mb-2">
                      <span className="text-lg font-black">{order.id}</span>
                      <StatusBadge status={order.status} />
                      <span className="text-[10px] font-bold bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full uppercase tracking-widest">Pagado</span>
                    </div>
                    <p className="text-slate-400 text-sm font-medium">
                      Cliente: <span className="text-slate-900 font-bold">{order.customerName}</span> {order.tableNumber ? `• Mesa ${order.tableNumber}` : ''}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-2xl font-black text-slate-900">${order.total.toFixed(2)}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">{new Date(order.createdAt).toLocaleTimeString()}</p>
                  </div>
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl space-y-2">
                  {order.items.map(i => (
                    <div key={i.id} className="flex justify-between text-sm">
                      <span className="font-medium">{i.quantity}x {i.name}</span>
                      <span className="text-slate-400">${(i.price * i.quantity).toFixed(2)}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {orders.length === 0 && (
              <div className="text-center py-20 bg-white rounded-[40px] border border-dashed border-slate-200">
                <ClipboardList className="w-16 h-16 text-slate-200 mx-auto mb-4" />
                <p className="text-slate-400 font-bold">No hay historial de pedidos todavía.</p>
              </div>
            )}
          </div>
        )}

        {activeView === 'kitchen' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {orders.filter(o => o.status !== OrderStatus.DELIVERED).map(order => (
              <div key={order.id} className="bg-white rounded-[32px] border-2 border-slate-50 overflow-hidden shadow-xl shadow-slate-100 flex flex-col">
                <div className={`p-6 border-b-2 ${order.status === OrderStatus.PENDING ? 'bg-amber-50 border-amber-100' : 'bg-blue-50 border-blue-100'}`}>
                  <div className="flex justify-between items-center mb-3">
                    <span className="text-xl font-black">{order.id}</span>
                    <div className="animate-pulse flex items-center gap-2 text-[10px] font-bold uppercase bg-white px-3 py-1 rounded-full shadow-sm">
                      <Clock className="w-3 h-3" /> {order.status}
                    </div>
                  </div>
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest">{order.customerName} {order.tableNumber && `| MESA ${order.tableNumber}`}</p>
                </div>
                <div className="p-6 flex-1 space-y-4">
                  {order.items.map(item => (
                    <div key={item.id} className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-orange-100 text-orange-600 rounded-xl flex items-center justify-center font-black text-lg">
                        {item.quantity}
                      </div>
                      <span className="flex-1 font-bold text-slate-700">{item.name}</span>
                    </div>
                  ))}
                </div>
                <div className="p-6 pt-0">
                  {order.status === OrderStatus.PENDING ? (
                    <button 
                      onClick={() => updateOrderStatus(order.id, OrderStatus.PREPARING)}
                      className="w-full py-4 bg-orange-500 text-white rounded-2xl font-black shadow-lg shadow-orange-100 hover:bg-orange-600 transition-all flex items-center justify-center gap-2"
                    >
                      Cocinar Pedido
                    </button>
                  ) : order.status === OrderStatus.PREPARING ? (
                    <button 
                      onClick={() => updateOrderStatus(order.id, OrderStatus.READY)}
                      className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                    >
                      Marcar como Listo
                    </button>
                  ) : (
                    <button 
                      onClick={() => updateOrderStatus(order.id, OrderStatus.DELIVERED)}
                      className="w-full py-4 bg-emerald-500 text-white rounded-2xl font-black shadow-lg shadow-emerald-100 hover:bg-emerald-600 transition-all flex items-center justify-center gap-2"
                    >
                      Completar Entrega
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      {/* Cart & Payment Drawer */}
      {isCartOpen && (
        <div className="fixed inset-0 z-[60] flex justify-end overflow-hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity" onClick={() => !isPaying && setIsCartOpen(false)} />
          <div className="relative w-full max-w-lg bg-white shadow-2xl flex flex-col transform transition-transform duration-500 animate-in slide-in-from-right">

            <div className="px-8 py-8 border-b border-slate-50 flex justify-between items-center">
              <div>
                <h2 className="text-3xl font-black tracking-tight">Tu Pedido</h2>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">{cart.length} productos seleccionados</p>
              </div>
              {!isPaying && (
                <button onClick={() => setIsCartOpen(false)} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-full transition-colors">
                  <X className="w-6 h-6" />
                </button>
              )}
            </div>

            <div className="flex-1 overflow-y-auto px-8 py-6 space-y-8">
              {cart.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ShoppingBag className="w-32 h-32 mb-4 opacity-10" />
                  <p className="text-xl font-black">Carrito vacío</p>
                </div>
              ) : (
                <>
                  <div className="space-y-4">
                    {cart.map(item => (
                      <div key={item.id} className="flex items-center gap-4 group">
                        <img src={item.image} className="w-20 h-20 rounded-[20px] object-cover shadow-sm" alt="" />
                        <div className="flex-1">
                          <h4 className="font-black text-slate-900">{item.name}</h4>
                          <p className="text-orange-500 font-bold text-sm">${item.price.toFixed(2)}</p>
                          <div className="flex items-center gap-4 mt-2">
                            <div className="flex items-center bg-slate-100 rounded-xl p-1">
                              <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded-lg transition-colors">
                                <Minus className="w-3 h-3" />
                              </button>
                              <span className="w-8 text-center text-xs font-black">{item.quantity}</span>
                              <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-white rounded-lg transition-colors">
                                <Plus className="w-3 h-3" />
                              </button>
                            </div>
                          </div>
                        </div>
                        <div className="text-right font-black">
                          ${(item.price * item.quantity).toFixed(2)}
                        </div>
                      </div>
                    ))}
                  </div>

                  {upsellHint && (
                    <div className="bg-orange-50 p-6 rounded-[28px] border-2 border-orange-100/50 flex gap-4 animate-bounce-slow">
                      <Sparkles className="w-6 h-6 text-orange-500 shrink-0" />
                      <div>
                        <p className="text-[10px] font-black text-orange-600 uppercase tracking-widest mb-1">Recomendación IA</p>
                        <p className="text-sm text-orange-900 font-medium leading-relaxed">{upsellHint}</p>
                      </div>
                    </div>
                  )}

                  <div className="space-y-6 pt-6 border-t border-slate-50">
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">Detalles de Entrega</h3>
                    <div className="space-y-4">
                      <div className="relative">
                        <input 
                          type="text" 
                          placeholder="Nombre del Cliente" 
                          value={customerName}
                          onChange={(e) => setCustomerName(e.target.value)}
                          className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-transparent rounded-[20px] focus:bg-white focus:border-orange-500 outline-none transition-all font-bold"
                        />
                        <UtensilsCrossed className="absolute left-4 top-4.5 w-5 h-5 text-slate-300" />
                      </div>
                      <div className="relative">
