                disabled={cart.length === 0 || isPaying || paymentSuccess}
                className={`w-full py-5 rounded-[24px] font-black text-lg shadow-2xl transition-all flex items-center justify-center gap-3 relative overflow-hidden ${
                  paymentSuccess 
                  ? 'bg-emerald-500 text-white' 
                  : 'bg-slate-900 text-white hover:bg-orange-600 active:scale-95 shadow-orange-100'
