// Componente para el contador de tiempo real en cocina
const OrderTimer: React.FC<{ startTime: number }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    }, 10000); // Actualiza cada 10 seg
    setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    return () => clearInterval(interval);
  }, [startTime]);

  return (
    <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm ${
      elapsed > 15 ? 'bg-red-500 text-white animate-pulse' : elapsed > 10 ? 'bg-orange-500 text-white' : 'bg-slate-900 text-white'
    }`}>
      <Timer className="w-3 h-3" />
      {elapsed} min esperando
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('menu');
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);
  const [upsellHint, setUpsellHint] = useState<string | null>(null);

  // Filtrado de menú
  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return INITIAL_MENU;
    return INITIAL_MENU.filter(item => item.category === activeCategory);
  }, [activeCategory]);

  // Lógica de Carrito
  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        const newQty = Math.max(1, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handlePayment = () => {
    if (!customerName) {
      alert("Por favor, ingresa tu nombre para el pedido.");
      return;
    }
    setIsPaying(true);
    setTimeout(() => {
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        confirmOrder();
        setPaymentSuccess(false);
      }, 1500);
    }, 2000);
  };

  const confirmOrder = () => {
    const newOrder: Order = {
      id: `#${Math.floor(1000 + Math.random() * 9000)}`,
      items: [...cart],
      total: cartTotal,
      status: OrderStatus.PENDING,
      paymentStatus: PaymentStatus.PAID,
      customerName: customerName,
      tableNumber: tableNumber,
      createdAt: Date.now()
    };
    // IMPORTANTE: Se agregan al final o se gestionan por fecha después
    setOrders(prev => [...prev, newOrder]);
    setCart([]);
    setCustomerName('');
    setTableNumber('');
    setIsCartOpen(false);
    setActiveView('menu'); // Regresa al menú tras pedir (simula kiosco)
    alert("¡Pedido enviado a cocina! Número de orden: " + newOrder.id);
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  // Pedidos activos ordenados por llegada (FIFO)
