const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => {
      o.items.forEach(item => {
        data[item.name] = (data[item.name] || 0) + item.quantity;
      });
    });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);

  return (
    <div className="space-y-16">
      <h2 className="text-5xl font-black tracking-tight">Análisis Operativo</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        <StatCard label="Ingresos Totales" value={`$${orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((a, b) => a + b.total, 0).toFixed(2)}`} icon={<BarChart3 className="text-emerald-500" />} />
        <StatCard label="Servicios Cerrados" value={orders.filter(o => o.status === OrderStatus.DELIVERED).length.toString()} icon={<CheckCircle2 className="text-blue-500" />} />
        <StatCard label="Ticket Promedio" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(2) : '0.00'}`} icon={<Clock className="text-orange-500" />} />
      </div>

      <div className="bg-white p-14 rounded-[60px] border border-slate-100 shadow-sm">
        <h3 className="font-black mb-12 text-2xl uppercase tracking-[0.2em] text-slate-300">Demanda por Plato</h3>
        <div className="h-[500px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={salesData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 800, fill: '#64748b' }} />
              <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 800, fill: '#64748b' }} />
