                     ))}
                   </div>

                   <div className="p-8 bg-slate-50 border-t border-slate-100">
                     <button 
                       onClick={() => updateOrderStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)}
                       className={`w-full py-5 rounded-[22px] font-black text-lg transition-all flex items-center justify-center gap-3 shadow-lg ${
                         order.status === OrderStatus.PENDING ? 'bg-orange-600 text-white shadow-orange-100' :
                         order.status === OrderStatus.PREPARING ? 'bg-blue-600 text-white shadow-blue-100' : 'bg-emerald-600 text-white shadow-emerald-100'
                       }`}
                     >
                       {order.status === OrderStatus.PENDING ? 'Iniciar Cocción' : 
                        order.status === OrderStatus.PREPARING ? 'Marcar como Listo' : 'Confirmar Entrega'}
                     </button>
                   </div>
                 </div>
               ))}

