const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => {
      o.items.forEach(item => { data[item.name] = (data[item.name] || 0) + item.quantity; });
    });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);
  return (
    <div className="space-y-16">
      <h2 className="text-5xl font-black tracking-tight">Análisis Operativo</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
