        <StatCard label="Servicios Cerrados" value={orders.filter(o => o.status === OrderStatus.DELIVERED).length.toString()} icon={<CheckCircle2 className="text-blue-500" />} />
        <StatCard label="Ticket Promedio" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(2) : '0.00'}`} icon={<Clock className="text-orange-500" />} />
      </div>
      <div className="bg-white p-14 rounded-[60px] border border-slate-100 shadow-sm">
        <h3 className="font-black mb-12 text-2xl uppercase tracking-[0.2em] text-slate-300">Demanda por Plato</h3>
        <div className="h-[500px] w-full"><ResponsiveContainer width="100%" height="100%"><BarChart data={salesData}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 800, fill: '#64748b' }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 800, fill: '#64748b' }} /><Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '32px', border: 'none', boxShadow: '0 40px 80px rgba(0,0,0,0.1)' }} /><Bar dataKey="value" fill="#f97316" radius={[16, 16, 0, 0]} barSize={60}>{salesData.map((entry, index) => <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#ea580c' : '#f97316'} />)}</Bar></BarChart></ResponsiveContainer></div>
      </div>
    </div>
  );
};

