                      <td className="p-8 font-black text-2xl text-slate-800 tracking-tighter">
                        <span className="text-orange-500 text-sm mr-1">$</span>
                        {item.price.toFixed(2)}
                      </td>
                      <td className="p-8 text-right">
                        <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }}
                            className="p-5 bg-white border border-slate-200 rounded-[20px] text-slate-400 hover:text-slate-900 hover:border-slate-900 transition-all shadow-sm"
                            title="Editar plato"
                          >
                            <Edit2 className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={() => handleDeleteItem(item.id)}
                            className="p-5 bg-white border border-slate-200 rounded-[20px] text-slate-400 hover:text-red-600 hover:border-red-200 transition-all shadow-sm"
                            title="Eliminar plato"
                          >
