// Componente para el contador de tiempo real en cocina (FIFO)
const OrderTimer: React.FC<{ startTime: number }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    }, 10000);
    setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    return () => clearInterval(interval);
  }, [startTime]);

  return (
    <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${
      elapsed > 15 ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white'
    }`}>
      <Timer className="w-3 h-3" />
      {elapsed} min en espera
    </div>
  );
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewType>('menu');
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [menuItems, setMenuItems] = useState<FoodItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<OrderItem[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);
  const [upsellHint, setUpsellHint] = useState<string | null>(null);
  const [lastAddedItem, setLastAddedItem] = useState<string | null>(null);

  // Admin State
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);
  const [isAdminFormOpen, setIsAdminFormOpen] = useState(false);
  const [adminSearch, setAdminSearch] = useState('');

  // Filtrado de menú para vista cliente
  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [activeCategory, menuItems]);

  // Filtrado de menú para admin
  const filteredAdminMenu = useMemo(() => {
    return menuItems.filter(item => 
      item.name.toLowerCase().includes(adminSearch.toLowerCase()) || 
      item.category.toLowerCase().includes(adminSearch.toLowerCase())
    );
  }, [menuItems, adminSearch]);

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
    setLastAddedItem(item.name);
    setTimeout(() => setLastAddedItem(null), 3000);
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => {
      if (i.id === itemId) {
        const newQty = Math.max(0, i.quantity + delta);
        return { ...i, quantity: newQty };
      }
      return i;
    }).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handlePayment = () => {
    if (!customerName) {
      alert("Por favor, ingresa el nombre para la comanda.");
      return;
    }
    setIsPaying(true);
    setTimeout(() => {
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        confirmOrder();
        setPaymentSuccess(false);
      }, 1500);
    }, 2000);
  };

  const confirmOrder = () => {
    const newOrder: Order = {
      id: `#COM-${Math.floor(100 + Math.random() * 899)}`,
      items: [...cart],
      total: cartTotal,
      status: OrderStatus.PENDING,
      paymentStatus: PaymentStatus.PAID,
      customerName: customerName,
      tableNumber: tableNumber,
      createdAt: Date.now()
    };
    setOrders(prev => [...prev, newOrder]);
    setCart([]);
    setCustomerName('');
    setTableNumber('');
    setIsCartOpen(false);
    setActiveView('orders');
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    try {
      const suggestions = await getSmartSuggestions(menuItems, orders);
      setAiSuggestions(suggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAI(false);
    }
  };

  const handleSaveItem = (item: FoodItem) => {
    if (editingItem && menuItems.some(i => i.id === item.id)) {
      setMenuItems(prev => prev.map(i => i.id === item.id ? item : i));
    } else {
      setMenuItems(prev => [...prev, { ...item, id: `item-${Date.now()}` }]);
    }
    setIsAdminFormOpen(false);
    setEditingItem(null);
  };

  const handleDeleteItem = (id: string) => {
    if (window.confirm('¿Estás seguro de eliminar este plato? Se quitará del menú inmediatamente.')) {
      setMenuItems(prev => prev.filter(i => i.id !== id));
    }
  };

  useEffect(() => {
    if (cart.length > 0 && cart.length % 2 === 0) {
      generateUpsellSuggestion(cart).then(hint => setUpsellHint(hint));
    } else {
      setUpsellHint(null);
    }
  }, [cart]);

  return (
    <div className="min-h-screen pb-24 md:pb-0 md:pl-28 flex flex-col bg-[#FAF9F6] text-slate-900 font-sans">

      {/* Navegación Sidebar */}
      <nav className="fixed bottom-0 left-0 right-0 md:top-0 md:bottom-0 md:w-28 bg-white border-t md:border-t-0 md:border-r border-slate-200 z-50 flex md:flex-col justify-around md:justify-center items-center py-6 shadow-2xl md:shadow-none">
        <div className="hidden md:flex mb-10">
          <div className="w-14 h-14 bg-orange-600 rounded-[20px] flex items-center justify-center shadow-lg shadow-orange-100">
            <UtensilsCrossed className="text-white w-7 h-7" />
          </div>
        </div>
        <div className="flex md:flex-col gap-4 md:gap-8">
          <NavButton icon={<ShoppingBasket />} active={activeView === 'menu'} onClick={() => setActiveView('menu')} label="Menú" />
          <NavButton icon={<ChefHat />} active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} label="Cocina" badge={orders.filter(o => o.status !== OrderStatus.DELIVERED).length} />
          <NavButton icon={<ClipboardList />} active={activeView === 'orders'} onClick={() => setActiveView('orders')} label="Servicio" />
          <NavButton icon={<BarChart3 />} active={activeView === 'stats'} onClick={() => setActiveView('stats')} label="Stats" />
          <NavButton icon={<Sparkles className="text-amber-500" />} active={activeView === 'ai'} onClick={() => setActiveView('ai')} label="IA" />
          <NavButton icon={<Settings />} active={activeView === 'admin'} onClick={() => setActiveView('admin')} label="Gestión" />
        </div>
      </nav>

      {/* Header Dinámico */}
      <header className="sticky top-0 bg-white/80 backdrop-blur-xl border-b border-slate-100 px-8 py-7 flex justify-between items-center z-40">
        <div>
          <h1 className="text-3xl font-black tracking-tight italic">
            FASTFOOD <span className="text-orange-600 not-italic">{activeView === 'admin' ? 'ADMIN' : 'SERVICE'}</span>
          </h1>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mt-1">
            {activeView === 'admin' ? 'Configuración de Productos' : 'Gestión de Comandas Profesionales'}
          </p>
        </div>

        {activeView === 'admin' ? (
          <button 
            onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }}
            className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-[22px] hover:bg-orange-600 transition-all active:scale-95 shadow-xl shadow-slate-200 font-black"
          >
            <Plus className="w-5 h-5" /> Nuevo Plato
          </button>
        ) : (
          <button 
            onClick={() => setIsCartOpen(true)}
            className="flex items-center gap-4 bg-slate-900 text-white px-8 py-4 rounded-[22px] hover:bg-orange-600 transition-all active:scale-95 shadow-xl shadow-slate-200 group"
          >
            <div className="relative">
              <ShoppingBag className="w-6 h-6 group-hover:rotate-12 transition-transform" />
              {cart.length > 0 && (
                <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">
                  {cart.reduce((a, b) => a + b.quantity, 0)}
                </span>
              )}
            </div>
            <div className="text-left hidden sm:block">
              <p className="text-[10px] font-black uppercase tracking-widest opacity-60 leading-none mb-1">Total Pedido</p>
              <p className="text-lg font-black leading-none">${cartTotal.toFixed(2)}</p>
            </div>
          </button>
        )}
      </header>

      <main className="flex-1 p-6 md:p-14 max-w-[1600px] mx-auto w-full animate-in fade-in duration-1000">

        {/* VISTA MENÚ (CLIENTE) */}
        {activeView === 'menu' && (
          <div className="space-y-16">
            <div className="flex overflow-x-auto pb-8 no-scrollbar gap-6 -mx-4 px-4 items-center">
              <CategoryBtn label="Todas" icon="🔥" active={activeCategory === 'Todas'} onClick={() => setActiveCategory('Todas')} />
              <div className="h-10 w-px bg-slate-200 shrink-0 mx-2" />
              {CATEGORIES.map(cat => <CategoryBtn key={cat.id} label={cat.id} icon={cat.icon} active={activeCategory === cat.id} onClick={() => setActiveCategory(cat.id)} />)}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[48px] border border-slate-100 overflow-hidden hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)] transition-all duration-700 group flex flex-col h-full animate-in zoom-in duration-300">
                  <div className="relative h-72 overflow-hidden">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                    <div className="absolute bottom-6 left-6 text-white opacity-0 group-hover:opacity-100 translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                      <p className="text-xs font-black uppercase tracking-widest text-orange-400 mb-1">{item.category}</p>
                      <p className="text-2xl font-black">{item.name}</p>
                    </div>
                  </div>
                  <div className="p-10 flex flex-col flex-1">
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="text-2xl font-black text-slate-800 leading-tight">{item.name}</h3>
                      <span className="text-xl font-black text-orange-600">${item.price.toFixed(2)}</span>
                    </div>
                    <p className="text-slate-400 text-sm leading-relaxed mb-10 line-clamp-2 font-medium">{item.description}</p>
                    <button onClick={() => addToCart(item)} className="mt-auto w-full py-5 bg-slate-50 text-slate-900 rounded-[28px] font-black text-lg flex items-center justify-center gap-3 hover:bg-slate-900 hover:text-white transition-all active:scale-95 border-2 border-slate-100 hover:border-slate-900 shadow-sm">
                      <Plus className="w-6 h-6" /> Añadir a la Orden
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VISTA GESTIÓN (ADMIN) */}
        {activeView === 'admin' && (
          <div className="space-y-12 animate-in slide-in-from-bottom duration-500">
            <div className="flex flex-col md:flex-row gap-6 justify-between items-center mb-8">
              <div className="relative w-full max-w-md group">
                <input 
                  type="text" 
                  placeholder="Buscar en el inventario..." 
                  value={adminSearch}
                  onChange={(e) => setAdminSearch(e.target.value)}
                  className="w-full pl-14 pr-6 py-5 bg-white border border-slate-200 rounded-full focus:ring-4 focus:ring-orange-50 focus:border-orange-500 outline-none transition-all font-bold text-slate-600 placeholder:text-slate-300 shadow-sm"
                />
                <Search className="absolute left-6 top-5 w-6 h-6 text-slate-300 group-focus-within:text-orange-500 transition-colors" />
              </div>
            </div>

            <div className="bg-white rounded-[48px] border border-slate-100 overflow-hidden shadow-sm">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-100">
                    <th className="p-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Producto</th>
                    <th className="p-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Categoría</th>
                    <th className="p-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Precio</th>
                    <th className="p-8 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Acciones</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50 font-medium">
                  {filteredAdminMenu.map(item => (
                    <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="p-8">
                        <div className="flex items-center gap-6">
                          <img src={item.image} className="w-20 h-20 rounded-3xl object-cover shadow-sm" alt="" />
                          <div>
                            <p className="font-black text-slate-900 text-xl">{item.name}</p>
                            <p className="text-xs text-slate-400 line-clamp-1 max-w-xs">{item.description}</p>
                          </div>
                        </div>
                      </td>
                      <td className="p-8">
                        <span className="bg-slate-100 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-600">
                          {item.category}
                        </span>
                      </td>
                      <td className="p-8 font-black text-2xl text-orange-600">
                        ${item.price.toFixed(2)}
                      </td>
                      <td className="p-8 text-right">
                        <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }}
                            className="p-4 bg-white border border-slate-100 rounded-2xl text-slate-400 hover:text-orange-600 hover:border-orange-200 transition-all shadow-sm"
                          >
                            <Edit2 className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={() => handleDeleteItem(item.id)}
                            className="p-4 bg-white border border-slate-100 rounded-2xl text-slate-400 hover:text-red-500 hover:border-red-200 transition-all shadow-sm"
                          >
                            <Trash2 className="w-5 h-5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                  {filteredAdminMenu.length === 0 && (
                    <tr>
                      <td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase tracking-widest">No hay platos para mostrar</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ... Vistas de Cocina, Stats, AI se mantienen funcionales ... */}
        {activeView === 'kitchen' && (
           <div className="space-y-12">
             <div className="flex justify-between items-end">
               <h2 className="text-5xl font-black tracking-tight">Monitor de Cocina</h2>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
               {orders.filter(o => o.status !== OrderStatus.DELIVERED).sort((a,b) => a.createdAt - b.createdAt).map((order, idx) => (
                 <div key={order.id} className={`bg-white rounded-[32px] overflow-hidden flex flex-col border-t-[12px] shadow-2xl shadow-slate-100 ${idx === 0 ? 'border-red-500 ring-8 ring-red-50 ring-inset' : 'border-slate-800'}`}>
                   <div className="p-8 border-b border-dashed border-slate-200">
                     <div className="flex justify-between items-start mb-6"><span className="text-3xl font-black text-slate-900">{order.id}</span><OrderTimer startTime={order.createdAt} /></div>
                     <p className="font-black text-slate-800 uppercase tracking-widest text-[10px] text-slate-400 mb-1">Cliente</p>
                     <p className="font-black text-slate-800">{order.customerName} {order.tableNumber ? `• M-${order.tableNumber}` : ''}</p>
                   </div>
                   <div className="p-8 flex-1 space-y-6">{order.items.map(item => (<div key={item.id} className="flex items-center gap-5"><div className="w-12 h-12 bg-slate-900 text-white rounded-[16px] flex items-center justify-center font-black text-xl shrink-0">{item.quantity}</div><div><h4 className="font-black text-slate-800 leading-tight">{item.name}</h4></div></div>))}</div>
                   <div className="p-8 bg-slate-50">
                     <button onClick={() => updateOrderStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)} className="w-full py-5 bg-orange-600 text-white rounded-[22px] font-black text-lg shadow-lg shadow-orange-100 hover:bg-orange-700 transition-all">
                       {order.status === OrderStatus.PENDING ? 'Iniciar Cocción' : order.status === OrderStatus.PREPARING ? 'Listo para Entrega' : 'Entregar'}
                     </button>
                   </div>
                 </div>
               ))}
             </div>
           </div>
        )}

        {activeView === 'orders' && <HistoryView orders={orders} />}
        {activeView === 'stats' && <StatsView orders={orders} />}
        {activeView === 'ai' && <AIView menu={menuItems} orders={orders} fetchAISuggestions={fetchAISuggestions} loadingAI={loadingAI} aiSuggestions={aiSuggestions} />}

      </main>

      {/* MODAL ADMINISTRATIVO PARA AGREGAR/EDITAR */}
      {isAdminFormOpen && (
        <AdminForm 
          item={editingItem} 
          onSave={handleSaveItem} 
          onClose={() => setIsAdminFormOpen(false)} 
        />
      )}

      {/* CARRITO / COMANDA */}
      {isCartOpen && (
        <div className="fixed inset-0 z-[60] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-md" onClick={() => !isPaying && setIsCartOpen(false)} />
          <div className="relative w-full max-w-2xl bg-white shadow-2xl flex flex-col transform transition-transform duration-500 animate-in slide-in-from-right">
            <div className="px-12 py-12 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
              <h2 className="text-4xl font-black tracking-tighter italic">Mi <span className="text-orange-600 not-italic">Orden</span></h2>
              <button onClick={() => setIsCartOpen(false)} className="p-4 bg-white shadow-sm border border-slate-100 hover:bg-slate-50 rounded-full transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="flex-1 overflow-y-auto px-12 py-10 space-y-10">
              {cart.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-20"><ShoppingBasket className="w-32 h-32 mb-6" /><p className="text-2xl font-black uppercase tracking-widest">Bandeja Vacía</p></div>
              ) : (
                <>
                  <div className="space-y-6">
                    {cart.map(item => (
                      <div key={item.id} className="flex items-center gap-8">
                        <img src={item.image} className="w-24 h-24 rounded-[32px] object-cover shadow-lg" alt="" />
                        <div className="flex-1">
                          <h4 className="text-xl font-black text-slate-900">{item.name}</h4>
                          <p className="text-orange-600 font-black">${item.price.toFixed(2)}</p>
                          <div className="flex items-center gap-4 mt-2">
                            <button onClick={() => updateQuantity(item.id, -1)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200"><Minus className="w-4 h-4" /></button>
                            <span className="font-black text-lg">{item.quantity}</span>
                            <button onClick={() => updateQuantity(item.id, 1)} className="p-2 bg-slate-100 rounded-xl hover:bg-slate-200"><Plus className="w-4 h-4" /></button>
                          </div>
                        </div>
                        <div className="text-xl font-black">${(item.price * item.quantity).toFixed(2)}</div>
                      </div>
                    ))}
                  </div>
                  <div className="pt-10 border-t border-slate-100 space-y-6">
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Datos de Entrega</p>
                    <input type="text" placeholder="Nombre para el pedido" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-8 py-6 bg-slate-50 rounded-[28px] outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 transition-all font-black text-xl" />
                    <input type="text" placeholder="Número de Mesa (Opcional)" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-8 py-6 bg-slate-50 rounded-[28px] outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 transition-all font-black text-xl" />
                  </div>
                </>
              )}
            </div>
            <div className="p-12 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-8">
                <span className="text-slate-400 font-black uppercase tracking-widest text-xs">Total a Pagar</span>
                <div className="text-6xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button onClick={handlePayment} disabled={cart.length === 0 || !customerName || isPaying} className="w-full py-7 bg-slate-900 text-white rounded-[32px] font-black text-2xl hover:bg-orange-600 shadow-2xl transition-all disabled:opacity-50">
                {isPaying ? 'Procesando...' : paymentSuccess ? '¡Servicio Enviado!' : 'Confirmar Orden'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// COMPONENTE FORMULARIO ADMINISTRATIVO
const AdminForm: React.FC<{ item: FoodItem | null, onSave: (item: FoodItem) => void, onClose: () => void }> = ({ item, onSave, onClose }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState<FoodItem>(item || {
    id: '',
    name: '',
    price: 0,
    category: 'Hamburguesas',
    image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=400&h=300',
    description: ''
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, image: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.price <= 0) return alert('Datos incompletos');
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-white w-full max-w-4xl rounded-[60px] shadow-3xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
        <div className="md:w-5/12 bg-slate-50 p-12 border-r border-slate-100 flex flex-col items-center justify-center text-center">
          <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-10">Previsualización del Menú</p>
          <div className="bg-white rounded-[40px] shadow-2xl border border-slate-200/50 w-full overflow-hidden">
            <img src={formData.image} className="w-full h-56 object-cover" alt="" />
            <div className="p-8 text-left">
              <h4 className="text-2xl font-black text-slate-900">{formData.name || 'Nombre del Plato'}</h4>
              <p className="text-orange-600 font-black text-xl mb-4">${formData.price.toFixed(2)}</p>
              <p className="text-slate-400 text-sm line-clamp-3">{formData.description || 'Descripción del plato...'}</p>
            </div>
          </div>
        </div>
        <form onSubmit={handleSubmit} className="md:w-7/12 p-12 overflow-y-auto space-y-8">
          <h2 className="text-4xl font-black tracking-tight">{item ? 'Editar Plato' : 'Nuevo Plato'}</h2>
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Nombre</label>
            <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-8 py-5 bg-slate-50 rounded-[24px] outline-none focus:bg-white border-2 border-transparent focus:border-orange-500 font-bold" />
          </div>
          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-4">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Precio ($)</label>
              <input type="number" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full px-8 py-5 bg-slate-50 rounded-[24px] outline-none focus:bg-white border-2 border-transparent focus:border-orange-500 font-bold" />
            </div>
            <div className="space-y-4">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Categoría</label>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})} className="w-full px-8 py-5 bg-slate-50 rounded-[24px] outline-none focus:bg-white border-2 border-transparent focus:border-orange-500 font-bold appearance-none">
                {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.id}</option>)}
              </select>
            </div>
          </div>
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Imagen</label>
            <div className="flex gap-4">
              <input type="text" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} placeholder="URL de imagen" className="flex-1 px-8 py-5 bg-slate-50 rounded-[24px] outline-none focus:bg-white border-2 border-transparent focus:border-orange-500 font-bold" />
              <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
              <button type="button" onClick={() => fileInputRef.current?.click()} className="p-5 bg-slate-900 text-white rounded-2xl"><Upload className="w-6 h-6" /></button>
            </div>
          </div>
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Descripción</label>
            <textarea rows={3} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-8 py-5 bg-slate-50 rounded-[24px] outline-none focus:bg-white border-2 border-transparent focus:border-orange-500 font-bold resize-none" />
          </div>
          <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-[28px] font-black text-xl hover:bg-orange-600 shadow-xl transition-all">Guardar Plato</button>
        </form>
      </div>
    </div>
  );
};

// COMPONENTES SECUNDARIOS
