const OrderTimer: React.FC<{ startTime: number }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60)), 10000);
    setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    return () => clearInterval(interval);
  }, [startTime]);

  return (
    <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${
      elapsed > 15 ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white'
    }`}>
      <Timer className="w-3 h-3" /> {elapsed} min
    </div>
  );
};

// --- APP PRINCIPAL ---

const App: React.FC = () => {
  // --- PERSISTENCIA Y ESTADO INICIAL ---
  const [isStaffMode, setIsStaffMode] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [pin, setPin] = useState('');
  const [activeView, setActiveView] = useState<ViewType>('menu');

  // Cargar datos de localStorage o usar iniciales
  const [menuItems, setMenuItems] = useState<FoodItem[]>(() => {
    const saved = localStorage.getItem('fastfood_menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [restaurantInfo, setRestaurantInfo] = useState({
    name: localStorage.getItem('fastfood_name') || 'Gourmet Express',
    logo: localStorage.getItem('fastfood_logo') || ''
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('fastfood_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [cart, setCart] = useState<OrderItem[]>([]);
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);

  // Admin State
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);
  const [isAdminFormOpen, setIsAdminFormOpen] = useState(false);
  const [adminSearch, setAdminSearch] = useState('');

  // Efectos para persistencia
  useEffect(() => localStorage.setItem('fastfood_menu', JSON.stringify(menuItems)), [menuItems]);
  useEffect(() => localStorage.setItem('fastfood_orders', JSON.stringify(orders)), [orders]);
  useEffect(() => {
    localStorage.setItem('fastfood_name', restaurantInfo.name);
    localStorage.setItem('fastfood_logo', restaurantInfo.logo);
  }, [restaurantInfo]);

  // --- LÓGICA DE NEGOCIO ---

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [activeCategory, menuItems]);

  const filteredAdminMenu = useMemo(() => {
    return menuItems.filter(item => 
      item.name.toLowerCase().includes(adminSearch.toLowerCase()) || 
      item.category.toLowerCase().includes(adminSearch.toLowerCase())
    );
  }, [menuItems, adminSearch]);

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => i.id === itemId ? { ...i, quantity: Math.max(0, i.quantity + delta) } : i).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (pin === '1234') { 
      setIsStaffMode(true);
      setShowLogin(false);
      setActiveView('kitchen');
      setPin('');
    } else {
      alert('PIN Incorrecto (Default: 1234)');
      setPin('');
    }
  };

  const handlePayment = () => {
    if (!customerName) return alert("Ingresa tu nombre para el pedido");
    setIsPaying(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: `#COM-${Math.floor(100 + Math.random() * 899)}`,
        items: [...cart],
        total: cartTotal,
        status: OrderStatus.PENDING,
        paymentStatus: PaymentStatus.PAID,
        customerName,
        tableNumber,
        createdAt: Date.now()
      };
      setOrders(prev => [...prev, newOrder]);
      setCart([]);
      setCustomerName('');
      setTableNumber('');
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        setPaymentSuccess(false);
        setIsCartOpen(false);
      }, 2000);
    }, 1500);
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  const handleSaveItem = (item: FoodItem) => {
    if (editingItem) {
      setMenuItems(prev => prev.map(i => i.id === item.id ? item : i));
    } else {
      setMenuItems(prev => [...prev, { ...item, id: `item-${Date.now()}` }]);
    }
    setIsAdminFormOpen(false);
    setEditingItem(null);
  };

  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    try {
      const suggestions = await getSmartSuggestions(menuItems, orders);
      setAiSuggestions(suggestions);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingAI(false);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setRestaurantInfo(prev => ({ ...prev, logo: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  // --- RENDERIZADO ---

  return (
    <div className={`min-h-screen flex flex-col bg-[#FAF9F6] text-slate-900 font-sans transition-all duration-500 ${isStaffMode ? 'md:pl-28' : ''}`}>

      {/* SIDEBAR PARA PERSONAL */}
      {isStaffMode && (
        <nav className="fixed bottom-0 left-0 right-0 md:top-0 md:bottom-0 md:w-28 bg-white border-t md:border-t-0 md:border-r border-slate-200 z-50 flex md:flex-col justify-around md:justify-center items-center py-6 shadow-2xl md:shadow-none">
          <div className="hidden md:flex mb-10">
            {restaurantInfo.logo ? (
              <img src={restaurantInfo.logo} className="w-14 h-14 rounded-2xl object-cover shadow-lg" alt="Logo" />
            ) : (
              <div className="w-14 h-14 bg-slate-900 rounded-[20px] flex items-center justify-center">
                <Store className="text-white w-7 h-7" />
              </div>
            )}
          </div>
          <div className="flex md:flex-col gap-4 md:gap-8">
            <NavButton icon={<ChefHat />} active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} label="Cocina" badge={orders.filter(o => o.status !== OrderStatus.DELIVERED).length} />
            <NavButton icon={<ClipboardList />} active={activeView === 'orders'} onClick={() => setActiveView('orders')} label="Ventas" />
            <NavButton icon={<BarChart3 />} active={activeView === 'stats'} onClick={() => setActiveView('stats')} label="Stats" />
            <NavButton icon={<Sparkles />} active={activeView === 'ai'} onClick={() => setActiveView('ai')} label="IA" />
            <NavButton icon={<UtensilsCrossed />} active={activeView === 'admin'} onClick={() => setActiveView('admin')} label="Menú" />
            <button onClick={() => setIsStaffMode(false)} className="flex flex-col items-center gap-2 p-4 text-red-400 hover:text-red-600 transition-colors">
              <LogOut className="w-7 h-7" />
              <span className="text-[9px] font-black uppercase">Cerrar</span>
            </button>
          </div>
        </nav>
      )}

      {/* HEADER DINÁMICO */}
      <header className="sticky top-0 bg-white/90 backdrop-blur-xl border-b border-slate-100 px-8 py-6 flex justify-between items-center z-40">
        <div className="flex items-center gap-5">
          {restaurantInfo.logo ? (
            <img src={restaurantInfo.logo} className="w-12 h-12 rounded-xl object-cover shadow-md border border-slate-100" alt="Logo" />
          ) : (
            <div className="w-12 h-12 bg-orange-600 rounded-xl flex items-center justify-center shadow-lg shadow-orange-100">
              <UtensilsCrossed className="text-white w-6 h-6" />
            </div>
          )}
          <div>
            <h1 className="text-xl font-black tracking-tight uppercase">
              {restaurantInfo.name} <span className="text-orange-600 italic ml-2">{isStaffMode ? `| ${activeView.toUpperCase()}` : ''}</span>
            </h1>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mt-1">
              {isStaffMode ? 'Gestión Interna' : 'Kiosko de Autoservicio'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {!isStaffMode ? (
            <>
              <button onClick={() => setIsCartOpen(true)} className="flex items-center gap-4 bg-slate-900 text-white px-6 py-3.5 rounded-2xl hover:bg-orange-600 transition-all shadow-lg relative group">
                <ShoppingBag className="w-5 h-5" />
                {cart.length > 0 && (
                  <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                  </span>
                )}
                <span className="font-black text-sm">${cartTotal.toFixed(2)}</span>
              </button>
              <button onClick={() => setShowLogin(true)} className="p-3.5 bg-slate-100 text-slate-400 rounded-2xl hover:bg-slate-200 transition-colors" title="Acceso Personal">
                <Lock className="w-5 h-5" />
              </button>
            </>
          ) : (
            activeView === 'admin' && (
              <button onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }} className="flex items-center gap-2 bg-slate-900 text-white px-6 py-3 rounded-2xl font-black text-xs hover:bg-orange-600 transition-all shadow-sm">
                <Plus className="w-4 h-4" /> Agregar Plato
              </button>
            )
          )}
        </div>
      </header>

      <main className="flex-1 p-6 md:p-12 max-w-[1400px] mx-auto w-full">

        {/* VISTA CLIENTE */}
        {!isStaffMode && (
          <div className="space-y-12 animate-in fade-in duration-700">
            <div className="flex overflow-x-auto pb-4 no-scrollbar gap-4 -mx-4 px-4 items-center">
              <CategoryBtn label="Todas" icon="🔥" active={activeCategory === 'Todas'} onClick={() => setActiveCategory('Todas')} />
              {CATEGORIES.map(cat => <CategoryBtn key={cat.id} label={cat.id} icon={cat.icon} active={activeCategory === cat.id} onClick={() => setActiveCategory(cat.id)} />)}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[40px] border border-slate-100 overflow-hidden hover:shadow-2xl transition-all duration-500 group flex flex-col h-full shadow-sm">
                  <div className="relative h-64 overflow-hidden bg-slate-100">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                  </div>
                  <div className="p-8 flex flex-col flex-1">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="text-xl font-black text-slate-800">{item.name}</h3>
                      <span className="text-lg font-black text-orange-600">${item.price.toFixed(2)}</span>
                    </div>
                    <p className="text-slate-400 text-xs font-medium leading-relaxed mb-8 line-clamp-2">{item.description}</p>
                    <button onClick={() => addToCart(item)} className="mt-auto w-full py-4 bg-slate-50 text-slate-900 rounded-2xl font-black text-sm flex items-center justify-center gap-2 hover:bg-slate-900 hover:text-white transition-all active:scale-95 border-2 border-slate-100">
                      <Plus className="w-4 h-4" /> Agregar
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VISTAS PERSONAL */}
        {isStaffMode && (
          <div className="animate-in slide-in-from-right duration-500">
            {activeView === 'kitchen' && <KitchenMonitor orders={orders} updateStatus={updateOrderStatus} />}

            {activeView === 'admin' && (
              <div className="space-y-12">
                {/* Configuración del Restaurante */}
                <div className="bg-white rounded-[40px] p-10 border border-slate-100 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-10 items-center">
                  <div className="space-y-6">
                    <h3 className="text-2xl font-black italic">Ajustes del <span className="text-orange-600 not-italic">Restaurante</span></h3>
                    <div className="space-y-4">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-2">Nombre Comercial</label>
                      <input 
                        type="text" 
                        value={restaurantInfo.name} 
                        onChange={e => setRestaurantInfo(prev => ({ ...prev, name: e.target.value }))}
                        className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold"
                      />
                    </div>
                  </div>
                  <div className="flex flex-col items-center gap-4">
                    <div className="relative group">
                      <div className="w-24 h-24 rounded-3xl overflow-hidden bg-slate-100 border-2 border-dashed border-slate-200 flex items-center justify-center">
                        {restaurantInfo.logo ? (
                          <img src={restaurantInfo.logo} className="w-full h-full object-cover" alt="Logo preview" />
                        ) : (
                          <Store className="w-10 h-10 text-slate-300" />
                        )}
                      </div>
                      <label className="absolute -bottom-2 -right-2 bg-slate-900 text-white p-2 rounded-full cursor-pointer shadow-lg hover:bg-orange-600 transition-colors">
                        <Camera className="w-4 h-4" />
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                      </label>
                    </div>
                    <p className="text-[10px] font-black uppercase text-slate-400">Subir Logo</p>
                  </div>
                </div>

                {/* Gestión de Platos */}
                <div className="space-y-6">
                  <div className="relative w-full max-w-md">
                    <input type="text" placeholder="Buscar plato..." value={adminSearch} onChange={(e) => setAdminSearch(e.target.value)} className="w-full pl-12 pr-6 py-4 bg-white border border-slate-200 rounded-2xl focus:border-orange-500 outline-none transition-all font-bold text-sm shadow-sm" />
                    <Search className="absolute left-4 top-4 w-4 h-4 text-slate-300" />
                  </div>
                  <div className="bg-white rounded-[40px] border border-slate-100 overflow-hidden shadow-sm">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 border-b border-slate-100 font-black text-[10px] uppercase text-slate-400">
                        <tr>
                          <th className="p-6">Producto</th>
                          <th className="p-6">Categoría</th>
                          <th className="p-6">Precio</th>
                          <th className="p-6 text-right">Acción</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50 font-bold text-sm">
                        {filteredAdminMenu.map(item => (
                          <tr key={item.id} className="hover:bg-slate-50/50">
                            <td className="p-6 flex items-center gap-4">
                              <img src={item.image} className="w-12 h-12 rounded-xl object-cover" alt="" />
                              <span className="font-black">{item.name}</span>
                            </td>
                            <td className="p-6"><span className="bg-slate-100 px-3 py-1 rounded-full text-[9px] uppercase">{item.category}</span></td>
                            <td className="p-6 text-orange-600">${item.price.toFixed(2)}</td>
                            <td className="p-6 text-right">
                              <div className="flex justify-end gap-2">
                                <button onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }} className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-orange-600"><Edit2 className="w-4 h-4" /></button>
                                <button onClick={() => setMenuItems(prev => prev.filter(i => i.id !== item.id))} className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {activeView === 'orders' && <HistoryView orders={orders} />}
            {activeView === 'stats' && <StatsView orders={orders} />}
            {activeView === 'ai' && <AIView menu={menuItems} orders={orders} fetchAISuggestions={fetchAISuggestions} loadingAI={loadingAI} aiSuggestions={aiSuggestions} />}
          </div>
        )}
      </main>

      {/* LOGIN MODAL */}
      {showLogin && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[40px] p-10 shadow-3xl text-center">
            <Lock className="w-12 h-12 text-slate-900 mx-auto mb-6" />
            <h2 className="text-2xl font-black mb-2">Modo Staff</h2>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-8">Ingresa el PIN de acceso</p>
            <form onSubmit={handleLogin} className="space-y-6">
              <input type="password" maxLength={4} value={pin} onChange={e => setPin(e.target.value)} placeholder="••••" className="w-full text-center text-4xl tracking-[1em] py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-slate-900 outline-none font-black" autoFocus />
              <div className="flex gap-4">
                <button type="button" onClick={() => setShowLogin(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-sm">Cerrar</button>
                <button type="submit" className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black text-sm shadow-lg shadow-slate-200">Acceder</button>
              </div>
            </form>
            <p className="mt-8 text-[9px] font-bold text-slate-300 uppercase tracking-widest">Pin por defecto: 1234</p>
          </div>
        </div>
      )}

      {/* MODAL ADMIN FORM (AÑADIR/EDITAR PLATO) */}
      {isAdminFormOpen && (
        <AdminForm item={editingItem} onSave={handleSaveItem} onClose={() => setIsAdminFormOpen(false)} />
      )}

      {/* CARRITO CLIENTE */}
      {isCartOpen && (
        <div className="fixed inset-0 z-[60] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-md" onClick={() => !isPaying && setIsCartOpen(false)} />
          <div className="relative w-full max-w-lg bg-white shadow-2xl flex flex-col transform transition-transform duration-500 animate-in slide-in-from-right">
            <div className="p-10 border-b border-slate-50 flex justify-between items-center">
              <h2 className="text-3xl font-black tracking-tighter italic">Tu <span className="text-orange-600 not-italic">Orden</span></h2>
              <button onClick={() => setIsCartOpen(false)} className="p-3 bg-slate-50 rounded-full"><X className="w-5 h-5 text-slate-400" /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-10 space-y-8">
              {cart.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-20"><ShoppingBasket className="w-24 h-24 mb-4" /><p className="font-black uppercase tracking-widest text-xs">Sin productos</p></div>
              ) : (
                <>
                  <div className="space-y-6">
                    {cart.map(item => (
                      <div key={item.id} className="flex items-center gap-6">
                        <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-sm" alt="" />
                        <div className="flex-1">
                          <h4 className="font-black text-slate-900 text-sm">{item.name}</h4>
                          <p className="text-orange-600 font-black text-xs">${item.price.toFixed(2)}</p>
                          <div className="flex items-center gap-3 mt-1">
                            <button onClick={() => updateQuantity(item.id, -1)} className="p-1.5 bg-slate-100 rounded-lg"><Minus className="w-3 h-3" /></button>
                            <span className="font-black text-sm">{item.quantity}</span>
                            <button onClick={() => updateQuantity(item.id, 1)} className="p-1.5 bg-slate-100 rounded-lg"><Plus className="w-3 h-3" /></button>
                          </div>
                        </div>
                        <div className="font-black text-sm">${(item.price * item.quantity).toFixed(2)}</div>
                      </div>
                    ))}
                  </div>
                  <div className="pt-8 border-t border-slate-100 space-y-4">
                    <input type="text" placeholder="Nombre para el pedido" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-900 font-bold" />
                    <input type="text" placeholder="Número de Mesa (Opcional)" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-900 font-bold" />
                  </div>
                </>
              )}
            </div>
            <div className="p-10 border-t border-slate-100 bg-white shadow-xl">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Total</span>
                <div className="text-5xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button onClick={handlePayment} disabled={cart.length === 0 || !customerName || isPaying} className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-orange-600 shadow-slate-200'}`}>
                {isPaying ? 'Enviando...' : paymentSuccess ? '¡Comanda en Cocina!' : 'Confirmar Pedido'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- COMPONENTES ATÓMICOS ---

const KitchenMonitor = ({ orders, updateStatus }: any) => (
  <div className="space-y-10">
    <div className="flex justify-between items-center">
      <h2 className="text-4xl font-black tracking-tighter">Comandas Activas</h2>
    </div>
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
      {orders.filter((o: any) => o.status !== OrderStatus.DELIVERED).sort((a: any, b: any) => a.createdAt - b.createdAt).map((order: any, idx: number) => (
        <div key={order.id} className={`bg-white rounded-3xl overflow-hidden flex flex-col border-t-[8px] shadow-sm ${idx === 0 ? 'border-red-500 ring-4 ring-red-50' : 'border-slate-800'}`}>
          <div className="p-6 border-b border-slate-50">
            <div className="flex justify-between items-start mb-4"><span className="text-xl font-black">{order.id}</span><OrderTimer startTime={order.createdAt} /></div>
            <p className="font-black text-slate-800 text-sm uppercase tracking-widest">{order.customerName} {order.tableNumber ? `• M-${order.tableNumber}` : ''}</p>
          </div>
          <div className="p-6 flex-1 space-y-4">
            {order.items.map((item: any) => (
              <div key={item.id} className="flex items-center gap-4">
                <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center font-black text-xs">{item.quantity}</div>
                <span className="font-bold text-sm text-slate-700">{item.name}</span>
              </div>
            ))}
          </div>
          <div className="p-6 bg-slate-50">
            <button onClick={() => updateStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)} className={`w-full py-3.5 rounded-xl font-black text-xs uppercase tracking-widest shadow-sm transition-all ${order.status === OrderStatus.PENDING ? 'bg-orange-600 text-white' : order.status === OrderStatus.PREPARING ? 'bg-blue-600 text-white' : 'bg-emerald-600 text-white'}`}>
              {order.status === OrderStatus.PENDING ? 'Comenzar Preparación' : order.status === OrderStatus.PREPARING ? 'Marcar como Listo' : 'Entregar'}
            </button>
          </div>
        </div>
      ))}
    </div>
  </div>
);

const NavButton: React.FC<{ icon: React.ReactNode, active: boolean, onClick: () => void, label: string, badge?: number }> = ({ icon, active, onClick, label, badge }) => (
  <button onClick={onClick} className={`relative flex flex-col items-center gap-2 p-4 rounded-[28px] transition-all group ${active ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-300 hover:text-slate-600'}`}>
    <div className={`${active ? 'scale-110' : ''} transition-transform`}>{React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}</div>
    <span className="text-[8px] font-black uppercase tracking-widest">{label}</span>
    {badge !== undefined && badge > 0 && <span className="absolute top-2 right-2 bg-red-600 text-white text-[9px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">{badge}</span>}
  </button>
);

const CategoryBtn: React.FC<{ label: string, icon: string, active: boolean, onClick: () => void }> = ({ label, icon, active, onClick }) => (
  <button onClick={onClick} className={`flex items-center gap-3 px-6 py-4 rounded-full transition-all border-2 whitespace-nowrap ${active ? 'bg-slate-900 text-white border-slate-900 shadow-xl' : 'bg-white text-slate-500 border-slate-50 hover:border-orange-200 shadow-sm'}`}>
    <span className="text-2xl">{icon}</span><span className="font-black text-xs uppercase tracking-widest">{label}</span>
  </button>
);

const AdminForm: React.FC<{ item: FoodItem | null, onSave: (item: FoodItem) => void, onClose: () => void }> = ({ item, onSave, onClose }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState<FoodItem>(item || {
    id: '', name: '', price: 0, category: 'Hamburguesas', 
    image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=400&h=300', 
    description: ''
  });

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, image: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.price <= 0) return alert('Por favor, completa nombre y precio');
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="relative bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
        <div className="md:w-5/12 bg-slate-50 p-10 flex flex-col items-center justify-center border-r border-slate-100">
          <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest mb-8 italic">Vista del Cliente</p>
          <div className="bg-white rounded-3xl shadow-xl w-full overflow-hidden border border-slate-200/50">
            <img src={formData.image} className="w-full h-48 object-cover" alt="" />
            <div className="p-6">
              <h4 className="text-lg font-black text-slate-900">{formData.name || 'Producto Nuevo'}</h4>
              <p className="text-orange-600 font-black text-sm mb-2">${formData.price.toFixed(2)}</p>
              <p className="text-slate-400 text-[10px] line-clamp-2">{formData.description || 'Aquí verán la descripción los clientes...'}</p>
            </div>
          </div>
        </div>
        <form onSubmit={handleSubmit} className="md:w-7/12 p-10 overflow-y-auto space-y-6 bg-white">
