                <div className="space-y-12">
                  <div className="bg-white rounded-[40px] p-10 border border-slate-100 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-10 items-center">
                    <div className="space-y-6">
                      <h3 className="text-2xl font-black italic">Ajustes <span className="text-orange-600 not-italic">Visuales</span></h3>
                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-2">Nombre del Restaurante</label>
