                          <Camera className="w-5 h-5" />
                          <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                        </label>
                      </div>
                      <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Actualizar Logo</p>
                    </div>
                  </div>

                  <div className="space-y-6">
                    <div className="relative w-full max-w-md">
                      <input type="text" placeholder="Buscar en el menú..." value={adminSearch} onChange={(e) => setAdminSearch(e.target.value)} className="w-full pl-12 pr-6 py-4 bg-white border border-slate-200 rounded-2xl focus:border-orange-500 outline-none transition-all font-bold text-sm shadow-sm" />
                      <Search className="absolute left-4 top-4 w-4 h-4 text-slate-300" />
                    </div>
                    <div className="bg-white rounded-[40px] border border-slate-100 overflow-hidden shadow-sm">
