  <button onClick={onClick} className={`relative w-full flex items-center gap-4 p-4 rounded-2xl transition-all group ${active ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}>
    <div className={`${active ? 'scale-110' : ''} transition-transform`}>{React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}</div>
    <span className="text-xs font-black uppercase tracking-widest">{label}</span>
    {badge !== undefined && badge > 0 && <span className="absolute top-4 right-4 bg-red-600 text-white text-[9px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white">{badge}</span>}
  </button>
);

const SidebarCategoryBtn: React.FC<{ label: string, icon: string, active: boolean, onClick: () => void }> = ({ label, icon, active, onClick }) => (
  <button onClick={onClick} className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all group border-2 ${active ? 'bg-white border-orange-500 text-orange-600 shadow-lg shadow-orange-50 translate-x-1' : 'bg-transparent border-transparent text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
    <div className="flex items-center gap-4">
      <span className="text-2xl group-hover:scale-125 transition-transform duration-300">{icon}</span>
      <span className="font-black text-xs uppercase tracking-widest">{label}</span>
