const KitchenMonitor = ({ orders, updateStatus }: any) => (
  <div className="space-y-10">
    <h2 className="text-4xl font-black tracking-tighter">Comandas Activas</h2>
    <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
      {orders.filter((o: any) => o.status !== OrderStatus.DELIVERED).sort((a: any, b: any) => a.createdAt - b.createdAt).map((order: any, idx: number) => (
        <div key={order.id} className={`bg-white rounded-[32px] overflow-hidden flex flex-col border-t-[8px] shadow-sm ${idx === 0 ? 'border-red-500 ring-4 ring-red-50' : 'border-slate-800'}`}>
          <div className="p-6 border-b border-slate-50">
            <div className="flex justify-between items-start mb-4"><span className="text-xl font-black">{order.id}</span><OrderTimer startTime={order.createdAt} /></div>
            <p className="font-black text-slate-800 text-sm uppercase tracking-widest">{order.customerName} {order.tableNumber ? `• M-${order.tableNumber}` : ''}</p>
          </div>
          <div className="p-6 flex-1 space-y-4">
            {order.items.map((item: any) => (
              <div key={item.id} className="flex items-center gap-4">
                <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center font-black text-xs">{item.quantity}</div>
                <span className="font-bold text-sm text-slate-700">{item.name}</span>
              </div>
            ))}
          </div>
          <div className="p-6 bg-slate-50">
            <button onClick={() => updateStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-sm transition-all ${order.status === OrderStatus.PENDING ? 'bg-orange-600 text-white' : order.status === OrderStatus.PREPARING ? 'bg-blue-600 text-white' : 'bg-emerald-600 text-white'}`}>
              {order.status === OrderStatus.PENDING ? 'Comenzar Preparación' : order.status === OrderStatus.PREPARING ? 'Marcar como Listo' : 'Entregar'}
            </button>
          </div>
        </div>
      ))}
    </div>
  </div>
);

const AdminForm: React.FC<{ item: FoodItem | null, onSave: (item: FoodItem) => void, onClose: () => void }> = ({ item, onSave, onClose }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState<FoodItem>(item || { id: '', name: '', price: 0, category: 'Hamburguesas', image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=400&h=300', description: '' });
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, image: reader.result as string });
      reader.readAsDataURL(file);
    }
  };
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.price <= 0) return alert('Datos incompletos');
    onSave(formData);
  };
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-md">
      <div className="relative bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col md:flex-row max-h-[90vh]">
        <div className="md:w-5/12 bg-slate-50 p-10 flex flex-col items-center justify-center border-r border-slate-100">
          <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest mb-8 italic">Vista Cliente</p>
          <div className="bg-white rounded-3xl shadow-xl w-full overflow-hidden border border-slate-200/50">
            <img src={formData.image} className="w-full h-48 object-cover" alt="" /><div className="p-6"><h4 className="text-lg font-black text-slate-900">{formData.name || 'Producto'}</h4><p className="text-orange-600 font-black text-sm mb-2">${formData.price.toFixed(2)}</p><p className="text-slate-400 text-[10px] line-clamp-2">{formData.description || 'Descripción...'}</p></div>
          </div>
        </div>
        <form onSubmit={handleSubmit} className="md:w-7/12 p-10 overflow-y-auto space-y-6 bg-white">
          <div className="flex justify-between items-center mb-4"><h2 className="text-2xl font-black">{item ? 'Editar Plato' : 'Nuevo Plato'}</h2><button type="button" onClick={onClose} className="p-2 hover:bg-slate-50 rounded-full"><X className="w-6 h-6 text-slate-300" /></button></div>
          <div className="space-y-4"><label className="text-[10px] font-black uppercase text-slate-400">Nombre</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-4 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold" /></div>
          <div className="grid grid-cols-2 gap-4"><div className="space-y-4"><label className="text-[10px] font-black uppercase text-slate-400">Precio</label><input type="number" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})} className="w-full px-6 py-4 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold" /></div><div className="space-y-4"><label className="text-[10px] font-black uppercase text-slate-400">Categoría</label><select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})} className="w-full px-6 py-4 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold appearance-none">{CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.id}</option>)}</select></div></div>
          <div className="space-y-4"><label className="text-[10px] font-black uppercase text-slate-400">Imagen</label><div className="flex gap-4"><input type="text" value={formData.image.startsWith('data:') ? 'Imagen Cargada' : formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="flex-1 px-6 py-4 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold" /><label className="p-4 bg-slate-900 text-white rounded-xl cursor-pointer hover:bg-orange-600 transition-colors shadow-lg"><Upload className="w-5 h-5" /><input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} /></label></div></div>
          <div className="space-y-4"><label className="text-[10px] font-black uppercase text-slate-400">Descripción</label><textarea rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold resize-none" /></div>
          <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-orange-600 transition-all shadow-xl">Guardar</button>
        </form>
      </div>
    </div>
  );
};

const HistoryView = ({ orders }: { orders: Order[] }) => (
  <div className="max-w-4xl mx-auto space-y-6">
    <h2 className="text-3xl font-black mb-8 italic">Ventas <span className="text-orange-600 not-italic">Realizadas</span></h2>
    {orders.slice().reverse().map(order => (
      <div key={order.id} className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between gap-6">
        <div><div className="flex items-center gap-3 mb-2"><span className="text-lg font-black">{order.id}</span><StatusBadge status={order.status} /></div><p className="font-bold text-slate-800 uppercase tracking-widest text-sm">{order.customerName}</p><p className="text-[10px] text-slate-400 font-bold">{new Date(order.createdAt).toLocaleString()}</p></div>
        <div className="text-right flex flex-col justify-center"><p className="text-3xl font-black text-slate-900 tracking-tighter">${order.total.toFixed(2)}</p><div className="flex gap-2 flex-wrap justify-end mt-2">{order.items.map(i => <span key={i.id} className="bg-slate-50 px-2 py-1 rounded-lg text-[9px] font-black border border-slate-100 uppercase">{i.quantity}x {i.name}</span>)}</div></div>
      </div>
    ))}
  </div>
);

const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => { o.items.forEach(item => { data[item.name] = (data[item.name] || 0) + item.quantity; }); });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);
  return (
    <div className="space-y-10">
      <h2 className="text-3xl font-black">Rendimiento</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard label="Ingresos" value={`$${orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((a, b) => a + b.total, 0).toFixed(2)}`} icon={<DollarSign className="text-emerald-500" />} />
        <StatCard label="Pedidos" value={orders.length.toString()} icon={<ShoppingBag className="text-blue-500" />} />
        <StatCard label="Ticket Promedio" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(2) : '0'}`} icon={<Timer className="text-orange-500" />} />
      </div>
      <div className="bg-white p-10 rounded-[40px] border border-slate-100 h-[350px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={salesData}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 700 }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 700 }} /><Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)' }} /><Bar dataKey="value" fill="#f97316" radius={[8, 8, 0, 0]} barSize={35} /></BarChart></ResponsiveContainer></div>
    </div>
  );
};

const AIView = ({ menu, orders, fetchAISuggestions, loadingAI, aiSuggestions }: any) => (
  <div className="space-y-10">
    <div className="bg-slate-900 rounded-[40px] p-12 text-white relative overflow-hidden shadow-2xl">
      <div className="relative z-10 max-w-xl"><h2 className="text-4xl font-black mb-4 flex items-center gap-3"><Sparkles className="text-orange-500 w-10 h-10" /> Gemini Strategy</h2><p className="text-lg text-slate-400 font-medium mb-8 leading-relaxed">Asistente de IA para optimizar tu negocio.</p><button onClick={fetchAISuggestions} disabled={loadingAI} className="px-10 py-4 bg-white text-slate-900 rounded-full font-black text-xs uppercase tracking-widest hover:bg-orange-500 hover:text-white transition-all shadow-xl">{loadingAI ? 'Analizando...' : 'Actualizar IA'}</button></div>
    </div>
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
      {aiSuggestions.map((s: any, idx: number) => (
        <div key={idx} className="bg-white p-8 rounded-3xl border border-slate-100 hover:border-orange-200 transition-all group shadow-sm"><span className={`text-[9px] font-black px-3 py-1 rounded-full border mb-4 inline-block uppercase tracking-widest ${s.impact === 'Alta' ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600'}`}>{s.impact} Impacto</span><h3 className="text-xl font-black mb-3 group-hover:text-orange-600 transition-colors">{s.title}</h3><p className="text-slate-500 text-xs font-medium leading-relaxed">{s.description}</p></div>
      ))}
    </div>
  </div>
