const OrderTimer: React.FC<{ startTime: number }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60)), 10000);
    setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    return () => clearInterval(interval);
  }, [startTime]);

  return (
    <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${
      elapsed > 15 ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white'
    }`}>
      <Timer className="w-3 h-3" /> {elapsed} min
    </div>
  );
};

// --- APP PRINCIPAL ---

const App: React.FC = () => {
  // --- PERSISTENCIA Y ESTADO INICIAL ---
  const [isStaffMode, setIsStaffMode] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [pin, setPin] = useState('');
  const [activeView, setActiveView] = useState<ViewType>('menu');

  const [menuItems, setMenuItems] = useState<FoodItem[]>(() => {
    const saved = localStorage.getItem('fastfood_menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [restaurantInfo, setRestaurantInfo] = useState({
    name: localStorage.getItem('fastfood_name') || 'Santa Parrilla',
    logo: localStorage.getItem('fastfood_logo') || ''
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('fastfood_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [cart, setCart] = useState<OrderItem[]>([]);
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);

  // Admin State
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);
  const [isAdminFormOpen, setIsAdminFormOpen] = useState(false);
  const [adminSearch, setAdminSearch] = useState('');

  // Efectos para persistencia
  useEffect(() => localStorage.setItem('fastfood_menu', JSON.stringify(menuItems)), [menuItems]);
  useEffect(() => localStorage.setItem('fastfood_orders', JSON.stringify(orders)), [orders]);
  useEffect(() => {
    localStorage.setItem('fastfood_name', restaurantInfo.name);
    localStorage.setItem('fastfood_logo', restaurantInfo.logo);
  }, [restaurantInfo]);

  useEffect(() => {
    if (activeView === 'ai' && aiSuggestions.length === 0) {
      fetchAISuggestions();
    }
  }, [activeView]);

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [activeCategory, menuItems]);

  const filteredAdminMenu = useMemo(() => {
    return menuItems.filter(item => 
      item.name.toLowerCase().includes(adminSearch.toLowerCase()) || 
      item.category.toLowerCase().includes(adminSearch.toLowerCase())
    );
  }, [menuItems, adminSearch]);

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => i.id === itemId ? { ...i, quantity: Math.max(0, i.quantity + delta) } : i).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (pin === '1234') { 
      setIsStaffMode(true);
      setShowLogin(false);
      setActiveView('kitchen');
      setPin('');
    } else {
      alert('PIN Incorrecto (Default: 1234)');
      setPin('');
    }
  };

  const handlePayment = () => {
    if (!customerName) return alert("Ingresa tu nombre para el pedido");
    setIsPaying(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: `#COM-${Math.floor(100 + Math.random() * 899)}`,
        items: [...cart],
        total: cartTotal,
        status: OrderStatus.PENDING,
        paymentStatus: PaymentStatus.PAID,
        customerName,
        tableNumber,
        createdAt: Date.now()
      };
      setOrders(prev => [...prev, newOrder]);
      setCart([]);
      setCustomerName('');
      setTableNumber('');
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        setPaymentSuccess(false);
        setIsCartOpen(false);
      }, 2000);
    }, 1500);
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    try {
      const suggestions = await getSmartSuggestions(menuItems, orders);
      setAiSuggestions(suggestions);
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setLoadingAI(false);
    }
  };

  const handleSaveItem = (item: FoodItem) => {
    if (editingItem) {
      setMenuItems(prev => prev.map(i => i.id === item.id ? item : i));
    } else {
      setMenuItems(prev => [...prev, { ...item, id: `item-${Date.now()}` }]);
    }
    setIsAdminFormOpen(false);
    setEditingItem(null);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setRestaurantInfo(prev => ({ ...prev, logo: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col md:flex-row bg-[#FAF9F6] text-slate-900 font-sans transition-all duration-300`}>

      {/* BARRA LATERAL (NEGRA Y COLAPSABLE) */}
      <nav className={`fixed bottom-0 left-0 right-0 md:top-0 md:bottom-0 ${isSidebarCollapsed ? 'md:w-24' : 'md:w-80'} bg-slate-950 text-white z-50 flex flex-col transition-all duration-500 shadow-2xl`}>

        {/* BOTÓN COLAPSAR (Desktop only) */}
        <button 
          onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          className="hidden md:flex absolute -right-4 top-10 w-8 h-8 bg-orange-600 rounded-full items-center justify-center text-white shadow-xl hover:scale-110 transition-transform z-[60]"
        >
          {isSidebarCollapsed ? <ChevronLast className="w-5 h-5" /> : <ChevronFirst className="w-5 h-5" />}
        </button>

        {/* LOGO Y NOMBRE */}
        <div className={`p-8 pb-4 flex flex-col items-center text-center transition-all duration-500 overflow-hidden ${isSidebarCollapsed ? 'p-4' : 'p-8'}`}>
          <div className="relative group mb-6">
            {restaurantInfo.logo ? (
              <img 
                src={restaurantInfo.logo} 
                className={`${isSidebarCollapsed ? 'w-12 h-12' : 'w-40 h-40 md:w-48 md:h-48'} rounded-3xl object-cover shadow-2xl border-2 border-white/10 ring-1 ring-white/5 transition-all duration-500`} 
                alt="Logo" 
              />
            ) : (
              <div className={`${isSidebarCollapsed ? 'w-12 h-12' : 'w-40 h-40 md:w-48 md:h-48'} bg-orange-600 rounded-[30px] flex items-center justify-center shadow-2xl shadow-orange-900/40 transition-all duration-500`}>
                <UtensilsCrossed className={`${isSidebarCollapsed ? 'w-6 h-6' : 'w-20 h-20'} text-white transition-all duration-500`} />
              </div>
            )}
          </div>

          <div className={`transition-all duration-500 ${isSidebarCollapsed ? 'opacity-0 h-0 scale-90' : 'opacity-100 h-auto scale-100'}`}>
            <h1 className="text-2xl font-black tracking-tighter uppercase leading-tight px-2 text-white">
              {restaurantInfo.name}
            </h1>
            <div className="w-12 h-1 bg-orange-500 rounded-full mx-auto mt-4 mb-2"></div>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">
              {isStaffMode ? 'Staff Panel' : 'Bienvenido'}
            </p>
          </div>
        </div>

        {/* NAVEGACIÓN VERTICAL */}
        <div className="flex-1 px-4 py-6 space-y-2 overflow-y-auto no-scrollbar">
          {isStaffMode ? (
            <div className="space-y-2">
              <NavButton icon={<ChefHat />} active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} label="Cocina" badge={orders.filter(o => o.status !== OrderStatus.DELIVERED).length} collapsed={isSidebarCollapsed} dark />
              <NavButton icon={<ClipboardList />} active={activeView === 'orders'} onClick={() => setActiveView('orders')} label="Ventas" collapsed={isSidebarCollapsed} dark />
              <NavButton icon={<BarChart3 />} active={activeView === 'stats'} onClick={() => setActiveView('stats')} label="Métricas" collapsed={isSidebarCollapsed} dark />
              <NavButton icon={<Sparkles />} active={activeView === 'ai'} onClick={() => setActiveView('ai')} label="IA Strategy" collapsed={isSidebarCollapsed} dark />
              <NavButton icon={<UtensilsCrossed />} active={activeView === 'admin'} onClick={() => setActiveView('admin')} label="Menú" collapsed={isSidebarCollapsed} dark />

              <div className="pt-6">
                <button 
                  onClick={() => setIsStaffMode(false)} 
                  className={`w-full flex items-center ${isSidebarCollapsed ? 'justify-center' : 'gap-4'} p-4 rounded-2xl text-red-400 hover:bg-red-500/10 transition-colors`}
                  title="Cerrar Modo Staff"
                >
                  <LogOut className="w-6 h-6" />
                  {!isSidebarCollapsed && <span className="text-xs font-black uppercase tracking-widest">Salir</span>}
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-2">
              {!isSidebarCollapsed && <p className="text-[9px] font-black text-slate-600 uppercase tracking-widest px-4 mb-4">Categorías</p>}
              <SidebarCategoryBtn label="Todas" icon="🔥" active={activeCategory === 'Todas'} onClick={() => setActiveCategory('Todas')} collapsed={isSidebarCollapsed} />
              {CATEGORIES.map(cat => (
                <SidebarCategoryBtn key={cat.id} label={cat.id} icon={cat.icon} active={activeCategory === cat.id} onClick={() => setActiveCategory(cat.id)} collapsed={isSidebarCollapsed} />
              ))}
            </div>
          )}
        </div>

        {/* LOGIN DISCRETO */}
        {!isStaffMode && (
          <div className="p-4 border-t border-white/5">
            <button 
              onClick={() => setShowLogin(true)} 
              className={`w-full flex items-center justify-center gap-2 p-3 text-slate-600 hover:text-white transition-colors text-[10px] font-black uppercase tracking-widest`}
              title="Acceso Personal"
            >
              <Lock className="w-4 h-4" />
              {!isSidebarCollapsed && <span>Modo Staff</span>}
            </button>
          </div>
        )}
      </nav>

      {/* CONTENIDO PRINCIPAL */}
      <div className={`flex-1 transition-all duration-500 ${isSidebarCollapsed ? 'md:ml-24' : 'md:ml-80'} flex flex-col min-h-screen`}>

        <header className="sticky top-0 bg-[#FAF9F6]/80 backdrop-blur-xl px-8 py-6 flex justify-between items-center z-40">
          <div>
            {!isStaffMode ? (
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Menú Actual:</span>
                <span className="bg-slate-900 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest animate-in fade-in">
                  {activeCategory}
                </span>
              </div>
            ) : (
              <h2 className="text-xl font-black uppercase tracking-tighter text-slate-900">
                {activeView} <span className="text-orange-600 italic">Admin</span>
              </h2>
            )}
          </div>

          <div className="flex items-center gap-4">
            {!isStaffMode && (
              <button onClick={() => setIsCartOpen(true)} className="flex items-center gap-4 bg-slate-900 text-white px-6 py-3.5 rounded-2xl hover:bg-orange-600 transition-all shadow-2xl relative group">
                <ShoppingBag className="w-5 h-5 group-hover:rotate-12 transition-transform" />
                {cart.length > 0 && (
                  <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-[#FAF9F6] animate-bounce">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                  </span>
                )}
                <span className="font-black text-sm">${cartTotal.toFixed(2)}</span>
              </button>
            )}
            {isStaffMode && activeView === 'admin' && (
              <button onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }} className="flex items-center gap-2 bg-orange-600 text-white px-6 py-3 rounded-2xl font-black text-xs hover:bg-slate-900 transition-all shadow-lg">
                <Plus className="w-4 h-4" /> Nuevo Plato
              </button>
            )}
          </div>
        </header>

        <main className="flex-1 p-6 md:p-10 w-full animate-in fade-in duration-500">
          {!isStaffMode && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[40px] border border-slate-100 overflow-hidden hover:shadow-2xl transition-all duration-500 group flex flex-col h-full shadow-sm">
                  <div className="relative h-64 overflow-hidden bg-slate-50">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                    <div className="absolute top-4 right-4 bg-slate-900/80 backdrop-blur px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest border border-white/20">
                      {item.category}
                    </div>
                  </div>
                  <div className="p-8 flex flex-col flex-1">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="text-xl font-black text-slate-800 leading-tight">{item.name}</h3>
                      <span className="text-lg font-black text-orange-600">${item.price.toFixed(2)}</span>
                    </div>
                    <p className="text-slate-400 text-xs font-medium leading-relaxed mb-8 line-clamp-2">{item.description}</p>
                    <button onClick={() => addToCart(item)} className="mt-auto w-full py-4 bg-slate-50 text-slate-900 rounded-2xl font-black text-sm flex items-center justify-center gap-2 hover:bg-slate-900 hover:text-white transition-all active:scale-95 border-2 border-slate-100">
                      <Plus className="w-4 h-4" /> Ordenar Ahora
                    </button>
                  </div>
                </div>
              ))}
              {filteredMenu.length === 0 && (
                <div className="col-span-full py-20 text-center opacity-30">
                  <ShoppingBasket className="w-20 h-20 mx-auto mb-6" />
                  <p className="font-black uppercase tracking-widest">Sin platos disponibles</p>
                </div>
              )}
            </div>
          )}

          {isStaffMode && (
            <div className="animate-in slide-in-from-right duration-500">
              {activeView === 'kitchen' && <KitchenMonitor orders={orders} updateStatus={updateOrderStatus} />}
              {activeView === 'admin' && (
                <div className="space-y-12">
                  <div className="bg-white rounded-[40px] p-10 border border-slate-100 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-10 items-center">
                    <div className="space-y-6">
                      <h3 className="text-2xl font-black italic">Branding del <span className="text-orange-600 not-italic">Restaurante</span></h3>
                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-2">Nombre Comercial</label>
                        <input type="text" value={restaurantInfo.name} onChange={e => setRestaurantInfo(prev => ({ ...prev, name: e.target.value }))} className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-900 font-bold" />
                      </div>
                    </div>
                    <div className="flex flex-col items-center gap-4">
                      <div className="relative group">
                        <div className="w-32 h-32 rounded-3xl overflow-hidden bg-slate-100 border-2 border-dashed border-slate-200 flex items-center justify-center">
                          {restaurantInfo.logo ? <img src={restaurantInfo.logo} className="w-full h-full object-cover" alt="Logo preview" /> : <Store className="w-10 h-10 text-slate-300" />}
                        </div>
                        <label className="absolute -bottom-2 -right-2 bg-orange-600 text-white p-2.5 rounded-full cursor-pointer shadow-lg hover:bg-slate-900 transition-colors">
                          <Camera className="w-5 h-5" />
                          <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                        </label>
                      </div>
                      <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Logo Principal</p>
                    </div>
                  </div>

                  <div className="space-y-6">
                    <div className="relative w-full max-w-md">
                      <input type="text" placeholder="Buscar productos..." value={adminSearch} onChange={(e) => setAdminSearch(e.target.value)} className="w-full pl-12 pr-6 py-4 bg-white border border-slate-200 rounded-2xl focus:border-orange-500 outline-none transition-all font-bold text-sm shadow-sm" />
                      <Search className="absolute left-4 top-4 w-4 h-4 text-slate-300" />
                    </div>
                    <div className="bg-white rounded-[40px] border border-slate-100 overflow-hidden shadow-sm">
                      <table className="w-full text-left">
                        <thead className="bg-slate-50 border-b border-slate-100 font-black text-[10px] uppercase text-slate-400">
                          <tr><th className="p-6">Plato</th><th className="p-6">Categoría</th><th className="p-6">Precio</th><th className="p-6 text-right">Acción</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 font-bold text-sm">
                          {filteredAdminMenu.map(item => (
                            <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                              <td className="p-6 flex items-center gap-4"><img src={item.image} className="w-12 h-12 rounded-xl object-cover" alt="" /><span className="font-black">{item.name}</span></td>
                              <td className="p-6"><span className="bg-slate-100 px-3 py-1 rounded-full text-[9px] uppercase">{item.category}</span></td>
                              <td className="p-6 text-orange-600 font-black">${item.price.toFixed(2)}</td>
                              <td className="p-6 text-right">
                                <div className="flex justify-end gap-2">
                                  <button onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }} className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-orange-600"><Edit2 className="w-4 h-4" /></button>
                                  <button onClick={() => setMenuItems(prev => prev.filter(i => i.id !== item.id))} className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}
              {activeView === 'orders' && <HistoryView orders={orders} />}
              {activeView === 'stats' && <StatsView orders={orders} />}
              {activeView === 'ai' && <AIView menu={menuItems} orders={orders} fetchAISuggestions={fetchAISuggestions} loadingAI={loadingAI} aiSuggestions={aiSuggestions} />}
            </div>
          )}
        </main>
      </div>

      {/* MODALES */}
      {showLogin && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/90 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-[40px] p-10 shadow-3xl text-center">
            <Lock className="w-12 h-12 text-slate-900 mx-auto mb-6" />
            <h2 className="text-2xl font-black mb-2">Acceso Staff</h2>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-8">PIN de Seguridad</p>
            <form onSubmit={handleLogin} className="space-y-6">
              <input type="password" maxLength={4} value={pin} onChange={e => setPin(e.target.value)} placeholder="••••" className="w-full text-center text-4xl tracking-[1em] py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-slate-900 outline-none font-black" autoFocus />
              <div className="flex gap-4">
                <button type="button" onClick={() => setShowLogin(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-sm">Cancelar</button>
                <button type="submit" className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black text-sm">Entrar</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {isAdminFormOpen && <AdminForm item={editingItem} onSave={handleSaveItem} onClose={() => setIsAdminFormOpen(false)} />}

      {/* CARRITO */}
      {isCartOpen && (
        <div className="fixed inset-0 z-[60] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => !isPaying && setIsCartOpen(false)} />
          <div className="relative w-full max-w-lg bg-white shadow-2xl flex flex-col transform transition-transform duration-500 animate-in slide-in-from-right">
            <div className="p-10 border-b border-slate-50 flex justify-between items-center">
              <h2 className="text-3xl font-black tracking-tighter italic">Tu <span className="text-orange-600 not-italic">Pedido</span></h2>
              <button onClick={() => setIsCartOpen(false)} className="p-3 bg-slate-50 rounded-full hover:bg-slate-100 transition-colors"><X className="w-5 h-5 text-slate-400" /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-10 space-y-8">
              {cart.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-10">
                  <ShoppingBasket className="w-24 h-24 mb-4" />
                  <p className="font-black uppercase tracking-widest text-xs">Vacio</p>
                </div>
              ) : (
                <>
                  <div className="space-y-6">
                    {cart.map(item => (
                      <div key={item.id} className="flex items-center gap-6">
                        <img src={item.image} className="w-16 h-16 rounded-2xl object-cover shadow-sm" alt="" />
                        <div className="flex-1">
                          <h4 className="font-black text-slate-900 text-sm">{item.name}</h4>
                          <p className="text-orange-600 font-black text-xs">${item.price.toFixed(2)}</p>
                          <div className="flex items-center gap-3 mt-1">
                            <button onClick={() => updateQuantity(item.id, -1)} className="p-1.5 bg-slate-100 rounded-lg hover:bg-slate-200"><Minus className="w-3 h-3" /></button>
                            <span className="font-black text-sm">{item.quantity}</span>
                            <button onClick={() => updateQuantity(item.id, 1)} className="p-1.5 bg-slate-100 rounded-lg hover:bg-slate-200"><Plus className="w-3 h-3" /></button>
                          </div>
                        </div>
                        <div className="font-black text-sm">${(item.price * item.quantity).toFixed(2)}</div>
                      </div>
                    ))}
                  </div>
                  <div className="pt-8 border-t border-slate-100 space-y-4">
                    <input type="text" placeholder="Nombre para el pedido" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-900 font-bold" />
                    <input type="text" placeholder="Mesa / Dirección" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-6 py-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-900 font-bold" />
                  </div>
                </>
              )}
            </div>
            <div className="p-10 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Total</span>
                <div className="text-5xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button 
                onClick={handlePayment} 
                disabled={cart.length === 0 || !customerName || isPaying} 
                className={`w-full py-5 rounded-2xl font-black text-lg transition-all shadow-xl ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white hover:bg-orange-600'}`}
              >
                {isPaying ? 'Enviando...' : paymentSuccess ? '¡Listo!' : 'Confirmar Pedido'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- COMPONENTES VERTICALES ---

const NavButton: React.FC<{ icon: React.ReactNode, active: boolean, onClick: () => void, label: string, badge?: number, collapsed?: boolean, dark?: boolean }> = ({ icon, active, onClick, label, badge, collapsed, dark }) => (
  <button 
    onClick={onClick} 
    className={`relative w-full flex items-center ${collapsed ? 'justify-center' : 'gap-4'} p-4 rounded-2xl transition-all group ${
      active 
        ? 'bg-orange-600 text-white shadow-xl scale-[1.02]' 
        : 'text-slate-500 hover:text-white hover:bg-white/5'
    }`}
    title={collapsed ? label : ''}
  >
    <div className="shrink-0">{React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}</div>
    {!collapsed && <span className="text-xs font-black uppercase tracking-widest">{label}</span>}
    {badge !== undefined && badge > 0 && (
      <span className={`absolute ${collapsed ? 'top-2 right-2' : 'top-4 right-4'} bg-red-600 text-white text-[9px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 ${dark ? 'border-slate-950' : 'border-white'}`}>
        {badge}
      </span>
    )}
  </button>
);

const SidebarCategoryBtn: React.FC<{ label: string, icon: string, active: boolean, onClick: () => void, collapsed?: boolean }> = ({ label, icon, active, onClick, collapsed }) => (
  <button 
    onClick={onClick} 
    className={`w-full flex items-center ${collapsed ? 'justify-center' : 'justify-between'} p-4 rounded-2xl transition-all group border-2 ${
      active 
        ? 'bg-orange-600 border-orange-600 text-white shadow-lg' 
        : 'bg-transparent border-transparent text-slate-500 hover:bg-white/5 hover:text-white'
    }`}
    title={collapsed ? label : ''}
  >
    <div className="flex items-center gap-4">
      <span className={`text-2xl transition-transform duration-300 ${active ? 'scale-110' : 'group-hover:scale-125'}`}>{icon}</span>
      {!collapsed && <span className="font-black text-xs uppercase tracking-widest">{label}</span>}
    </div>
    {!collapsed && active && <ChevronRight className="w-4 h-4" />}
  </button>
);

const KitchenMonitor = ({ orders, updateStatus }: any) => (
  <div className="space-y-10">
    <h2 className="text-4xl font-black tracking-tighter">Comandas en Curso</h2>
    <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
      {orders.filter((o: any) => o.status !== OrderStatus.DELIVERED).sort((a: any, b: any) => a.createdAt - b.createdAt).map((order: any, idx: number) => (
        <div key={order.id} className={`bg-white rounded-[32px] overflow-hidden flex flex-col border-t-[8px] shadow-sm ${idx === 0 ? 'border-red-500 ring-4 ring-red-50' : 'border-slate-800'}`}>
          <div className="p-6 border-b border-slate-50">
            <div className="flex justify-between items-start mb-4"><span className="text-xl font-black">{order.id}</span><OrderTimer startTime={order.createdAt} /></div>
            <p className="font-black text-slate-800 text-sm uppercase tracking-widest">{order.customerName} {order.tableNumber ? `• ${order.tableNumber}` : ''}</p>
          </div>
          <div className="p-6 flex-1 space-y-4">
            {order.items.map((item: any) => (
              <div key={item.id} className="flex items-center gap-4">
                <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center font-black text-xs">{item.quantity}</div>
                <span className="font-bold text-sm text-slate-700">{item.name}</span>
              </div>
            ))}
          </div>
          <div className="p-6 bg-slate-50">
            <button onClick={() => updateStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)} className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-sm transition-all ${order.status === OrderStatus.PENDING ? 'bg-orange-600 text-white' : order.status === OrderStatus.PREPARING ? 'bg-blue-600 text-white' : 'bg-emerald-600 text-white'}`}>
