                </div>
              ) : (
                <>
                  <div className="space-y-5">
                    {cart.map(item => (
                      <div key={item.id} className="flex items-center gap-4">
                        <img src={item.image} className="w-14 h-14 rounded-xl object-cover shadow-sm" alt="" />
                        <div className="flex-1">
                          <h4 className="font-black text-slate-900 text-xs truncate max-w-[150px]">{item.name}</h4>
                          <p className="text-orange-600 font-black text-[10px]">${item.price.toFixed(2)}</p>
