                        </div>
                        <div className="font-black text-xs shrink-0">${(item.price * item.quantity).toFixed(2)}</div>
                      </div>
                    ))}
                  </div>
                  <div className="pt-6 border-t border-slate-100 space-y-4">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 ml-1">Para quién es:</label>
                      <input type="text" placeholder="Ej: Juan Pérez" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-950 font-bold text-sm" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 ml-1">Donde estás:</label>
                      <input type="text" placeholder="Mesa / Barra / Dirección" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-950 font-bold text-sm" />
                    </div>
                  </div>
                </>
              )}
            </div>
            <div className="p-6 md:p-10 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-400 font-black uppercase text-[9px] tracking-[0.2em]">Total</span>
                <div className="text-4xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button 
                onClick={handlePayment} 
                disabled={cart.length === 0 || !customerName || isPaying} 
                className={`w-full py-4.5 rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-xl active:scale-95 ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-950 text-white'}`}
              >
                {isPaying ? 'Procesando...' : paymentSuccess ? '¡Completado!' : 'Finalizar Pedido'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ADMIN FORM RESPONSIVE */}
      {isAdminFormOpen && <AdminForm item={editingItem} onSave={handleSaveItem} onClose={() => setIsAdminFormOpen(false)} />}
    </div>
  );
};

