      {orders.filter((o: any) => o.status !== OrderStatus.DELIVERED).sort((a: any, b: any) => a.createdAt - b.createdAt).map((order: any, idx: number) => (
        <div key={order.id} className={`bg-white rounded-3xl overflow-hidden flex flex-col border-t-[6px] shadow-sm ${idx === 0 ? 'border-red-500 ring-2 ring-red-50' : 'border-slate-800'}`}>
