const AdminForm: React.FC<{ item: FoodItem | null, onSave: (item: FoodItem) => void, onClose: () => void }> = ({ item, onSave, onClose }) => {
  const [formData, setFormData] = useState<FoodItem>(item || { id: '', name: '', price: 0, category: 'Hamburguesas', image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=400&h=300', description: '' });
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, image: reader.result as string });
      reader.readAsDataURL(file);
    }
  };
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.price <= 0) return alert('Nombre y precio requeridos');
    onSave(formData);
  };
  return (
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-6 bg-slate-950/80 backdrop-blur-md">
      <div className="relative bg-white w-full max-w-2xl rounded-t-[32px] md:rounded-[40px] shadow-3xl overflow-hidden flex flex-col md:flex-row max-h-[90vh] animate-in slide-in-from-bottom">
        <form onSubmit={handleSubmit} className="p-6 md:p-10 overflow-y-auto space-y-5 bg-white w-full">
          <div className="flex justify-between items-center mb-2"><h2 className="text-xl font-black uppercase tracking-tighter">{item ? 'Editar' : 'Nuevo'}</h2><button type="button" onClick={onClose} className="p-2 bg-slate-50 rounded-full"><X className="w-5 h-5 text-slate-300" /></button></div>
          <div className="space-y-3"><label className="text-[9px] font-black uppercase text-slate-400 ml-1">Nombre</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-950 font-bold text-sm" /></div>
          <div className="grid grid-cols-2 gap-3"><div className="space-y-3"><label className="text-[9px] font-black uppercase text-slate-400 ml-1">Precio</label><input type="number" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-950 font-bold text-sm" /></div><div className="space-y-3"><label className="text-[9px] font-black uppercase text-slate-400 ml-1">Categoría</label><select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-950 font-bold text-sm appearance-none">{CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.id}</option>)}</select></div></div>
          <div className="space-y-3"><label className="text-[9px] font-black uppercase text-slate-400 ml-1">Imagen</label><div className="flex gap-2"><input type="text" value={formData.image.startsWith('data:') ? 'Imagen Local' : formData.image} readOnly className="flex-1 px-5 py-3.5 bg-slate-50 rounded-2xl border-2 border-transparent font-bold text-xs" /><label className="p-3.5 bg-orange-600 text-white rounded-2xl cursor-pointer hover:bg-slate-950 active:scale-95"><Upload className="w-5 h-5" /><input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} /></label></div></div>
          <div className="space-y-3"><label className="text-[9px] font-black uppercase text-slate-400 ml-1">Descripción</label><textarea rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-950 font-bold text-xs resize-none" /></div>
          <button type="submit" className="w-full py-4.5 bg-slate-950 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95">Guardar Cambios</button>
        </form>
      </div>
    </div>
  );
};

const HistoryView = ({ orders }: { orders: Order[] }) => (
  <div className="max-w-2xl mx-auto space-y-4">
    <h2 className="text-2xl font-black uppercase tracking-tighter">Historial</h2>
    {orders.slice().reverse().map(order => (
      <div key={order.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1"><span className="text-sm font-black">{order.id}</span><StatusBadge status={order.status} /></div>
          <p className="font-bold text-slate-800 text-xs truncate uppercase tracking-widest">{order.customerName}</p>
        </div>
        <div className="text-right">
          <p className="text-xl font-black text-slate-900 tracking-tighter">${order.total.toFixed(2)}</p>
          <p className="text-[8px] text-slate-400 font-bold">{new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
        </div>
      </div>
    ))}
  </div>
);

const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => { o.items.forEach(item => { data[item.name] = (data[item.name] || 0) + item.quantity; }); });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);
  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <StatCard label="Ingresos" value={`$${orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((a, b) => a + b.total, 0).toFixed(2)}`} icon={<DollarSign className="text-emerald-500" />} />
        <StatCard label="Pedidos" value={orders.length.toString()} icon={<ShoppingBag className="text-blue-500" />} />
        <StatCard label="Ticket" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(2) : '0'}`} icon={<Timer className="text-orange-500" />} />
      </div>
      <div className="bg-white p-6 rounded-3xl border border-slate-100 h-[300px] shadow-sm">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={salesData}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 8, fontWeight: 700 }} />
            <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 8, fontWeight: 700 }} />
            <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontSize: '10px' }} />
            <Bar dataKey="value" fill="#f97316" radius={[4, 4, 0, 0]} barSize={24} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

const AIView = ({ menu, orders, fetchAISuggestions, loadingAI, aiSuggestions }: any) => (
  <div className="space-y-6">
    <div className="bg-slate-950 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
      <div className="relative z-10 max-w-sm">
        <h2 className="text-2xl font-black mb-2 flex items-center gap-2"><Sparkles className="text-orange-500 w-6 h-6" /> Estrategia IA</h2>
        <p className="text-xs text-slate-400 font-medium mb-6 leading-relaxed">Optimizador inteligente de ventas.</p>
        <button onClick={fetchAISuggestions} disabled={loadingAI} className="w-full py-3.5 bg-orange-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-white hover:text-slate-950 transition-all active:scale-95">{loadingAI ? 'Analizando...' : 'Actualizar'}</button>
      </div>
    </div>
    <div className="grid grid-cols-1 gap-4">
      {aiSuggestions.map((s: any, idx: number) => (
        <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><span className={`text-[8px] font-black px-2 py-0.5 rounded-full border mb-3 inline-block uppercase tracking-widest ${s.impact === 'Alta' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{s.impact} Impacto</span><h3 className="text-md font-black mb-2">{s.title}</h3><p className="text-slate-500 text-[10px] font-medium leading-relaxed">{s.description}</p></div>
      ))}
