                          <button onClick={() => updateQuantity(item.id, -1)} className="p-1 bg-white border border-slate-200 rounded-lg"><Minus className="w-3 h-3" /></button>
                          <span className="font-black text-xs">{item.quantity}</span>
                          <button onClick={() => updateQuantity(item.id, 1)} className="p-1 bg-white border border-slate-200 rounded-lg"><Plus className="w-3 h-3" /></button>
                        </div>
                      </div>
                      <div className="font-black text-xs text-orange-600">${(item.price * item.quantity).toFixed(2)}</div>
                    </div>
                  ))}
                  <div className="pt-6 space-y-3">
                    <input type="text" placeholder="Tu Nombre" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border-2 border-transparent focus:border-slate-950 font-bold text-sm outline-none" />
                    <input type="text" placeholder="Nº Mesa / Dirección" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border-2 border-transparent focus:border-slate-950 font-bold text-sm outline-none" />
                  </div>
                </div>
              )}
            </div>
            <div className="p-6 md:p-10 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-400 font-black uppercase text-[9px] tracking-[0.2em]">Total</span>
                <div className="text-4xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button 
                onClick={handlePayment} 
                disabled={cart.length === 0 || !customerName || isPaying} 
                className={`w-full py-4.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95 ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-950 text-white'}`}
              >
                {isPaying ? 'Procesando...' : paymentSuccess ? '¡Enviado!' : 'Confirmar Pedido'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ADMIN FORM RESPONSIVE */}
      {isAdminFormOpen && <AdminForm item={editingItem} onSave={handleSaveItem} onClose={() => setIsAdminFormOpen(false)} />}
    </div>
  );
};

