  Plus, 
  Minus, 
  Trash2, 
  X,
  UtensilsCrossed,
  Timer,
  ShoppingBasket,
  Edit2,
  Search,
  Lock,
  LogOut,
  ChevronLeft,
  // Added missing ChevronRight and Settings icons
  ChevronRight,
  Settings,
  Store,
