    className={`relative w-full flex items-center ${collapsed ? 'justify-center' : 'gap-4'} p-4 rounded-2xl transition-all ${
      active ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:text-white hover:bg-white/5'
    }`}
    title={collapsed ? label : ''}
  >
    <div className="shrink-0">{React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}</div>
    {!collapsed && <span className="text-xs font-black uppercase tracking-widest">{label}</span>}
    {badge !== undefined && badge > 0 && (
      <span className="absolute top-2 right-2 bg-red-600 text-white text-[9px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-slate-950">
        {badge}
