);

const KitchenMonitor = ({ orders, updateStatus }: any) => (
  <div className="space-y-6">
    <h2 className="text-2xl font-black tracking-tighter uppercase">Comandas</h2>
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {orders.filter((o: any) => o.status !== OrderStatus.DELIVERED).sort((a: any, b: any) => a.createdAt - b.createdAt).map((order: any, idx: number) => (
        <div key={order.id} className={`bg-white rounded-3xl overflow-hidden border-t-8 shadow-sm flex flex-col ${idx === 0 ? 'border-red-500 ring-2 ring-red-50' : 'border-slate-800'}`}>
          <div className="p-4 border-b border-slate-50 flex justify-between items-start">
            <div><span className="text-lg font-black">{order.id}</span><p className="text-[9px] font-black text-slate-400 uppercase">{order.customerName}</p></div>
            <OrderTimer startTime={order.createdAt} />
          </div>
          <div className="p-4 flex-1 space-y-2">
            {order.items.map((item: any) => (
              <div key={item.id} className="flex justify-between items-center text-xs font-bold">
                <span>{item.quantity}x {item.name}</span>
              </div>
            ))}
          </div>
          <button onClick={() => updateStatus(order.id, order.status === OrderStatus.PENDING ? OrderStatus.PREPARING : order.status === OrderStatus.PREPARING ? OrderStatus.READY : OrderStatus.DELIVERED)} className={`w-full py-4 text-[10px] font-black uppercase tracking-widest ${order.status === OrderStatus.PENDING ? 'bg-orange-600 text-white' : 'bg-emerald-600 text-white'}`}>
            {order.status === OrderStatus.PENDING ? 'Comenzar' : 'Marcar Listo'}
          </button>
        </div>
      ))}
    </div>
  </div>
);

const AdminForm: React.FC<{ item: FoodItem | null, onSave: (item: FoodItem) => void, onClose: () => void }> = ({ item, onSave, onClose }) => {
  const [formData, setFormData] = useState<FoodItem>(item || { id: '', name: '', price: 0, category: 'Hamburguesas', image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=400&h=300', description: '' });
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, image: reader.result as string });
      reader.readAsDataURL(file);
    }
  };
  return (
    <div className="fixed inset-0 z-[110] flex items-end md:items-center justify-center p-0 md:p-6 bg-slate-950/80 backdrop-blur-md">
      <div className="bg-white w-full max-w-lg rounded-t-[32px] md:rounded-[40px] p-6 md:p-10 shadow-3xl overflow-y-auto max-h-[90vh] animate-in slide-in-from-bottom">
        <div className="flex justify-between items-center mb-6"><h2 className="text-xl font-black uppercase">{item ? 'Editar' : 'Nuevo Plato'}</h2><button onClick={onClose} className="p-2 bg-slate-50 rounded-full"><X className="w-5 h-5" /></button></div>
        <div className="space-y-4">
          <input type="text" placeholder="Nombre" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-950 font-bold" />
          <div className="grid grid-cols-2 gap-4">
            <input type="number" placeholder="Precio" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-950 font-bold" />
            <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold">
              {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.id}</option>)}
            </select>
          </div>
          <div className="flex gap-2">
            <input type="text" value={formData.image.startsWith('data:') ? 'Imagen Cargada' : formData.image} readOnly className="flex-1 p-4 bg-slate-50 rounded-2xl font-bold text-xs" />
            <label className="p-4 bg-orange-600 text-white rounded-2xl cursor-pointer"><Camera className="w-5 h-5" /><input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} /></label>
          </div>
          <textarea placeholder="Descripción" rows={2} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl outline-none border-2 border-transparent focus:border-slate-950 font-bold resize-none" />
          <button onClick={() => onSave(formData)} className="w-full py-4 bg-slate-950 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Guardar</button>
        </div>
      </div>
    </div>
  );
};

const HistoryView = ({ orders }: { orders: Order[] }) => (
  <div className="max-w-2xl mx-auto space-y-4">
    <h2 className="text-2xl font-black uppercase tracking-tighter italic">Ventas <span className="text-orange-600 not-italic">Recientes</span></h2>
    {orders.slice().reverse().map(order => (
      <div key={order.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center gap-4">
        <div><div className="flex items-center gap-2 mb-1"><span className="text-sm font-black">{order.id}</span><StatusBadge status={order.status} /></div><p className="font-bold text-slate-800 text-[10px] uppercase tracking-widest">{order.customerName}</p></div>
        <div className="text-right"><p className="text-xl font-black text-slate-900">${order.total.toFixed(2)}</p><p className="text-[8px] text-slate-400 font-bold">{new Date(order.createdAt).toLocaleTimeString()}</p></div>
      </div>
    ))}
  </div>
);

const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => { o.items.forEach(item => { data[item.name] = (data[item.name] || 0) + item.quantity; }); });
    return Object.entries(data).map(([name, value]) => ({ name, value }));
  }, [orders]);
  return (
    <div className="space-y-6">
      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Ingresos" value={`$${orders.reduce((a, b) => a + b.total, 0).toFixed(0)}`} />
        <StatCard label="Órdenes" value={orders.length.toString()} />
        <StatCard label="Ticket" value={`$${orders.length > 0 ? (orders.reduce((a, b) => a + b.total, 0) / orders.length).toFixed(0) : '0'}`} />
      </div>
      <div className="bg-white p-6 rounded-3xl border border-slate-100 h-[250px] shadow-sm">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={salesData}><XAxis dataKey="name" hide /><YAxis hide /><Tooltip /><Bar dataKey="value" fill="#f97316" radius={[4, 4, 0, 0]} /></BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

const AIView = ({ fetchAISuggestions, loadingAI, aiSuggestions }: any) => (
  <div className="space-y-6">
    <div className="bg-slate-950 rounded-3xl p-8 text-white relative overflow-hidden">
      <h2 className="text-2xl font-black mb-2 flex items-center gap-2 tracking-tighter uppercase">Estrategia IA <Sparkles className="text-orange-500" /></h2>
      <p className="text-xs text-slate-400 mb-6">Analizando datos en tiempo real.</p>
      <button onClick={fetchAISuggestions} disabled={loadingAI} className="w-full py-4 bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest">{loadingAI ? 'Analizando...' : 'Actualizar IA'}</button>
