);

const StatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => <span className={`text-[8px] font-black px-2 py-0.5 rounded-full border uppercase tracking-widest ${status === OrderStatus.PENDING ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'}`}>{status}</span>;
