import React, { useState, useMemo, useEffect } from 'react';
import { 
  ShoppingBag, 
  ClipboardList, 
  ChefHat, 
  BarChart3, 
  Sparkles, 
  Plus, 
  Minus, 
  Trash2, 
  X,
  UtensilsCrossed,
  Timer,
  ShoppingBasket,
  Edit2,
  Search,
  Lock,
  LogOut,
  ChevronLeft,
  ChevronRight,
  Settings,
  Store,
  Camera,
  LayoutGrid,
  Home,
  User,
  Upload,
  DollarSign
} from 'lucide-react';
import { FoodItem, Order, OrderItem, OrderStatus, ViewType, PaymentStatus } from './types';
import { INITIAL_MENU, CATEGORIES } from './constants';
import { getSmartSuggestions } from './geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

// --- COMPONENTES AUXILIARES ---

const OrderTimer: React.FC<{ startTime: number }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60)), 10000);
    setElapsed(Math.floor((Date.now() - startTime) / 1000 / 60));
    return () => clearInterval(interval);
  }, [startTime]);

  return (
    <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full text-[9px] font-black uppercase tracking-wider ${
      elapsed > 15 ? 'bg-red-500 text-white animate-pulse' : 'bg-slate-900 text-white'
    }`}>
      <Timer className="w-3 h-3" /> {elapsed} min
    </div>
  );
};

// --- APP PRINCIPAL ---

const App: React.FC = () => {
  const [isStaffMode, setIsStaffMode] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [pin, setPin] = useState('');
  const [activeView, setActiveView] = useState<ViewType>('menu');

  // Persistencia del Menú
  const [menuItems, setMenuItems] = useState<FoodItem[]>(() => {
    const saved = localStorage.getItem('fastfood_menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  // Persistencia de Info del Restaurante
  const [restaurantInfo, setRestaurantInfo] = useState({
    name: localStorage.getItem('fastfood_name') || 'Santa Parrilla',
    logo: localStorage.getItem('fastfood_logo') || ''
  });

  // Persistencia de Órdenes (Historial real)
  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('fastfood_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [cart, setCart] = useState<OrderItem[]>([]);
  const [activeCategory, setActiveCategory] = useState<string>('Todas');
  const [customerName, setCustomerName] = useState('');
  const [tableNumber, setTableNumber] = useState('');
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [loadingAI, setLoadingAI] = useState(false);

  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);
  const [isAdminFormOpen, setIsAdminFormOpen] = useState(false);
  const [adminSearch, setAdminSearch] = useState('');

  // Sincronización con LocalStorage
  useEffect(() => localStorage.setItem('fastfood_menu', JSON.stringify(menuItems)), [menuItems]);
  useEffect(() => localStorage.setItem('fastfood_orders', JSON.stringify(orders)), [orders]);
  useEffect(() => {
    localStorage.setItem('fastfood_name', restaurantInfo.name);
    localStorage.setItem('fastfood_logo', restaurantInfo.logo);
  }, [restaurantInfo]);

  useEffect(() => {
    if (activeView === 'ai' && aiSuggestions.length === 0) {
      fetchAISuggestions();
    }
  }, [activeView]);

  const filteredMenu = useMemo(() => {
    if (activeCategory === 'Todas') return menuItems;
    return menuItems.filter(item => item.category === activeCategory);
  }, [activeCategory, menuItems]);

  const filteredAdminMenu = useMemo(() => {
    return menuItems.filter(item => 
      item.name.toLowerCase().includes(adminSearch.toLowerCase()) || 
      item.category.toLowerCase().includes(adminSearch.toLowerCase())
    );
  }, [menuItems, adminSearch]);

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => prev.map(i => i.id === itemId ? { ...i, quantity: Math.max(0, i.quantity + delta) } : i).filter(i => i.quantity > 0));
  };

  const cartTotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (pin === '1234') { 
      setIsStaffMode(true);
      setShowLogin(false);
      setActiveView('kitchen');
      setPin('');
    } else {
      alert('PIN Incorrecto (Default: 1234)');
      setPin('');
    }
  };

  const handlePayment = () => {
    if (!customerName) return alert("Por favor, ingresa tu nombre para el pedido");
    setIsPaying(true);
    setTimeout(() => {
      const newOrder: Order = {
        id: `#${Math.floor(100 + Math.random() * 899)}`,
        items: [...cart],
        total: cartTotal,
        status: OrderStatus.PENDING,
        paymentStatus: PaymentStatus.PAID,
        customerName,
        tableNumber,
        createdAt: Date.now()
      };
      setOrders(prev => [...prev, newOrder]);
      setCart([]);
      setCustomerName('');
      setTableNumber('');
      setIsPaying(false);
      setPaymentSuccess(true);
      setTimeout(() => {
        setPaymentSuccess(false);
        setIsCartOpen(false);
      }, 2000);
    }, 1200);
  };

  const updateOrderStatus = (orderId: string, nextStatus: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: nextStatus } : o));
  };

  const fetchAISuggestions = async () => {
    setLoadingAI(true);
    try {
      const suggestions = await getSmartSuggestions(menuItems, orders);
      setAiSuggestions(suggestions);
    } catch (error) {
      console.error(error);
    } finally {
      setLoadingAI(false);
    }
  };

  const handleSaveItem = (item: FoodItem) => {
    if (editingItem) {
      setMenuItems(prev => prev.map(i => i.id === item.id ? item : i));
    } else {
      setMenuItems(prev => [...prev, { ...item, id: `item-${Date.now()}` }]);
    }
    setIsAdminFormOpen(false);
    setEditingItem(null);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setRestaurantInfo(prev => ({ ...prev, logo: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#FAF9F6] text-slate-900 font-sans transition-all duration-300">

      {/* NAVEGACIÓN LATERAL (Solo Desktop) */}
      <nav className={`
        hidden md:flex flex-col bg-slate-950 text-white shadow-2xl transition-all duration-500
        sticky top-0 h-screen overflow-y-auto no-scrollbar
        ${isSidebarCollapsed ? 'w-24' : 'w-72'}
      `}>
        <button 
          onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          className="absolute -right-3 top-10 w-6 h-10 bg-orange-600 rounded-r-lg flex items-center justify-center shadow-lg"
        >
          {isSidebarCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
        </button>

        <div className={`p-8 text-center transition-all ${isSidebarCollapsed ? 'opacity-0 scale-50 p-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          <div className="mb-6 mx-auto w-32 h-32 relative">
            {restaurantInfo.logo ? (
              <img src={restaurantInfo.logo} className="w-full h-full rounded-3xl object-cover shadow-2xl ring-4 ring-white/10" alt="Logo" />
            ) : (
              <div className="w-full h-full bg-orange-600 rounded-3xl flex items-center justify-center">
                <UtensilsCrossed className="w-16 h-16 text-white" />
              </div>
            )}
          </div>
          <h1 className="text-xl font-black uppercase tracking-tighter">{restaurantInfo.name}</h1>
          <div className="w-10 h-1 bg-orange-500 mx-auto mt-4"></div>
        </div>

        <div className="flex-1 px-4 space-y-2 mt-4">
          {isStaffMode ? (
            <>
              <SidebarItem icon={<ChefHat />} label="Cocina" active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} collapsed={isSidebarCollapsed} badge={orders.filter(o => o.status !== OrderStatus.DELIVERED).length} />
              <SidebarItem icon={<ClipboardList />} label="Historial" active={activeView === 'orders'} onClick={() => setActiveView('orders')} collapsed={isSidebarCollapsed} />
              <SidebarItem icon={<BarChart3 />} label="Métricas" active={activeView === 'stats'} onClick={() => setActiveView('stats')} collapsed={isSidebarCollapsed} />
              <SidebarItem icon={<Sparkles />} label="IA Plan" active={activeView === 'ai'} onClick={() => setActiveView('ai')} collapsed={isSidebarCollapsed} />
              <SidebarItem icon={<Settings />} label="Ajustes Menú" active={activeView === 'admin'} onClick={() => setActiveView('admin')} collapsed={isSidebarCollapsed} />
              <button onClick={() => { setIsStaffMode(false); setActiveView('menu'); }} className="w-full mt-10 p-4 flex items-center gap-4 text-red-400 hover:bg-red-500/10 rounded-2xl transition-all">
                <LogOut className="w-6 h-6" />
                {!isSidebarCollapsed && <span className="text-xs font-black uppercase">Salir Modo Staff</span>}
              </button>
            </>
          ) : (
            <div className="space-y-1">
              <p className={`text-[10px] font-black text-slate-500 uppercase tracking-widest px-4 mb-4 ${isSidebarCollapsed ? 'hidden' : ''}`}>Categorías</p>
              <SidebarItem icon={<LayoutGrid />} label="Todas" active={activeCategory === 'Todas'} onClick={() => setActiveCategory('Todas')} collapsed={isSidebarCollapsed} />
              {CATEGORIES.map(cat => (
                <SidebarItem key={cat.id} icon={<span>{cat.icon}</span>} label={cat.id} active={activeCategory === cat.id} onClick={() => setActiveCategory(cat.id)} collapsed={isSidebarCollapsed} />
              ))}
            </div>
          )}
        </div>
      </nav>

      {/* CONTENIDO PRINCIPAL */}
      <div className="flex-1 flex flex-col min-h-screen">

        {/* HEADER SUPERIOR */}
        <header className="sticky top-0 bg-white/90 backdrop-blur-xl border-b border-slate-100 z-40 px-4 md:px-8 py-3 md:py-5 flex justify-between items-center">
          <div className="flex items-center gap-3">
            {restaurantInfo.logo ? (
              <img src={restaurantInfo.logo} className="w-10 h-10 rounded-xl object-cover shadow-sm md:hidden" alt="Logo" />
            ) : (
              <div className="w-10 h-10 bg-orange-600 rounded-xl flex items-center justify-center md:hidden">
                <UtensilsCrossed className="w-5 h-5 text-white" />
              </div>
            )}
            <div>
              <h2 className="text-sm md:text-lg font-black uppercase tracking-tighter text-slate-900 leading-none">
                {isStaffMode ? activeView.toUpperCase() : restaurantInfo.name}
              </h2>
              <span className="text-[10px] font-bold text-orange-600 uppercase tracking-widest">
                {isStaffMode ? 'Dashboard Personal' : activeCategory}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {!isStaffMode && (
              <button onClick={() => setIsCartOpen(true)} className="flex items-center gap-2 bg-slate-950 text-white px-4 py-2.5 md:px-6 md:py-3.5 rounded-2xl shadow-xl relative active:scale-95 transition-all">
                <ShoppingBag className="w-4 h-4" />
                {cart.length > 0 && (
                  <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[9px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-white animate-pulse">
                    {cart.length}
                  </span>
                )}
                <span className="font-black text-xs md:text-sm">${cartTotal.toFixed(2)}</span>
              </button>
            )}
            {isStaffMode && activeView === 'admin' && (
              <button onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }} className="bg-orange-600 text-white px-4 py-2.5 rounded-xl shadow-lg active:scale-95 flex items-center gap-2 font-black text-[10px] uppercase">
                <Plus className="w-4 h-4" /> Nuevo Plato
              </button>
            )}
          </div>
        </header>

        {/* CATEGORÍAS TIPO "CHIP" (Solo Móvil) */}
        {!isStaffMode && activeView === 'menu' && (
          <div className="md:hidden sticky top-[57px] bg-white/80 backdrop-blur-md border-b border-slate-50 z-30 px-4 py-3 flex gap-2 overflow-x-auto no-scrollbar shadow-sm">
            <button 
              onClick={() => setActiveCategory('Todas')}
              className={`shrink-0 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${activeCategory === 'Todas' ? 'bg-slate-950 text-white border-slate-950 shadow-md' : 'bg-white text-slate-400 border-slate-200'}`}
            >
              🔥 Todas
            </button>
            {CATEGORIES.map(cat => (
              <button 
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                className={`shrink-0 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${activeCategory === cat.id ? 'bg-slate-950 text-white border-slate-950 shadow-md' : 'bg-white text-slate-400 border-slate-200'}`}
              >
                {cat.icon} {cat.id}
              </button>
            ))}
          </div>
        )}

        {/* CONTENIDO PRINCIPAL DINÁMICO */}
        <main className="flex-1 p-4 md:p-10 w-full animate-in fade-in duration-500 pb-24 md:pb-10">
          {!isStaffMode && activeView === 'menu' && (
            <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-8">
              {filteredMenu.map(item => (
                <div key={item.id} className="bg-white rounded-[24px] md:rounded-[40px] border border-slate-100 overflow-hidden shadow-sm flex flex-col h-full group active:scale-[0.98] transition-all">
                  <div className="relative h-32 md:h-64 overflow-hidden bg-slate-50">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                  </div>
                  <div className="p-3 md:p-8 flex flex-col flex-1">
                    <div className="mb-1 md:mb-2">
                      <h3 className="text-xs md:text-lg font-black text-slate-800 leading-tight truncate">{item.name}</h3>
                      <span className="text-xs md:text-md font-black text-orange-600">${item.price.toFixed(2)}</span>
                    </div>
                    <p className="hidden md:block text-slate-400 text-xs font-medium leading-relaxed mb-6 line-clamp-2">{item.description}</p>
                    <button onClick={() => addToCart(item)} className="mt-auto w-full py-2.5 md:py-4 bg-slate-50 text-slate-950 rounded-xl md:rounded-2xl font-black text-[10px] md:text-sm flex items-center justify-center gap-1 md:gap-2 hover:bg-slate-950 hover:text-white transition-all border-2 border-slate-100">
                      <Plus className="w-3 h-3 md:w-4 md:h-4" /> Agregar
                    </button>
                  </div>
                </div>
              ))}
              {filteredMenu.length === 0 && (
                <div className="col-span-full py-20 text-center opacity-20">
                  <ShoppingBasket className="w-20 h-20 mx-auto mb-4" />
                  <p className="font-black uppercase tracking-widest text-xs">Sin platos en esta sección</p>
                </div>
              )}
            </div>
          )}

          {isStaffMode && (
            <div className="animate-in slide-in-from-right duration-500">
              {activeView === 'kitchen' && <KitchenMonitor orders={orders} updateStatus={updateOrderStatus} />}
              {activeView === 'admin' && (
                <div className="max-w-4xl mx-auto space-y-6">
                  {/* Branding del Local */}
                  <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col md:flex-row gap-6 items-center">
                    <div className="flex-1 space-y-4 w-full">
                      <h3 className="text-sm font-black uppercase tracking-widest text-slate-400 italic">Identidad Visual</h3>
                      <input type="text" value={restaurantInfo.name} onChange={e => setRestaurantInfo(prev => ({ ...prev, name: e.target.value }))} className="w-full px-5 py-3 bg-slate-50 rounded-xl outline-none focus:bg-white border-2 border-transparent focus:border-slate-950 font-bold text-sm" placeholder="Nombre del restaurante" />
                    </div>
                    <div className="relative shrink-0">
                      <div className="w-24 h-24 rounded-2xl overflow-hidden bg-slate-100 border-2 border-dashed border-slate-200 flex items-center justify-center">
                        {restaurantInfo.logo ? <img src={restaurantInfo.logo} className="w-full h-full object-cover" alt="" /> : <Store className="w-8 h-8 text-slate-300" />}
                      </div>
                      <label className="absolute -bottom-2 -right-2 bg-orange-600 text-white p-2 rounded-full cursor-pointer shadow-lg active:scale-90 transition-transform">
                        <Camera className="w-4 h-4" />
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                      </label>
                    </div>
                  </div>

                  {/* Listado de Platos */}
                  <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                    <div className="p-4 border-b border-slate-50 flex items-center gap-3">
                      <Search className="w-4 h-4 text-slate-300" />
                      <input type="text" placeholder="Filtrar platos..." value={adminSearch} onChange={(e) => setAdminSearch(e.target.value)} className="w-full bg-transparent outline-none font-bold text-xs" />
                    </div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left text-xs">
                        <thead className="bg-slate-50 font-black text-[9px] uppercase text-slate-400">
                          <tr><th className="p-4">Plato</th><th className="p-4">Categoría</th><th className="p-4">Precio</th><th className="p-4 text-right">Acción</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 font-bold">
                          {filteredAdminMenu.map(item => (
                            <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                              <td className="p-4 flex items-center gap-3">
                                <img src={item.image} className="w-10 h-10 rounded-lg object-cover" alt="" />
                                <span className="font-black truncate max-w-[150px]">{item.name}</span>
                              </td>
                              <td className="p-4 text-slate-400">{item.category}</td>
                              <td className="p-4 text-orange-600 font-black">${item.price.toFixed(2)}</td>
                              <td className="p-4 text-right">
                                <div className="flex justify-end gap-1">
                                  <button onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }} className="p-2 text-slate-400 hover:text-orange-600"><Edit2 className="w-4 h-4" /></button>
                                  <button onClick={() => setMenuItems(prev => prev.filter(i => i.id !== item.id))} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}
              {activeView === 'orders' && <HistoryView orders={orders} />}
              {activeView === 'stats' && <StatsView orders={orders} />}
              {activeView === 'ai' && <AIView fetchAISuggestions={fetchAISuggestions} loadingAI={loadingAI} aiSuggestions={aiSuggestions} />}
            </div>
          )}
        </main>
      </div>

      {/* NAVEGACIÓN INFERIOR (Solo Móvil) */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 h-16 bg-slate-950 text-white flex items-center justify-around px-4 z-50 border-t border-white/5 pb-safe">
        <MobileNavItem icon={<Home />} label="Menú" active={!isStaffMode && activeView === 'menu'} onClick={() => { setIsStaffMode(false); setActiveView('menu'); }} />
        <MobileNavItem icon={<ShoppingBag />} label="Carrito" active={!isStaffMode && isCartOpen} onClick={() => setIsCartOpen(true)} badge={cart.length} />
        {isStaffMode ? (
          <>
            <MobileNavItem icon={<ChefHat />} label="Cocina" active={activeView === 'kitchen'} onClick={() => setActiveView('kitchen')} badge={orders.filter(o => o.status !== OrderStatus.DELIVERED).length} />
            <MobileNavItem icon={<BarChart3 />} label="Admin" active={activeView === 'stats' || activeView === 'admin'} onClick={() => setActiveView('stats')} />
          </>
        ) : (
          <MobileNavItem icon={<Lock />} label="Acceso" active={false} onClick={() => setShowLogin(true)} />
        )}
      </nav>

      {/* MODAL LOGIN */}
      {showLogin && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-6 bg-slate-950/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-sm rounded-t-[32px] md:rounded-[40px] p-8 md:p-10 shadow-3xl text-center animate-in slide-in-from-bottom">
            <Lock className="w-10 h-10 text-slate-900 mx-auto mb-4" />
            <h2 className="text-xl font-black mb-2 uppercase tracking-tighter">Acceso Staff</h2>
            <p className="text-slate-400 text-[9px] font-black uppercase tracking-widest mb-8">Clave de 4 dígitos (1234)</p>
            <form onSubmit={handleLogin} className="space-y-6">
              <input type="password" maxLength={4} value={pin} onChange={e => setPin(e.target.value)} placeholder="••••" className="w-full text-center text-4xl tracking-[0.5em] py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-slate-950 outline-none font-black" autoFocus />
              <div className="flex gap-4">
