                      <input type="text" placeholder="Ej: Juan Pérez" value={customerName} onChange={(e) => setCustomerName(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border-2 border-transparent focus:border-slate-950 font-bold text-sm outline-none" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 ml-1">Lugar / Mesa</label>
                      <input type="text" placeholder="Ej: Mesa 5 o Dirección" value={tableNumber} onChange={(e) => setTableNumber(e.target.value)} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border-2 border-transparent focus:border-slate-950 font-bold text-sm outline-none" />
                    </div>
                  </div>
                </div>
              )}
            </div>
            <div className="p-6 md:p-10 border-t border-slate-100 bg-white">
              <div className="flex justify-between items-end mb-6">
                <span className="text-slate-400 font-black uppercase text-[9px] tracking-[0.2em]">Total</span>
                <div className="text-4xl font-black text-slate-900 tracking-tighter">${cartTotal.toFixed(2)}</div>
              </div>
              <button 
                onClick={handlePayment} 
                disabled={cart.length === 0 || !customerName || isPaying} 
                className={`w-full py-4.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl active:scale-95 ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-950 text-white hover:bg-orange-600'}`}
              >
                {isPaying ? 'Enviando...' : paymentSuccess ? '¡Listo!' : 'Confirmar Pedido'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ADMIN FORM MODAL */}
      {isAdminFormOpen && <AdminForm item={editingItem} onSave={handleSaveItem} onClose={() => setIsAdminFormOpen(false)} />}
    </div>
  );
};

