const StatsView = ({ orders }: { orders: Order[] }) => {
  const salesData = useMemo(() => {
    const data: Record<string, number> = {};
    orders.filter(o => o.status === OrderStatus.DELIVERED).forEach(o => { o.items.forEach(item => { data[item.name] = (data[item.name] || 0) + item.quantity; }); });
    return Object.entries(data).map(([name, value]) => ({ name, value })).slice(0, 5);
  }, [orders]);

  const totalRevenue = orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((a, b) => a + b.total, 0);
  const avgTicket = orders.length > 0 ? totalRevenue / orders.length : 0;

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <h2 className="text-2xl font-black uppercase tracking-tighter">Métricas del Negocio</h2>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <StatCard label="Ingresos Hoy" value={`$${totalRevenue.toFixed(0)}`} icon={<DollarSign className="text-emerald-500" />} />
        <StatCard label="Total Órdenes" value={orders.length.toString()} icon={<ShoppingBag className="text-blue-500" />} />
        <StatCard label="Ticket Promedio" value={`$${avgTicket.toFixed(0)}`} icon={<Timer className="text-orange-500" />} />
      </div>
      <div className="bg-white p-6 md:p-10 rounded-[32px] md:rounded-[40px] border border-slate-100 shadow-sm">
        <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-8">Top 5 Productos más vendidos</h3>
        {salesData.length > 0 ? (
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={salesData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 700 }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 700 }} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontSize: '10px' }} />
                <Bar dataKey="value" fill="#f97316" radius={[6, 6, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <div className="h-[200px] flex items-center justify-center text-slate-300 font-black text-xs uppercase tracking-widest">Esperando datos de ventas...</div>
        )}
      </div>
    </div>
  );
};

