                  <Database className="w-8 h-8" />
                </div>
                <div className="flex-1 text-center md:text-left">
                    <h3 className="text-xl font-black uppercase tracking-tighter italic">
                      Estado de la <span className={isFirebaseEnabled ? 'text-emerald-600' : 'text-red-600'}>Sincronización</span>
                    </h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">
                      {isFirebaseEnabled 
                        ? 'Conectado a Firebase Cloud. Los datos son reales y compartidos.' 
                        : 'Modo Offline: Debes editar App.tsx con tus credenciales de Firebase.'}
                    </p>
                </div>
                {!isFirebaseEnabled && (
                  <div className="bg-white/50 p-4 rounded-2xl border border-red-100">
                    <p className="text-[8px] font-bold text-red-800 uppercase leading-relaxed">
                      1. Crea proyecto en Firebase<br/>
                      2. Crea App Web<br/>
                      3. Pega las llaves en App.tsx
