                <h2 className="text-sm md:text-xl font-black uppercase tracking-tight italic text-slate-900">
                    {isStaffMode ? (activeView === 'kitchen' ? 'Comandas' : activeView === 'admin' ? 'Gestión Negocio' : 'Marketing IA') : restaurantSettings.name}
