                if (itemData.id) return prev.map(i => i.id === itemData.id ? itemData : i);
                return [...prev, { ...itemData, id: 'local_' + Date.now() }];
              });
              setIsAdminFormOpen(false);
            }
          }} 
          onClose={() => setIsAdminFormOpen(false)} 
        />
      )}
    </div>
  );
};

