  Settings, Store, LayoutGrid, Sparkles, TrendingUp, Bell, Image as ImageIcon, Wand2, Database, AlertTriangle, CloudOff, ChevronRight, Save, Check, PlusCircle, Info, Upload, Camera
} from 'lucide-react';
