const SidebarItem = ({ icon, label, active, onClick, badge }: any) => (
  <button onClick={onClick} className={`relative w-full p-5 flex items-center gap-5 rounded-[2rem] transition-all duration-300 group ${active ? 'bg-orange-600 text-white shadow-orange-glow' : 'text-white/40 hover:bg-white/5 hover:text-white'}`}>
    <div className={`transition-all duration-300 ${active ? 'scale-110' : 'group-hover:scale-110 opacity-60 group-hover:opacity-100'}`}>{icon}</div>
    <span className="text-[11px] font-black uppercase tracking-[0.2em] text-left truncate">{label}</span>
    {badge > 0 && <span className="absolute top-3 right-3 bg-white text-orange-600 text-[9px] font-black w-6 h-6 flex items-center justify-center rounded-xl shadow-lg border border-orange-100 animate-in zoom-in">{badge}</span>}
  </button>
);

const AdminForm = ({ item, onSave, onClose }: any) => {
  const [data, setData] = useState(item || { name: '', price: 0, category: 'Hamburguesas', image: '', description: '' });
  const [isGenerating, setIsGenerating] = useState(false);

  const handleAIDescription = async () => {
    if (!data.name) return alert("Ingresa un nombre primero");
    setIsGenerating(true);
    try { const desc = await improveDescription(data.name); setData({ ...data, description: desc }); } finally { setIsGenerating(false); }
  };

  const handleAIImage = async () => {
    if (!data.name) return alert("Ingresa un nombre primero");
    setIsGenerating(true);
    try { const img = await generateFoodImage(data.name); if (img) setData({ ...data, image: img }); } finally { setIsGenerating(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[300] flex items-center justify-center p-6 overflow-y-auto animate-in fade-in">
      <div className="bg-white w-full max-w-xl rounded-[3rem] p-10 md:p-14 shadow-2xl animate-in slide-in-from-bottom-10 text-slate-900">
        <div className="flex justify-between items-center mb-10">
          <h2 className="text-3xl font-black uppercase italic tracking-tighter">Detalles del <span className="text-orange-600 not-italic">Plato</span></h2>
          <button onClick={onClose} className="p-3 bg-slate-100 rounded-2xl btn-press"><X className="w-6 h-6" /></button>
        </div>
