  const [paymentSuccess, setPaymentSuccess] = useState(false);
  const [isAdminFormOpen, setIsAdminFormOpen] = useState(false);
  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [selectedFoodForDetail, setSelectedFoodForDetail] = useState<FoodItem | null>(null);

  const [restaurantSettings, setRestaurantSettings] = useState(() => {
    const saved = localStorage.getItem('santa_parrilla_settings');
    if (saved) return JSON.parse(saved);
    return { ...DEFAULT_BRANDING, logoUrl: '', name: 'Santa Parrilla' };
  });

  const [isSavingBranding, setIsSavingBranding] = useState(false);
  const [brandingSaved, setBrandingSaved] = useState(false);
  const [logoLoaded, setLogoLoaded] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
    try {
      const { data: menuData } = await supabase.from('menu').select('*');
      if (menuData && menuData.length > 0) setMenuItems(menuData);

      const { data: catData } = await supabase.from('categories').select('*');
      if (catData && catData.length > 0) setCategories(catData);

      const { data: ordersData } = await supabase
        .from('orders')
        .select('*')
        .neq('status', OrderStatus.DELIVERED)
        .order('createdAt', { ascending: false });
      if (ordersData) setOrders(ordersData);

      const { data: settingsData } = await supabase.from('settings').select('*').eq('id', 'branding').single();
      if (settingsData) {
        const newSettings = { name: settingsData.name, logoUrl: settingsData.logoUrl || DEFAULT_BRANDING.logoUrl };
        setRestaurantSettings(newSettings);
        localStorage.setItem('santa_parrilla_settings', JSON.stringify(newSettings));
      }
    } catch (err) {
      console.error("Fetch error:", err);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newUrl = reader.result as string;
        setRestaurantSettings(prev => ({ ...prev, logoUrl: newUrl }));
        setLogoLoaded(false); 
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveBranding = async () => {
    setIsSavingBranding(true);
    try {
      await supabase.from('settings').upsert({ id: 'branding', name: restaurantSettings.name, logoUrl: restaurantSettings.logoUrl });
      localStorage.setItem('santa_parrilla_settings', JSON.stringify(restaurantSettings));
      setBrandingSaved(true);
      setTimeout(() => setBrandingSaved(false), 3000);
      fetchData();
    } finally { setIsSavingBranding(false); }
  };

  const handleDeleteItem = async (id: string) => {
    if (!confirm("¿Eliminar este plato?")) return;
    try {
      await supabase.from('menu').delete().eq('id', id);
      fetchData();
    } catch (err) {
      setMenuItems(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleDeleteCategory = async (id: string) => {
    if (!confirm("¿Eliminar esta categoría? Los platos asociados quedarán sin categoría.")) return;
    try {
      await supabase.from('categories').delete().eq('id', id);
      fetchData();
    } catch (err) {
      setCategories(prev => prev.filter(c => c.id !== id));
    }
  };

  useEffect(() => {
    fetchData();
    const menuSub = supabase.channel('menu-rt').on('postgres_changes', { event: '*', schema: 'public', table: 'menu' }, fetchData).subscribe();
    const catSub = supabase.channel('cat-rt').on('postgres_changes', { event: '*', schema: 'public', table: 'categories' }, fetchData).subscribe();
    const ordersSub = supabase.channel('ord-rt').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, fetchData).subscribe();
    return () => { supabase.removeChannel(menuSub); supabase.removeChannel(catSub); supabase.removeChannel(ordersSub); };
  }, [isStaffMode]);

  const addToCart = (item: FoodItem, quantity: number = 1) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + quantity } : i);
      return [...prev, { ...item, quantity }];
    });
    setSelectedFoodForDetail(null);
  };

  const handlePayment = async () => {
    if (!customerName) return alert("Ingresa tu nombre");
    setIsPaying(true);
    try {
      const newOrder = { items: cart, total: cartTotal, status: OrderStatus.PENDING, customerName, tableNumber: tableNumber || 'Llevar', createdAt: new Date().toISOString() };
      await supabase.from('orders').insert([newOrder]);
      setCart([]);
      setPaymentSuccess(true);
      setTimeout(() => { setPaymentSuccess(false); setIsCartOpen(false); }, 2000);
    } finally { setIsPaying(false); }
  };

  const updateStatus = async (id: string, current: OrderStatus) => {
    const sequence = [OrderStatus.PENDING, OrderStatus.PREPARING, OrderStatus.READY, OrderStatus.DELIVERED];
    const nextIndex = sequence.indexOf(current) + 1;
    if (nextIndex >= sequence.length) return;
    await supabase.from('orders').update({ status: sequence[nextIndex] }).eq('id', id);
    fetchData();
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const filteredMenu = activeCategory === 'Todas' ? menuItems : menuItems.filter(i => i.category === activeCategory);

  if (!hasEntered) {
    return (
      <div className="fixed inset-0 z-[500] bg-[#020617] flex flex-col items-center justify-center p-8 overflow-hidden">
        <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-orange-600/20 blur-[150px] rounded-full"></div>
        <div className="absolute bottom-[-20%] right-[-20%] w-[60%] h-[60%] bg-orange-600/10 blur-[150px] rounded-full"></div>
        <div className="relative z-10 text-center space-y-16 animate-fade-scale">
          <div className="relative inline-block">
             <div className="absolute inset-0 bg-orange-500/20 blur-[80px] rounded-full scale-150 animate-pulse"></div>
             <div className="w-48 h-48 md:w-64 md:h-64 bg-slate-900 rounded-full p-2 border-4 border-orange-500/20 shadow-2xl relative flex items-center justify-center overflow-hidden">
               <div className="w-full h-full rounded-full overflow-hidden border-2 border-orange-500/50">
                {restaurantSettings.logoUrl ? (
                  <img src={restaurantSettings.logoUrl} className={`w-full h-full object-cover transition-opacity duration-1000 ${logoLoaded ? 'opacity-100' : 'opacity-0'}`} alt="Logo" onLoad={() => setLogoLoaded(true)} />
                ) : (
                  <div className="w-full h-full bg-slate-900 flex items-center justify-center"><div className="w-10 h-10 border-2 border-orange-500/30 border-t-orange-500 rounded-full animate-spin"></div></div>
                )}
               </div>
             </div>
          </div>
          <div className="space-y-4">
            <span className="font-lettering text-white text-3xl md:text-5xl block opacity-90">Bienvenido a</span>
            <h1 className="text-5xl md:text-8xl font-black text-orange-500 uppercase italic tracking-tighter leading-none drop-shadow-[0_5px_15px_rgba(249,115,22,0.3)]">{restaurantSettings.name}</h1>
          </div>
          <button onClick={() => setHasEntered(true)} className="group relative px-14 py-6 bg-orange-600 hover:bg-orange-500 text-white rounded-full font-black uppercase text-xs tracking-[0.4em] shadow-orange-glow transition-all hover:scale-105 active:scale-95 flex items-center gap-4 mx-auto btn-press">INGRESAR <ArrowRight className="w-5 h-5 group-hover:translate-x-2 transition-transform" /></button>
        </div>
      </div>
    );
  }

  const NavContent = () => (
    <div className="flex flex-col h-full glass-dark">
      <div className="p-10 text-center">
        <div className="w-24 h-24 bg-slate-800 rounded-3xl mx-auto flex items-center justify-center mb-6 shadow-2xl overflow-hidden border border-white/10 relative group">
          <img src={restaurantSettings.logoUrl || DEFAULT_BRANDING.logoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="Logo" />
        </div>
        <h1 className="text-xs font-black uppercase tracking-[0.5em] text-white/90 italic">{restaurantSettings.name}</h1>
      </div>
      <nav className="flex-1 px-6 space-y-3 overflow-y-auto no-scrollbar pb-10">
        {isStaffMode ? (
          <>
            <div className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] mb-4 ml-4">Terminal Cocina</div>
            <SidebarItem icon={<ChefHat className="w-5 h-5" />} label="Comandas" active={activeView === 'kitchen'} onClick={() => {setActiveView('kitchen'); setIsMobileMenuOpen(false);}} badge={orders.length} />
            <SidebarItem icon={<Settings className="w-5 h-5" />} label="Gestión" active={activeView === 'admin'} onClick={() => {setActiveView('admin'); setIsMobileMenuOpen(false);}} />
            <SidebarItem icon={<TrendingUp className="w-5 h-5" />} label="Reportes IA" active={activeView === 'stats'} onClick={() => {setActiveView('stats'); setIsMobileMenuOpen(false);}} />
            <button onClick={() => {setIsStaffMode(false); setActiveView('menu'); setIsMobileMenuOpen(false);}} className="w-full mt-10 p-5 text-rose-400 hover:bg-rose-500/10 rounded-2xl flex items-center gap-4 font-black text-[10px] uppercase transition-all btn-press"><LogOut className="w-4 h-4" /> Cerrar Sesión</button>
          </>
        ) : (
          <>
            <div className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] mb-4 ml-4">Categorías</div>
            <SidebarItem icon={<LayoutGrid className="w-5 h-5" />} label="Todas" active={activeCategory === 'Todas'} onClick={() => {setActiveCategory('Todas'); setIsMobileMenuOpen(false);}} />
            {categories.map(c => <SidebarItem key={c.id} icon={<span className="text-lg">{c.icon}</span>} label={c.name} active={activeCategory === c.name} onClick={() => {setActiveCategory(c.name); setIsMobileMenuOpen(false);}} />)}
            <div className="pt-10 border-t border-white/5 mt-6">
              <button onClick={() => {setShowLogin(true); setIsMobileMenuOpen(false);}} className="w-full p-5 bg-white/5 text-white/60 hover:text-white rounded-3xl flex items-center gap-4 font-black text-[9px] uppercase tracking-widest transition-all border border-white/5 btn-press"><Lock className="w-4 h-4" /> Acceso Staff</button>
            </div>
          </>
        )}
      </nav>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col md:flex-row font-sans bg-[#F8F9FA] text-slate-900">
      <aside className="hidden md:flex flex-col text-white w-72 h-screen sticky top-0 shrink-0"><NavContent /></aside>
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[100] md:hidden">
          <div className="absolute inset-0 bg-[#020617]/60 backdrop-blur-md" onClick={() => setIsMobileMenuOpen(false)} />
          <div className="relative w-72 h-full bg-[#020617] text-white shadow-2xl animate-in slide-in-from-left duration-300"><NavContent /></div>
        </div>
      )}
      <div className="flex-1 flex flex-col min-w-0">
        <header className="sticky top-0 glass border-b border-slate-200/50 z-40 px-6 py-4 flex justify-between items-center pt-safe">
          <div className="flex items-center gap-5">
            <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-3 bg-white rounded-2xl shadow-premium active:scale-90 text-slate-900"><LayoutGrid className="w-5 h-5" /></button>
            <div>
                <h2 className="text-sm md:text-2xl font-black uppercase tracking-tight italic text-slate-900 leading-none">{isStaffMode ? (activeView === 'kitchen' ? 'Comandas' : activeView === 'admin' ? 'Gestión Local' : 'Insights') : restaurantSettings.name}</h2>
                {!isStaffMode && <span className="text-[10px] font-bold text-orange-600 uppercase tracking-widest mt-1 block">{activeCategory}</span>}
            </div>
          </div>
          {!isStaffMode && (
            <button onClick={() => setIsCartOpen(true)} className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl flex items-center gap-4 relative shadow-2xl active:scale-95 transition-all btn-press">
              <ShoppingBag className="w-4 h-4 text-orange-400" />
              <span className="font-black text-xs tracking-wider">${cartTotal.toFixed(2)}</span>
              {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-orange-600 text-white text-[10px] font-black w-6 h-6 flex items-center justify-center rounded-full border-2 border-[#F8F9FA]">{cart.length}</span>}
            </button>
          )}
        </header>

        <main className="flex-1 p-4 md:p-12 max-w-7xl mx-auto w-full pb-32 animate-fade-scale">
          {activeView === 'menu' && !isStaffMode && (
            <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-10">
              {filteredMenu.map(item => (
                <div key={item.id} onClick={() => setSelectedFoodForDetail(item)} className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-premium flex flex-col group transition-all duration-300 hover:shadow-2xl hover:-translate-y-2 cursor-pointer">
                  <div className="h-40 md:h-60 overflow-hidden relative">
                    <img src={item.image} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" loading="lazy" />
                    <div className="absolute bottom-4 right-4 bg-orange-600 text-white px-4 py-2 rounded-2xl text-xs font-black shadow-xl border border-white/20">${item.price.toFixed(2)}</div>
                  </div>
                  <div className="p-5 md:p-8 flex flex-col flex-1">
                    <h3 className="text-xs md:text-lg font-black text-slate-900 line-clamp-1 mb-2 uppercase italic">{item.name}</h3>
                    <p className="text-[10px] md:text-xs text-slate-500 line-clamp-2 mb-8 leading-relaxed font-medium">{item.description}</p>
                    <button className="mt-auto w-full py-4 bg-slate-50 hover:bg-slate-900 hover:text-white transition-all rounded-3xl font-black text-[11px] uppercase border border-slate-100 text-slate-900 btn-press">Pedir Ahora</button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {isStaffMode && activeView === 'kitchen' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {orders.map(order => (
                <div key={order.id} className="bg-white border border-slate-200 rounded-[2.5rem] shadow-premium overflow-hidden flex flex-col relative animate-fade-scale">
                  <div className="p-6 border-b border-dashed flex justify-between items-center bg-slate-50/50">
                    <div>
                      <span className="font-mono text-[10px] text-slate-400 font-bold uppercase block mb-1">MESA • {order.tableNumber}</span>
                      <p className="text-sm font-black text-slate-900 uppercase italic leading-none">{order.customerName}</p>
                    </div>
                    <OrderTimer startTime={order.createdAt} />
                  </div>
                  <div className="p-8 flex-1 space-y-5">
                    {order.items.map((item, idx) => (
                      <div key={idx} className="flex items-center gap-4 text-sm font-bold text-slate-700">
                        <span className="bg-slate-900 text-white w-8 h-8 flex items-center justify-center rounded-xl text-[11px] font-black">{item.quantity}</span>
                        <span className="uppercase truncate flex-1">{item.name}</span>
                      </div>
                    ))}
                  </div>
                  <div className="p-8 pt-0"><button onClick={() => updateStatus(order.id, order.status)} className={`w-full py-5 rounded-3xl text-[11px] font-black uppercase tracking-widest shadow-xl transition-all btn-press ${order.status === 'READY' ? 'bg-emerald-600 text-white shadow-emerald-200' : 'bg-slate-900 text-white'}`}>{order.status === 'PENDING' ? 'Recibir' : order.status === 'PREPARING' ? 'Listo' : 'Entregado'}</button></div>
                </div>
              ))}
            </div>
          )}

          {isStaffMode && activeView === 'admin' && (
            <div className="max-w-4xl mx-auto space-y-12 pb-20">
                <div className="bg-white p-10 md:p-14 rounded-[3rem] border border-slate-200 shadow-premium">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-10 mb-12">
                        <div className="flex items-center gap-8">
                          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                            <div className="w-24 h-24 bg-slate-900 rounded-3xl flex items-center justify-center text-white shadow-2xl border-2 border-white/10 overflow-hidden transition-all duration-500 group-hover:border-orange-500">
                              {restaurantSettings.logoUrl ? <img src={restaurantSettings.logoUrl} className="w-full h-full object-cover" alt="Logo" /> : <Upload className="w-8 h-8 text-orange-500" />}
                            </div>
                            <input type="file" ref={fileInputRef} onChange={handleLogoUpload} className="hidden" accept="image/*" />
                          </div>
                          <div><h4 className="text-2xl font-black italic uppercase tracking-tighter text-slate-900 mb-2 leading-none">Identidad Visual</h4><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Logo y Marca</p></div>
                        </div>
                        <button onClick={handleSaveBranding} className={`flex items-center gap-4 px-12 py-5 rounded-full font-black text-xs uppercase shadow-xl btn-press ${brandingSaved ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white'}`}>{isSavingBranding ? 'Guardando...' : brandingSaved ? '¡Guardado!' : 'Guardar'}</button>
                    </div>
                    <input type="text" value={restaurantSettings.name} onChange={e => setRestaurantSettings({...restaurantSettings, name: e.target.value})} className="w-full p-6 bg-slate-50 rounded-3xl font-black text-sm outline-none border border-slate-200 shadow-inner" placeholder="Nombre comercial" />
                </div>

                <div className="space-y-6">
                  <div className="flex justify-between items-center px-6">
                    <div><h4 className="text-3xl font-black italic uppercase tracking-tighter text-slate-900">Categorías</h4><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Organiza tu menú</p></div>
                    <button onClick={() => { setEditingCategory(null); setIsCategoryFormOpen(true); }} className="bg-orange-600 text-white px-8 py-4 rounded-full font-black text-[10px] uppercase shadow-orange-glow btn-press flex items-center gap-3"><PlusCircle className="w-4 h-4" /> Nueva</button>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {categories.map(cat => (
                      <div key={cat.id} className="bg-white p-5 rounded-[2rem] border border-slate-200 flex items-center gap-5 group hover:border-orange-200 transition-all shadow-sm">
                        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-2xl shadow-inner border border-slate-100">{cat.icon}</div>
                        <div className="flex-1"><h5 className="font-black uppercase text-xs italic text-slate-900">{cat.name}</h5></div>
                        <div className="flex items-center gap-2">
                          <button onClick={() => { setEditingCategory(cat); setIsCategoryFormOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-xl transition-all btn-press"><Edit2 className="w-3.5 h-3.5" /></button>
                          <button onClick={() => handleDeleteCategory(cat.id)} className="p-3 bg-rose-50 text-rose-400 hover:text-white hover:bg-rose-500 rounded-xl transition-all btn-press"><Trash2 className="w-3.5 h-3.5" /></button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex justify-between items-center px-6">
                    <div><h4 className="text-3xl font-black italic uppercase tracking-tighter text-slate-900">Menú</h4><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Platos y precios</p></div>
                    <button onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }} className="bg-slate-900 text-white px-8 py-4 rounded-full font-black text-[10px] uppercase shadow-slate-200 btn-press flex items-center gap-3"><PlusCircle className="w-4 h-4" /> Nuevo Plato</button>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    {menuItems.map(item => (
                      <div key={item.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-premium flex items-center gap-6 group hover:border-orange-200 transition-all">
                        <img src={item.image} className="w-20 h-20 rounded-[1.5rem] object-cover shadow-lg" />
                        <div className="flex-1 min-w-0"><h5 className="font-black uppercase text-xs italic mb-1 truncate text-slate-900">{item.name}</h5><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{item.category}</p></div>
                        <div className="flex items-center gap-3">
                          <button onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-xl btn-press"><Edit2 className="w-4 h-4" /></button>
                          <button onClick={() => handleDeleteItem(item.id)} className="p-3 bg-rose-50 text-rose-400 hover:bg-rose-500 hover:text-white rounded-xl btn-press"><Trash2 className="w-4 h-4" /></button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
            </div>
          )}
        </main>
      </div>

      {showLogin && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-2xl z-[150] flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white w-full max-w-sm rounded-[3rem] p-12 text-center shadow-2xl">
             <div className="w-20 h-20 bg-slate-50 rounded-[2rem] flex items-center justify-center mx-auto mb-10 text-slate-900 shadow-inner"><Lock className="w-10 h-10" /></div>
             <input type="password" placeholder="••••" maxLength={4} className="w-full py-6 bg-slate-50 rounded-3xl text-center text-5xl font-black tracking-[0.8em] outline-none border border-slate-200 focus:border-orange-500 shadow-inner" autoFocus onChange={(e) => { if(e.target.value === '1234') { setIsStaffMode(true); setShowLogin(false); setActiveView('kitchen'); } }} />
             <button onClick={() => setShowLogin(false)} className="mt-10 text-[10px] font-black text-slate-400 uppercase tracking-widest">Cancelar</button>
          </div>
        </div>
      )}

      {selectedFoodForDetail && <FoodDetailModal item={selectedFoodForDetail} onAdd={addToCart} onClose={() => setSelectedFoodForDetail(null)} />}
      {isCartOpen && <CartView cart={cart} setCart={setCart} customerName={customerName} setCustomerName={setCustomerName} tableNumber={tableNumber} setTableNumber={setTableNumber} cartTotal={cartTotal} isPaying={isPaying} paymentSuccess={paymentSuccess} handlePayment={handlePayment} onClose={() => setIsCartOpen(false)} />}
      {isAdminFormOpen && <AdminForm item={editingItem} categories={categories} onSave={async (d: any) => { if(d.id && !String(d.id).startsWith('local_')) await supabase.from('menu').upsert(d); else await supabase.from('menu').insert([{...d, id: undefined}]); setIsAdminFormOpen(false); fetchData(); }} onClose={() => setIsAdminFormOpen(false)} />}
      {isCategoryFormOpen && <CategoryForm category={editingCategory} onSave={async (d: any) => { if(d.id) await supabase.from('categories').upsert(d); else await supabase.from('categories').insert([{...d, id: undefined}]); setIsCategoryFormOpen(false); fetchData(); }} onClose={() => setIsCategoryFormOpen(false)} />}
    </div>
  );
};

const SidebarItem = ({ icon, label, active, onClick, badge }: any) => (
  <button onClick={onClick} className={`relative w-full p-5 flex items-center gap-5 rounded-[2rem] transition-all duration-300 group ${active ? 'bg-orange-600 text-white shadow-orange-glow' : 'text-white/40 hover:bg-white/5 hover:text-white'}`}>
    <div className={`transition-all duration-300 ${active ? 'scale-110' : 'group-hover:scale-110 opacity-60 group-hover:opacity-100'}`}>{icon}</div>
    <span className="text-[11px] font-black uppercase tracking-[0.2em] text-left truncate">{label}</span>
    {badge > 0 && <span className="absolute top-3 right-3 bg-white text-orange-600 text-[9px] font-black w-6 h-6 flex items-center justify-center rounded-xl shadow-lg border border-orange-100">{badge}</span>}
  </button>
);

const FoodDetailModal = ({ item, onAdd, onClose }: { item: FoodItem, onAdd: (item: FoodItem, qty: number) => void, onClose: () => void }) => {
  const [qty, setQty] = useState(1);
  const calculatorKeys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'C', '0', 'OK'];

  const handleKeyClick = (key: string) => {
    if (key === 'C') setQty(0);
    else if (key === 'OK') onAdd(item, Math.max(1, qty));
    else {
      const newQty = parseInt(qty.toString() + key);
      if (newQty <= 99) setQty(newQty);
    }
  };

  return (
    <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-xl animate-in fade-in" onClick={onClose} />
      <div className="relative w-full max-w-md bg-white rounded-[3.5rem] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-300">
        <div className="h-56 relative">
          <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
          <button onClick={onClose} className="absolute top-6 right-6 p-3 bg-white/20 backdrop-blur rounded-2xl text-white hover:bg-white/40 transition-all"><X className="w-6 h-6" /></button>
          <div className="absolute -bottom-6 right-8 bg-orange-600 text-white px-8 py-4 rounded-3xl font-black text-2xl italic shadow-2xl border-4 border-white tracking-tighter">
            ${(item.price * Math.max(1, qty)).toFixed(2)}
          </div>
        </div>

        <div className="p-10 pt-12 space-y-8">
          <div>
            <h2 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900 leading-none mb-4">{item.name}</h2>
            <p className="text-sm text-slate-500 font-medium leading-relaxed">{item.description}</p>
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center mb-2 px-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Cantidad a pedir</label>
              <div className="flex items-center gap-4 bg-slate-100 px-4 py-2 rounded-2xl">
                <button onClick={() => setQty(q => Math.max(1, q - 1))} className="text-slate-400 hover:text-slate-900 transition-colors"><Minus className="w-5 h-5" /></button>
                <span className="text-2xl font-black text-slate-900 w-8 text-center">{qty}</span>
                <button onClick={() => setQty(q => q + 1)} className="text-slate-400 hover:text-slate-900 transition-colors"><Plus className="w-5 h-5" /></button>
              </div>
            </div>

