                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {categories.map(cat => (
                      <div key={cat.id} className="bg-white p-5 rounded-[2rem] border border-slate-200 flex items-center gap-5 shadow-sm">
