const AnimatedFireBackground = () => {
  const sparks = useMemo(() => {
    return Array.from({ length: 40 }).map((_, i) => ({
      id: i,
      left: `${Math.random() * 100}%`,
      duration: `${4 + Math.random() * 6}s`,
      delay: `${Math.random() * 5}s`,
      drift: `${(Math.random() - 0.5) * 200}px`,
      size: `${1 + Math.random() * 3}px`
    }));
  }, []);

  return (
    <div className="fixed inset-0 bg-[#020617] overflow-hidden pointer-events-none">
      {/* Resplandor base de brasas */}
      <div 
        className="absolute bottom-[-10%] left-1/2 -translate-x-1/2 w-[150%] h-[60%] bg-orange-900/40 rounded-[100%] mix-blend-screen"
        style={{ animation: 'fireGlow 6s infinite ease-in-out', filter: 'blur(100px)' }}
      />

      {/* Chispas animadas */}
      {sparks.map(spark => (
        <div
          key={spark.id}
          className="spark"
          style={{
            left: spark.left,
            width: spark.size,
            height: spark.size,
            '--drift': spark.drift,
            animation: `sparkUp ${spark.duration} linear infinite ${spark.delay}`
          } as any}
        />
      ))}

      {/* Humo/Niebla sutil */}
      <div className="absolute inset-0 bg-gradient-to-t from-orange-950/20 to-transparent opacity-50" />
    </div>
  );
};

const OrderTimer: React.FC<{ startTime: any }> = ({ startTime }) => {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const start = typeof startTime === 'string' ? new Date(startTime).getTime() : startTime;
    const interval = setInterval(() => {
      setElapsed(Math.floor((Date.now() - start) / 60000));
    }, 10000);
    setElapsed(Math.floor((Date.now() - start) / 60000));
    return () => clearInterval(interval);
  }, [startTime]);

  const getColor = () => {
    if (elapsed > 20) return 'bg-rose-500 shadow-rose-200 animate-pulse';
    if (elapsed > 10) return 'bg-amber-500 shadow-amber-200';
    return 'bg-emerald-500 shadow-emerald-200';
  };

  return (
    <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold text-white shadow-lg transition-colors ${getColor()}`}>
      <Timer className="w-3 h-3" /> {elapsed} min
    </div>
  );
};

