        if(d.id) {
          await supabase.from('categories').upsert(d); 
        } else {
          const { id, ...newCat } = d;
          await supabase.from('categories').insert([newCat]);
        }
        setIsCategoryFormOpen(false); 
        fetchData(); 
      }} onClose={() => setIsCategoryFormOpen(false)} />}
    </div>
