      left: `${Math.random() * 100}%`,
      duration: `${3 + Math.random() * 7}s`,
      delay: `${Math.random() * 10}s`,
      drift: `${(Math.random() - 0.5) * 300}px`,
      size: `${1 + Math.random() * 4}px`,
      rot: `${Math.random() * 360}deg`,
      opacity: 0.3 + Math.random() * 0.7
    }));
  }, []);

  return (
