          key={spark.id}
          className="spark"
          style={{
            left: spark.left,
            width: spark.size,
            height: `calc(${spark.size} * 2)`,
            opacity: spark.opacity,
            '--drift': spark.drift,
            '--rot': spark.rot,
            animation: `sparkUp ${spark.duration} linear infinite ${spark.delay}`
          } as any}
        />
      ))}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(2,6,23,0.9)_100%)]" />
