          if (d.id && !isInitial) await supabase.from('menu').upsert(d);
          else { const { id, ...newItem } = d; await supabase.from('menu').insert([newItem]); }
          setIsAdminFormOpen(false); fetchData();
        }} onClose={() => setIsAdminFormOpen(false)} />
