                                alert("Código copiado");
                             }} className="absolute top-4 right-4 bg-white/10 hover:bg-white/20 text-white px-3 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest transition-all">Copiar</button>
                          </div>
