      {isAdminFormOpen && (
        <AdminForm item={editingItem} categories={categories} onSave={async (d: any) => { 
          const isInitial = d.id && (d.id.startsWith('b') || d.id.startsWith('c') || d.id.startsWith('p') || d.id.startsWith('add'));
