          setCart={setOrderItems} 
          customerName={customerName} 
          setCustomerName={setCustomerName} 
          tableNumber={tableNumber} 
          setTableNumber={setTableNumber} 
          cartTotal={cartTotal} 
          isPaying={isPaying} 
          paymentSuccess={paymentSuccess} 
          handlePayment={handlePaymentConfirm} 
