              <button onClick={() => setShowWebhookHelp(false)} className="absolute top-8 right-8 p-3 bg-slate-100 rounded-2xl text-slate-900"><X className="w-6 h-6" /></button>
              <div className="space-y-8">
                 <h2 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900">Conectar con <span className="text-orange-600 not-italic">Sheets</span></h2>
                 <div className="space-y-6">
                    <div className="flex gap-6 items-start">
                       <div className="w-12 h-12 bg-orange-600 rounded-2xl flex items-center justify-center text-white font-black shrink-0">1</div>
                       <div><p className="font-black text-xs uppercase tracking-widest">Abre tu Google Sheet</p><p className="text-xs text-slate-500">Ve a Extensiones > Apps Script.</p></div>
                    </div>
                    <div className="bg-slate-950 p-6 rounded-3xl relative">
                       <pre className="text-[10px] font-mono text-orange-300 overflow-x-auto">
{`function doPost(e) {
  var data = JSON.parse(e.postData.contents);
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  sheet.appendRow([new Date(), data.restaurantName, data.date, data.totalSales, data.orderCount, JSON.stringify(data.itemsReport)]);
  return ContentService.createTextOutput("OK");
}`}
                       </pre>
                       <button onClick={() => navigator.clipboard.writeText(`function doPost(e) {\n  var data = JSON.parse(e.postData.contents);\n  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();\n  sheet.appendRow([new Date(), data.restaurantName, data.date, data.totalSales, data.orderCount, JSON.stringify(data.itemsReport)]);\n  return ContentService.createTextOutput("OK");\n}`)} className="absolute top-4 right-4 bg-white/10 text-white px-3 py-1.5 rounded-xl text-[8px] font-black uppercase">Copiar</button>
                    </div>
                 </div>
                 <button onClick={() => setShowWebhookHelp(false)} className="w-full py-5 bg-slate-900 text-white rounded-full font-black uppercase text-[10px] tracking-[0.2em]">Entendido</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

