  </button>
);

const FoodDetailModal = ({ item, additions, onAdd, onClose }: { item: FoodItem, additions: FoodItem[], onAdd: (item: FoodItem, qty: number, additions: FoodItem[]) => void, onClose: () => void }) => {
  const [qty, setQty] = useState(1);
  const [selectedAdds, setSelectedAdds] = useState<FoodItem[]>([]);
  const toggleAddition = (add: FoodItem) => setSelectedAdds(prev => prev.find(i => i.id === add.id) ? prev.filter(i => i.id !== add.id) : [...prev, add]);
  const totalPrice = (item.price + selectedAdds.reduce((sum, a) => sum + a.price, 0)) * qty;

  return (
    <div className="fixed inset-0 z-[400] flex items-end md:items-center justify-center p-0 md:p-4 backdrop-blur-xl">
      <div className="absolute inset-0 bg-slate-900/60" onClick={onClose} />
      <div className="relative w-full max-w-xl bg-white rounded-t-[2.5rem] md:rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[95vh] md:max-h-[90vh]">
        <div className="relative h-48 md:h-72 shrink-0">
          <img src={item.image} className="w-full h-full object-cover" />
          <button onClick={onClose} className="absolute top-6 right-6 p-3 bg-black/20 backdrop-blur-md rounded-2xl text-white"><X className="w-6 h-6" /></button>
          <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-white via-white/80 to-transparent p-6 md:p-10 pt-16">
             <div className="flex justify-between items-end gap-4"><div className="min-w-0"><h2 className="text-xl md:text-4xl font-black uppercase italic tracking-tighter text-slate-900 leading-tight mb-1 truncate">{item.name}</h2><p className="text-[9px] md:text-xs font-black text-orange-600 uppercase tracking-widest">{item.category}</p></div><div className="text-right shrink-0"><span className="text-[8px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Subtotal</span><span className="text-xl md:text-3xl font-black text-slate-900 italic tracking-tighter leading-none">${formatPrice(totalPrice)}</span></div></div>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-6 md:p-10 space-y-6 md:space-y-8 no-scrollbar">
          <p className="text-xs md:text-sm text-slate-500 font-medium leading-relaxed">{item.description}</p>
          <div className="space-y-4">
            <div className="flex justify-between items-center"><label className="text-[10px] md:text-[11px] font-black text-slate-900 uppercase tracking-widest">¿Algo extra?</label></div>
            <div className="relative">
              <div className="max-h-56 md:max-h-64 overflow-y-auto pr-2 space-y-2 md:space-y-3 custom-scrollbar relative">
                {additions.length > 0 ? additions.map(add => { 
                  const isSelected = selectedAdds.find(i => i.id === add.id); 
                  return (
                    <button key={add.id} onClick={() => toggleAddition(add)} className={`w-full p-4 md:p-5 rounded-2xl md:rounded-3xl border transition-all flex items-center justify-between group ${isSelected ? 'bg-orange-600 border-orange-500 text-white shadow-orange-glow' : 'bg-slate-50 border-slate-100 hover:border-slate-200 text-slate-900'}`}>
                      <div className="flex items-center gap-3 md:gap-4 text-left">
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${isSelected ? 'bg-white/20' : 'bg-white shadow-sm'}`}><Plus className={`w-3.5 h-3.5 ${isSelected ? 'text-white' : 'text-slate-400 group-hover:text-slate-900'}`} /></div>
                        <div><p className="text-[10px] md:text-[11px] font-black uppercase italic leading-none mb-1">{add.name}</p><p className={`text-[9px] md:text-[10px] font-bold ${isSelected ? 'text-orange-200' : 'text-slate-400'}`}>+${formatPrice(add.price)}</p></div>
                      </div>
                      {isSelected && <Check className="w-4 h-4" />}
                    </button>
                  ); 
                }) : <p className="text-center text-[10px] text-slate-400 py-4 uppercase font-black">No hay adiciones disponibles</p>}
              </div>
              {additions.length > 3 && (
                <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-white to-transparent pointer-events-none flex items-end justify-center pb-1">
                  <ChevronDown className="w-4 h-4 text-slate-300 animate-bounce" />
                </div>
              )}
            </div>
          </div>
        </div>
        <div className="p-6 md:p-10 border-t bg-slate-50 flex items-center justify-between gap-4 pb-safe shrink-0">
          <div className="flex items-center gap-3 bg-white p-1.5 rounded-full border border-slate-200 shrink-0"><button onClick={() => setQty(q => Math.max(1, q - 1))} className="w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center text-slate-400"><Minus className="w-5 h-5" /></button><span className="text-lg md:text-2xl font-black text-slate-900 w-8 md:w-10 text-center italic">{qty}</span><button onClick={() => setQty(q => q + 1)} className="w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center bg-slate-900 text-white shadow-lg"><Plus className="w-5 h-5" /></button></div>
          <button onClick={() => onAdd(item, qty, selectedAdds)} className="flex-1 py-5 bg-orange-600 text-white rounded-full font-black uppercase text-[10px] tracking-[0.3em] shadow-orange-glow hover:bg-orange-500 transition-all btn-press flex items-center justify-center gap-2">CONFIRMAR <ChevronRight className="w-5 h-5" /></button>
        </div>
      </div>
    </div>
  );
};

const CartView = ({ 
  cart, 
  setCart, 
  customerName, 
  setCustomerName, 
  tableNumber, 
  setTableNumber, 
  cartTotal, 
  isPaying, 
  paymentSuccess, 
  handlePayment, 
  onClose,
  selectedPaymentMethod,
  setSelectedPaymentMethod,
  showTransferScreen,
  setShowTransferScreen,
  restaurantSettings
}: any) => {
  const removeItem = (idx: number) => setCart((prev: any[]) => prev.filter((_, i) => i !== idx));
  return (
    <div className="fixed inset-0 z-[200] flex justify-end">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={onClose} />
      <div className="relative w-full max-w-md bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-500">
         <div className="p-6 md:p-8 border-b flex justify-between items-center pt-safe">
           <h2 className="text-xl md:text-2xl font-black italic uppercase tracking-tighter text-slate-900">Tu <span className="text-orange-600 not-italic">Orden</span></h2>
           <button onClick={onClose} className="p-2 bg-slate-100 rounded-xl text-slate-900"><X className="w-5 h-5" /></button>
         </div>
         {showTransferScreen ? (
           <div className="flex-1 flex flex-col p-8 text-center animate-in zoom-in duration-300">
             <div className="mb-8"><div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4"><ArrowRightLeft className="w-8 h-8" /></div><h3 className="text-2xl font-black uppercase italic tracking-tighter text-slate-900">Transferencia</h3><p className="text-slate-500 text-xs font-medium mt-2">Paga un total de <span className="font-black text-slate-900 italic">${formatPrice(cartTotal)}</span></p></div>
             <div className="flex-1 flex flex-col items-center justify-center"><div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 shadow-inner w-full">{restaurantSettings.qrUrl ? (<div className="space-y-6"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Escanea para pagar</p><img src={restaurantSettings.qrUrl} className="w-full max-w-[200px] mx-auto rounded-2xl shadow-xl" /></div>) : (<div className="py-12 opacity-40"><QrCode className="w-12 h-12 mx-auto mb-2" /><p className="text-[10px] font-black uppercase tracking-widest">Código QR no disponible</p></div>)}</div>{restaurantSettings.transferUrl && (<a href={restaurantSettings.transferUrl} target="_blank" rel="noopener noreferrer" className="mt-8 flex items-center gap-3 text-blue-600 font-black text-[10px] uppercase tracking-widest hover:underline">Abrir App Bancaria <ExternalLink className="w-4 h-4" /></a>)}</div>
             <div className="mt-8 space-y-4"><button onClick={handlePayment} className="w-full py-5 bg-slate-900 text-white rounded-full font-black uppercase text-[10px] tracking-[0.2em] shadow-xl">YA REALICÉ EL PAGO</button><button onClick={() => setShowTransferScreen(false)} className="w-full text-[9px] font-black text-slate-400 uppercase tracking-widest">VOLVER ATRÁS</button></div>
           </div>
         ) : (
           <>
             <div className="flex-1 overflow-y-auto p-6 md:p-8 space-y-8 no-scrollbar">
                <div className="space-y-4">{cart.length === 0 ? (<div className="py-24 text-center opacity-20"><ShoppingBasket className="w-16 h-16 mx-auto mb-6 text-slate-900" /><p className="font-black uppercase text-[10px] tracking-[0.3em]">Carrito Vacío</p></div>) : cart.map((item: any, idx: number) => { const addsPrice = (item.additions || []).reduce((sum: number, add: any) => sum + add.price, 0); return (<div key={idx} className="flex flex-col gap-3 bg-slate-50/80 p-5 rounded-[2rem] border border-slate-100 relative"><button onClick={() => removeItem(idx)} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 className="w-4 h-4" /></button><div className="flex items-center gap-4"><img src={item.image} className="w-14 h-14 rounded-xl object-cover shadow-lg shrink-0" /><div className="flex-1 min-w-0"><p className="text-[11px] font-black uppercase italic text-slate-900 truncate mb-1">{item.name}</p><p className="text-[9px] font-black text-orange-600 uppercase tracking-widest">${formatPrice(item.price + addsPrice)} c/u</p><p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">Cant: {item.quantity}</p></div></div></div>); })}</div>
                {cart.length > 0 && (<><div className="space-y-4"><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Datos de Entrega</h4><div className="space-y-3"><input type="text" placeholder="Tu Nombre" value={customerName} onChange={e => setCustomerName(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl outline-none font-black text-[10px] uppercase border border-slate-100 focus:border-orange-500 shadow-inner" /><input type="text" placeholder="Mesa o Dirección" value={tableNumber} onChange={e => setTableNumber(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl outline-none font-black text-[10px] uppercase border border-slate-100 focus:border-orange-500 shadow-inner" /></div></div><div className="space-y-4"><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Método de Pago</h4><div className="grid grid-cols-2 gap-4"><button onClick={() => setSelectedPaymentMethod('CASH')} className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] border-2 transition-all ${selectedPaymentMethod === 'CASH' ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-lg scale-105' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}><Banknote className="w-8 h-8" /><span className="text-[9px] font-black uppercase tracking-widest">Efectivo</span></button><button onClick={() => setSelectedPaymentMethod('TRANSFER')} className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] border-2 transition-all ${selectedPaymentMethod === 'TRANSFER' ? 'bg-blue-50 border-blue-500 text-blue-700 shadow-lg scale-105' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}><QrCode className="w-8 h-8" /><span className="text-[9px] font-black uppercase tracking-widest">Transferencia</span></button></div></div></>)}
             </div>
             <div className="p-6 md:p-10 border-t glass pb-safe"><div className="flex justify-between items-end mb-6 text-slate-900"><span className="text-[10px] font-black uppercase text-slate-400 tracking-[0.4em] mb-1 leading-none">Total Orden</span><span className="text-3xl font-black tracking-tighter italic leading-none">${formatPrice(cartTotal)}</span></div><button onClick={handlePayment} disabled={cart.length === 0 || isPaying || !customerName} className={`w-full py-5 rounded-full font-black text-[10px] uppercase tracking-[0.2em] shadow-2xl transition-all btn-press ${paymentSuccess ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white disabled:opacity-20'}`}>{isPaying ? 'Procesando...' : paymentSuccess ? '¡Listo!' : (selectedPaymentMethod === 'TRANSFER' ? 'Pagar con Transferencia' : 'Confirmar Pedido')}</button></div>
           </>
         )}
      </div>
    </div>
  );
};

const OrderTrackingView = ({ order, onClose }: { order: Order, onClose: () => void }) => {
  const steps = [{ status: OrderStatus.PENDING, label: 'Recibido', icon: <Bell className="w-6 h-6" /> }, { status: OrderStatus.PREPARING, label: 'Cocinando', icon: <UtensilsCrossed className="w-6 h-6" /> }, { status: OrderStatus.READY, label: '¡Listo!', icon: <Sparkles className="w-6 h-6" /> }];
  const currentIdx = steps.findIndex(s => s.status === order.status);
  return (
    <div className="fixed inset-0 z-[450] bg-slate-950 flex flex-col p-6 animate-in fade-in"><AnimatedFireBackground /><div className="relative z-10 flex-1 flex flex-col max-w-xl mx-auto w-full"><header className="flex justify-between items-center py-8"><button onClick={onClose} className="p-4 bg-white/5 rounded-2xl text-white hover:bg-white/10 transition-all"><X className="w-6 h-6" /></button><div className="text-right"><p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-1">Orden #{order.id.slice(-4).toUpperCase()}</p><h3 className="text-white font-black text-xl italic uppercase truncate max-w-[150px]">{order.customerName}</h3></div></header><main className="flex-1 flex flex-col items-center justify-center text-center space-y-12"><div className="relative"><div className={`w-48 h-48 md:w-64 md:h-64 rounded-full border-[6px] border-orange-500/20 flex items-center justify-center relative ${order.status === OrderStatus.READY ? 'shadow-[0_0_80px_rgba(249,115,22,0.4)] animate-pulse' : ''}`}><div className="absolute inset-4 rounded-full border-2 border-dashed border-orange-500/30 animate-spin-slow" /><div className="flex flex-col items-center gap-4"><div className="w-20 h-20 md:w-28 md:h-28 bg-orange-600 rounded-3xl md:rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl animate-bounce">{steps[currentIdx]?.icon}</div><div className="space-y-1"><p className="text-[10px] font-black text-white/40 uppercase tracking-[0.4em]">Estado Actual</p><h2 className="text-3xl md:text-5xl font-black text-white uppercase italic tracking-tighter">{steps[currentIdx]?.label}</h2></div></div></div></div><div className="w-full space-y-8"><div className="flex justify-between relative px-2"><div className="absolute top-1/2 left-0 right-0 h-1 bg-white/5 -translate-y-1/2 rounded-full" /><div className="absolute top-1/2 left-0 h-1 bg-orange-600 -translate-y-1/2 rounded-full transition-all duration-1000" style={{ width: `${(currentIdx / (steps.length - 1)) * 100}%` }} />{steps.map((s, i) => (<div key={i} className="relative z-10 flex flex-col items-center gap-3"><div className={`w-10 h-10 md:w-14 md:h-14 rounded-full flex items-center justify-center border-4 transition-all duration-500 ${i <= currentIdx ? 'bg-orange-600 border-orange-400 text-white scale-110' : 'bg-slate-900 border-slate-800 text-white/20'}`}>{i <= currentIdx ? <Check className="w-4 h-4 md:w-6 md:h-6" /> : <span className="text-xs font-black">{i + 1}</span>}</div><span className={`text-[8px] md:text-[10px] font-black uppercase tracking-widest ${i <= currentIdx ? 'text-white' : 'text-white/20'}`}>{s.label}</span></div>))}</div></div></main><footer className="py-10"><button onClick={onClose} className="w-full py-5 bg-white text-slate-950 rounded-full font-black uppercase text-[10px] tracking-[0.4em] shadow-2xl active:scale-95 transition-all">Seguir Mirando el Menú</button></footer></div></div>
  );
};

const CategoryForm = ({ category, onSave, onClose }: any) => {
