                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Icono de la App</p>
                        <div className="w-40 h-40 bg-slate-50 rounded-[2.5rem] mx-auto border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                           {isUploading === 'logo' ? <Loader2 className="w-8 h-8 animate-spin text-orange-500" /> : <img src={restaurantSettings.logoUrl} className="w-full h-full object-cover" />}
                        </div>
                        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, 'logo')} />
                     </div>
                     <div className="text-center space-y-4">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">QR de Pagos</p>
                        <div className="w-40 h-40 bg-slate-50 rounded-[2.5rem] mx-auto border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer" onClick={() => qrInputRef.current?.click()}>
                           {isUploading === 'qr' ? <Loader2 className="w-8 h-8 animate-spin text-orange-500" /> : restaurantSettings.qrUrl ? <img src={restaurantSettings.qrUrl} className="w-full h-full object-contain p-4" /> : <QrCode className="w-8 h-8 text-slate-300" />}
                        </div>
                        <input type="file" ref={qrInputRef} className="hidden" accept="image/*" onChange={(e) => handleFileUpload(e, 'qr')} />
                     </div>
                  </div>
               </div>

               <div className="flex justify-between items-center">
                 <h4 className="text-xl font-black uppercase italic">Mi Menú</h4>
                 <button onClick={() => { setEditingItem(null); setIsAdminFormOpen(true); }} className="px-8 py-4 bg-slate-900 text-white rounded-full font-black text-[10px] uppercase shadow-xl hover:scale-105 transition-all flex items-center gap-2"><PlusCircle className="w-4 h-4" /> Nuevo Plato</button>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {menuItems.map(item => (
                   <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 flex items-center gap-6 shadow-sm">
                      <img src={item.image} className="w-16 h-16 rounded-2xl object-cover" />
                      <div className="flex-1">
                        <h5 className="font-black uppercase text-xs italic">{item.name}</h5>
                        <p className="text-[9px] font-black text-orange-600 tracking-tighter">${formatPrice(item.price)}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => { setEditingItem(item); setIsAdminFormOpen(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:text-slate-900"><Edit2 className="w-4 h-4" /></button>
                        <button onClick={async () => await supabase.from('menu').delete().eq('id', item.id)} className="p-3 bg-rose-50 text-rose-400 rounded-xl hover:bg-rose-100"><Trash2 className="w-3.5 h-3.5" /></button>
                      </div>
                   </div>
                 ))}
               </div>
            </div>
          )}
        </main>
      </div>

      {/* Cart Drawer */}
      {isCartOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[500] flex justify-end">
          <div className="bg-white w-full max-w-md h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
             <div className="p-8 border-b flex justify-between items-center">
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">Mi Pedido</h3>
                <button onClick={() => setIsCartOpen(false)} className="p-3 bg-slate-50 rounded-2xl"><X className="w-6 h-6" /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-8 space-y-6">
                {cart.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4">
                    <ShoppingBasket className="w-16 h-16 opacity-20" />
                    <p className="font-black uppercase text-[10px] tracking-[0.2em]">Carrito Vacío</p>
                  </div>
                ) : (
                  cart.map(item => (
                    <div key={item.id} className="flex gap-4 items-center">
                       <img src={item.image} className="w-20 h-20 rounded-2xl object-cover" />
                       <div className="flex-1">
                          <h4 className="font-black uppercase text-xs">{item.name}</h4>
                          <p className="text-[10px] font-bold text-orange-600">${formatPrice(item.price)}</p>
                       </div>
                       <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-2xl">
                          <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:text-orange-600"><Minus className="w-4 h-4" /></button>
                          <span className="font-black text-sm w-4 text-center">{item.quantity}</span>
                          <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:text-orange-600"><Plus className="w-4 h-4" /></button>
                       </div>
                    </div>
                  ))
                )}
             </div>
             {cart.length > 0 && (
               <div className="p-8 bg-slate-50 space-y-6">
                  <div className="space-y-4">
                     <div className="flex gap-4">
                       <input value={customerName} onChange={e => setCustomerName(e.target.value)} placeholder="Tu nombre..." className="flex-1 p-4 bg-white rounded-2xl font-black text-xs outline-none border border-slate-200" />
                       <input value={tableNumber} onChange={e => setTableNumber(e.target.value)} placeholder="Mesa..." className="w-24 p-4 bg-white rounded-2xl font-black text-xs outline-none border border-slate-200 text-center" />
                     </div>
                     <div className="flex gap-2">
                        <button onClick={() => setSelectedPaymentMethod('CASH')} className={`flex-1 py-4 rounded-2xl font-black text-[9px] uppercase tracking-widest flex items-center justify-center gap-2 border-2 transition-all ${selectedPaymentMethod === 'CASH' ? 'border-slate-900 bg-slate-900 text-white' : 'border-slate-200 bg-white'}`}><Banknote className="w-4 h-4" /> Efectivo</button>
                        <button onClick={() => setSelectedPaymentMethod('TRANSFER')} className={`flex-1 py-4 rounded-2xl font-black text-[9px] uppercase tracking-widest flex items-center justify-center gap-2 border-2 transition-all ${selectedPaymentMethod === 'TRANSFER' ? 'border-orange-600 bg-orange-600 text-white' : 'border-slate-200 bg-white'}`}><CreditCard className="w-4 h-4" /> Transferencia</button>
                     </div>
                  </div>
                  <button onClick={handleCreateOrder} disabled={isPaying} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black uppercase tracking-[0.3em] text-xs shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                     {isPaying ? <Loader2 className="w-5 h-5 animate-spin" /> : <>PEDIR A LA PARRILLA • ${formatPrice(cartTotal)}</>}
                  </button>
               </div>
             )}
          </div>
        </div>
      )}

      {/* Login Modal */}
      {showLogin && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-2xl z-[600] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] p-12 text-center shadow-2xl animate-in zoom-in duration-300">
             <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center mx-auto mb-8 text-slate-900 shadow-inner"><Lock className="w-8 h-8" /></div>
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ingresa PIN Staff</p>
             <input type="password" placeholder="••••" maxLength={4} className="w-full py-5 bg-slate-50 rounded-2xl text-center text-4xl font-black tracking-[0.8em] outline-none border border-slate-200 focus:border-orange-500 shadow-inner" autoFocus onChange={(e) => { if(e.target.value === '1234') { setIsStaffMode(true); setShowLogin(false); setActiveView('kitchen'); } }} />
             <button onClick={() => setShowLogin(false)} className="mt-8 text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-rose-500 transition-colors">Cancelar</button>
          </div>
        </div>
      )}

      {isAdminFormOpen && <AdminForm item={editingItem} categories={categories} onSave={async (d: any) => { if (d.id) await supabase.from('menu').upsert(d); else await supabase.from('menu').insert([d]); setIsAdminFormOpen(false); fetchData(); }} onClose={() => setIsAdminFormOpen(false)} />}
    </div>
  );
};

const SidebarItem = ({ icon, label, active, onClick, badge }: any) => (
  <button onClick={onClick} className={`relative w-full p-4 flex items-center gap-4 rounded-[1.5rem] transition-all group ${active ? 'bg-orange-600 text-white shadow-orange-glow' : 'text-white/40 hover:bg-white/5 hover:text-white'}`}>
    <div className={`transition-all ${active ? 'scale-110' : 'group-hover:scale-110'}`}>{icon}</div>
    <span className="text-[10px] font-black uppercase tracking-widest text-left truncate">{label}</span>
    {badge > 0 && <span className="absolute top-2 right-2 bg-white text-orange-600 text-[8px] font-black w-5 h-5 flex items-center justify-center rounded-lg shadow-lg">{badge}</span>}
  </button>
);

const AdminForm = ({ item, categories, onSave, onClose }: any) => {
  const [data, setData] = useState(item || { name: '', price: 0, category: categories[0]?.name || '', image: '', description: '' });
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleMagic = async () => {
    setIsAiLoading(true);
    const desc = await improveDescription(data.name);
    const img = await generateFoodImage(data.name);
    setData({ ...data, description: desc, image: img || data.image });
    setIsAiLoading(false);
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-2xl z-[300] flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-white w-full max-w-xl rounded-[2.5rem] p-10 shadow-2xl relative animate-in zoom-in duration-300">
        <h2 className="text-2xl font-black uppercase italic tracking-tighter mb-8">Gestionar Plato</h2>
        <div className="space-y-6">
          <input type="text" value={data.name} onChange={e => setData({...data, name: e.target.value})} placeholder="Nombre del plato..." className="w-full p-4 bg-slate-50 rounded-2xl font-black text-sm outline-none border border-slate-200" />
          <div className="grid grid-cols-2 gap-4">
            <input type="number" step="0.01" value={data.price} onChange={e => setData({...data, price: parseFloat(e.target.value) || 0})} placeholder="Precio..." className="p-4 bg-slate-50 rounded-2xl font-black text-sm outline-none border border-slate-200" />
            <select value={data.category} onChange={e => setData({...data, category: e.target.value})} className="p-4 bg-slate-50 rounded-2xl font-black text-xs outline-none border border-slate-200">{categories.map((c: any) => <option key={c.id} value={c.name}>{c.name}</option>)}</select>
          </div>
          <textarea value={data.description} onChange={e => setData({...data, description: e.target.value})} placeholder="Descripción gourmet..." className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs h-24 resize-none border border-slate-200" />
          <button onClick={handleMagic} disabled={isAiLoading || !data.name} className="w-full py-4 bg-orange-100 text-orange-600 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 hover:bg-orange-200 transition-all">
            {isAiLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />} Generar con IA
          </button>
          <div className="flex gap-4">
            <button onClick={() => onSave(data)} className="flex-1 py-5 bg-slate-900 text-white rounded-full font-black uppercase text-[10px] tracking-widest shadow-xl">Guardar</button>
            <button onClick={onClose} className="px-8 py-5 bg-slate-100 text-slate-400 rounded-full font-black uppercase text-[10px] tracking-widest">Cerrar</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
